source_text.data/entities/dwarves/traits.json:
{
  "__comment": [
    "Trait definitions for procedural dwarf generation.",
    "",
    "TRAIT SYSTEM:",
    "  Traits are permanent attributes assigned at dwarf generation time.",
    "  They cannot be gained or lost during play (except Homesick, which fades).",
    "  Each trait has a polarity (positive / negative) and a rarity weight",
    "  used when the generator selects which specific trait to assign.",
    "",
    "EFFECTS SCHEMA:",
    "  Each effect object has a 'type' field and type-specific parameters.",
    "  Effect types:",
    "    mood_baseline              — permanent additive delta to mood (float)",
    "    task_speed_modifier        — multiplier on all task durations (< 1.0 = faster)",
    "    experience_gain_multiplier — multiplier on task counts for a specific profession",
    "    enables_level_6            — unlocks experience level 6 for a specific profession",
    "    enables_future_profession  — reserves a profession unlock for when it is implemented",
    "    outdoor_mood_penalty       — mood delta applied while executing outdoor task types",
    "    sealed_room_mood_penalty   — mood delta applied while inside a sealed room with no sky",
    "    food_consumption_modifier  — multiplier on hunger drain rate",
    "    alcohol_dependency         — see field notes below",
    "    sleep_duration_modifier    — additional in-game hours of sleep required per cycle",
    "    damage_modifier            — multiplier on incoming damage (< 1.0 = more resistant)",
    "    crowd_mood_penalty         — mood delta when within range of crowd_threshold+ dwarves",
    "    homesick                   — temporary negative mood that fades; see field notes",
    "",
    "  alcohol_dependency fields:",
    "    required_interval_hours    — dwarf must consume alcohol within this window or penalty stacks",
    "    penalty_per_missed_interval— mood delta added each time the window expires without a drink",
    "    max_penalty_stacks         — maximum simultaneous stacks (mood floor from this trait alone)",
    "    bonus_multiplier           — multiplier on all alcohol-related thought magnitudes (drank_ale etc.)",
    "",
    "  homesick fields:",
    "    initial_penalty            — mood delta at arrival",
    "    fade_duration_days         — in-game days until effect is fully removed (linear fade)",
    "",
    "EXCLUSION GROUPS:",
    "  Traits in the same exclusion group cannot be assigned to the same dwarf.",
    "  The generator checks exclusions before finalising each trait slot."
  ],

  "generation_config": {
    "__comment": [
      "Weights for how many trait slots a dwarf receives at generation.",
      "Rolls are weighted: total all weights, pick a random value, find the matching bucket.",
      "When multiple slots are assigned, the generator fills positive slots from the",
      "positive pool and negative slots from the negative pool independently.",
      "'two_positive_one_negative' dwarves are the rarest and most valuable."
    ],
    "no_traits":               35,
    "one_negative":            30,
    "one_positive":            20,
    "one_positive_one_negative": 10,
    "two_positive":             4,
    "two_positive_one_negative": 1
  },

  "exclusion_groups": {
    "outdoor_preference": ["base:trait:hates_the_outdoors", "base:trait:cave_sick"],
    "mood_baseline":      ["base:trait:cheerful", "base:trait:grumpy"],
    "work_pace":          ["base:trait:hardworking", "base:trait:lazy"],
    "sleep_pattern":      ["base:trait:deep_sleeper", "base:trait:light_sleeper"],
    "social_preference":  ["base:trait:social", "base:trait:loner"]
  },

  "traits": {

    "__comment_calling": "Calling traits — grant +50% experience gain and unlock profession level 6.",

    "base:trait:born_miner": {
      "display_name": "Born Miner",
      "description": "Tunnels feel like home. This dwarf reads rock grain by instinct — fewer wasted swings, richer finds.",
      "polarity": "positive",
      "rarity_weight": 15,
      "effects": [
        { "type": "experience_gain_multiplier", "profession": "base:profession:miner", "value": 1.5 },
        { "type": "enables_level_6",            "profession": "base:profession:miner" }
      ]
    },

    "base:trait:brewmasters_intuition": {
