class_name ContainerStorageComponent
extends StorageComponent

const ITEM_LAYOUT = preload("res://scripts/components/StorageItemLayout.gd")

## Container storage (doc 19 §3.5) — the density face of the storage
## contract: capacity SLOTS behind one piece of installed furniture (barrel
## 8, chest 24, shelf 8). Deposit tokens are int slot tickets; counts live
## in a flat inventory Dictionary (item_key -> count, flat item count — SH
## parity, decision 6).
##
## VISUALS (the WYSIWYG split, doc 19 §3.0.5): render_contents false (barrel,
## chest) ABSORBS the deposited node — the window shows counts; true (shelf)
## renders items on the def's anchor points, fitted to optional slot bounds.
##
## Owned by FurniturePlacementController (attached to the piece's
## InstalledFurnitureComponent); registered with StockpileManager like a
## zone. Withdraw spawns the item back into the world pre-reserved for the
## fetching dwarf (containers hold counts, not nodes).

var capacity: int = 8
var render_contents: bool = false
var inventory: Dictionary = {}       # item_key (String) -> count (int)
var cells: Array[Vector3i] = []      # the installed piece's footprint floor cells
var suspended: bool = false          # 📤 flagged — stop accepting (doc 19 §3.4)

# ── Anchor rendering (doc 19 Phase 5 — SH ATTITEM parity) ─────────────────────
var display_parent: Node3D = null    # the installed piece's visual node
var anchors: Array = []              # local block offsets from data/furniture JSON
var anchor_scale: float = 0.5        # maximum display scale; optional slot bounds may shrink an item
var anchor_max_size := Vector3.ZERO # optional per-slot envelope; zero keeps legacy sizing

var _reserved_slots: int = 0
var _anchor_slots: Array = []        # per-anchor: null | [node: Node3D, item_key: String]


func setup_container(def: Dictionary, footprint_cells: Array[Vector3i]) -> void:
	var storage: Dictionary = def.get("storage", {})
	capacity = int(storage.get("capacity", 8))
	render_contents = bool(storage.get("render_contents", false))
	anchors = storage.get("anchors", [])
	anchor_scale = float(storage.get("anchor_scale", 0.5))
	var size: Array = storage.get("anchor_max_size", [])
	anchor_max_size = Vector3(float(size[0]), float(size[1]), float(size[2])) if size.size() == 3 else Vector3.ZERO
	cells = footprint_cells
	filter_tags = StockpileZoneComponent.DEFAULT_FILTER_TAGS.duplicate()
	_anchor_slots.resize(anchors.size())


func stored_count() -> int:
	var total: int = 0
	for key: String in inventory:
		total += int(inventory[key])
	return total


func restore_inventory(saved: Dictionary, item_manager: Node) -> void:
	inventory.clear()
	_reserved_slots = 0
	drop_manager = item_manager
	var remaining := capacity
	for item_key in saved:
		var count := clampi(int(saved[item_key]), 0, remaining)
		if count <= 0:
			continue
		inventory[String(item_key)] = count
		remaining -= count
		if render_contents and item_manager != null \
				and item_manager.has_method("create_item_visual"):
			for _i in range(count):
				var node: Node3D = item_manager.call("create_item_visual", String(item_key))
				if node != null:
					_place_visual(node, null)
		if remaining <= 0:
			break


# ── Storage contract (doc 19 §3.5 — the abstract surface) ─────────────────────

func _has_any_room() -> bool:
	if suspended:
		return false
	return stored_count() + _reserved_slots < capacity


func _reserve_deposit(_item_key: String, _near: Vector3i, _dwarf_id: int) -> Variant:
	if not _has_any_room():
		return null
	_reserved_slots += 1
	return _reserved_slots   # int ticket (never null; value is opaque)


func _release_deposit(_token: Variant) -> void:
	_reserved_slots = maxi(_reserved_slots - 1, 0)


func _commit_one(_token: Variant, item_key: String) -> void:
	_reserved_slots = maxi(_reserved_slots - 1, 0)
	inventory[item_key] = int(inventory.get(item_key, 0)) + 1


func _deposit_walk_target(_first_token: Variant) -> Vector3i:
	return nearest_stand_target(Vector3i.ZERO)


## Barrel/chest ABSORB the node; the shelf snaps it onto a free anchor
## (doc 19 Phase 5, art doc 41: scale up to 0.5, varied yaw, fitted slot bounds).
## Anchors are footprint-local block coords (origin = bottom-front-left);
## as children of the rotated piece node they follow its yaw for free, and
## slice culling rides the parent's visibility.
func _place_visual(node: Node3D, _token: Variant) -> void:
	if node == null or not is_instance_valid(node):
		return
	if not render_contents or display_parent == null or not is_instance_valid(display_parent):
		node.queue_free()
		return
	var slot := _free_anchor_slot()
	if slot < 0:
		node.queue_free()   # capacity > anchors would land here — WYSIWYG says never
		return
	var key := String(node.get_meta("item_key", ""))
	if node.get_parent() != null:
		node.get_parent().remove_child(node)
	display_parent.add_child(node)
	var fp_w := 1.0
	var fp_d := 1.0
	var offset: Array = anchors[slot]
	node.position = Vector3(
		float(offset[0]) - fp_w * 0.5,
		float(offset[1]),
		float(offset[2]) - fp_d * 0.5)
	node.scale = Vector3.ONE * anchor_scale
	# Varied per-anchor yaw (SH's scattered hand-placed look) — deterministic.
	node.rotation = Vector3(0.0, float(slot * 2654435761 % 628) / 100.0, 0.0)
	ITEM_LAYOUT.fit(node, anchor_max_size, anchor_scale)
	node.visible = true
	_anchor_slots[slot] = [node, key]


func _free_anchor_slot() -> int:
	for i: int in range(_anchor_slots.size()):
		if _anchor_slots[i] == null:
			return i
	return -1


## Frees one anchored node of `item_key` (shelf withdraw/dump bookkeeping).
func _pop_anchor_node(item_key: String) -> bool:
	for i: int in range(_anchor_slots.size()):
		var entry: Variant = _anchor_slots[i]
		if entry != null and String((entry as Array)[1]) == item_key:
			var node: Node3D = (entry as Array)[0]
			if node != null and is_instance_valid(node):
				node.queue_free()
			_anchor_slots[i] = null
			return true
	return false


## Nearest walkable cell bordering the footprint (the footprint itself is
## occupied — the InstalledFurnitureComponent pattern).
func nearest_stand_target(dwarf_cell: Vector3i) -> Vector3i:
	var best := Vector3i(-1, -1, -1)
	var best_dist: int = 0x7FFFFFFF
	for cell: Vector3i in cells:
		for offset: Vector3i in [Vector3i(1, 0, 0), Vector3i(-1, 0, 0), Vector3i(0, 0, 1), Vector3i(0, 0, -1)]:
			var stand := cell + offset
			if not NavGrid.is_walkable(stand):
				continue
			var d := stand - dwarf_cell
			var dist := absi(d.x) + absi(d.y) + absi(d.z)
			if dist < best_dist:
				best = stand
				best_dist = dist
	return best


# ── Withdraw (doc 19 §3.3 fetch path) ─────────────────────────────────────────

## Containers hold counts, not nodes: withdrawing spawns the item back into
## the world at the stand cell, pre-reserved for the fetching dwarf.
func withdraw_nearest(item_key: String, _near: Vector3i, dwarf_id: int) -> Node3D:
	if int(inventory.get(item_key, 0)) <= 0:
		return null
	if drop_manager == null or not is_instance_valid(drop_manager):
		return null
	var stand := nearest_stand_target(Vector3i.ZERO)
	if stand.x < 0:
		return null
	var node: Node3D = drop_manager.call("spawn_reserved", item_key, stand, dwarf_id)
	if node == null:
		return null
	if render_contents:
		_pop_anchor_node(item_key)   # the shelf visibly loses the piece
	inventory[item_key] = int(inventory[item_key]) - 1
	if int(inventory[item_key]) <= 0:
		inventory.erase(item_key)
	if changed_callback.is_valid():
		changed_callback.call(item_key, -1)
	return node


## Uninstall teardown (doc 19 §3.4 step 2): every stored item re-enters the
## world as an ordinary loose drop at the container's cell. Returns the
## dumped total (build-log verification).
func dump_contents(at_cell: Vector3i) -> int:
	if drop_manager == null or not is_instance_valid(drop_manager):
		return 0
	# Shelf: clear the anchored visuals first (counts respawn as drops below).
	for i: int in range(_anchor_slots.size()):
		var entry: Variant = _anchor_slots[i]
		if entry != null:
			var node: Node3D = (entry as Array)[0]
			if node != null and is_instance_valid(node):
				node.queue_free()
			_anchor_slots[i] = null
	var dumped := 0
	for item_key: String in inventory.keys():
		var count := int(inventory[item_key])
		if count > 0:
			drop_manager.call("spawn_drop", item_key, count, Vector3i(at_cell.x, at_cell.y + 1, at_cell.z))
			if changed_callback.is_valid():
				changed_callback.call(item_key, -count)
			dumped += count
	inventory.clear()
	return dumped

source_text.scripts/components/FurnitureGhostCompone:
class_name FurnitureGhostComponent
extends RefCounted

## A placed-but-unbuilt furniture designation (doc 19 §3.2–3.3) — the SH
## ghost form translated: a translucent placed-form marker that persists in
## the world as a standing request until a dwarf fetches the matching item
## and installs it.
##
## Phase 3 made this a WORK SOURCE (the fifth lease family): the ghost posts
## ONE FETCH_BUILD lease, and only while a matching item is AVAILABLE — loose
## and unreserved, or stored in colony storage (type-matched, SH parity: any
## item of the URI satisfies the ghost). The fetching dwarf pulls via
## reserve_fetch (loose first, else a storage withdraw), carries the item to
## the ghost's stand cell, works the build timer, and complete_build hands
## off to the controller's shared _install path.
##
## Ghosts are NON-SOLID (SH parity): no PlacedEntityRegistry registration,
## no nav impact — nav changes only when the piece is actually installed.
## Owned by FurniturePlacementController (the zone/mining ownership shape).
##
## ITEM CLAIMS (2026-08-07, Alen playtest — the HAUL/FETCH_BUILD item race):
## task priority (FETCH_BUILD 45 > HAUL 40) orders ASSIGNMENT, but the
## physical item had none — a stockpile hauler could pouch the last matching
## loose item, and while it rode the pouch item_available() was false, so the
## ghost had NO lease and idle dwarves stood around until the deposit wake
## (then walked to the zone and all the way back). SH restock parity: an item
## pending placement is never restocked. The ghost now CLAIMS the nearest
## matching loose item the moment one exists (wake-driven, like the lease):
## a claim is an ItemDropManager reservation under claim_owner_id(), so every
## hauler scan (unreserved-only) skips it. reserve_fetch hands the claim to
## the fetching dwarf; cancel_fetch re-claims on release; the controller
## releases the claim on ghost teardown. Items already inside a pouch when
## the ghost is placed remain the residual (unavoidable) delay: they become
## claimable only after the hauler deposits or drops them.

var ghost_id: int = -1
var furniture_key: String = ""      # base:furniture:* (namespaced — Hard Rule 3)
var item_key: String = ""           # the resources.json item form to fetch
var def: Dictionary = {}            # parsed data/furniture/*.json definition
var origin_cell: Vector3i = Vector3i(-1, -1, -1)   # footprint min-corner FLOOR cell
var yaw_steps: int = 0              # 0..3 — 90° each (R key)
var node: Node3D = null             # translucent in-world marker (controller-owned)

# ── Work-source state (doc 19 Phase 3 — injected by the controller) ───────────
var source_id: int = -1             # TaskManager.allocate_source_id()
var drop_manager: Node3D = null     # ItemDropManager (guard is_instance_valid)
var install_callback: Callable = Callable()   # (ghost) -> controller install path
var build_valid_callback: Callable = Callable() # support check before consuming item

var _lease_id: int = -1             # the ONE FETCH_BUILD lease, -1 = none
var _fetches: Dictionary = {}       # dwarf_id -> Node3D (reserved item, pre-pickup)
var _claim: Node3D = null           # ghost-held item claim (see header) — runtime only, never saved


func setup(id: int, key: String, definition: Dictionary, cell: Vector3i, yaw: int) -> void:
	ghost_id = id
	furniture_key = key
	def = definition
	item_key = String(definition.get("item_key", ""))
	origin_cell = cell
	yaw_steps = yaw


## Floor cells covered by the footprint (v1 pieces are all 1×1; width/depth
## swap under odd yaw steps so the math stays correct for future 2×1 pieces).
func footprint_cells() -> Array[Vector3i]:
	if String(def.get("placement", "floor")) == "wall":
		return []
	var fp: Dictionary = def.get("footprint", {})
	var w := int(fp.get("width", 1))
	var d := int(fp.get("depth", 1))
	if yaw_steps % 2 == 1:
		var t := w
		w = d
		d = t
	var cells: Array[Vector3i] = []
	for dx: int in range(w):
		for dz: int in range(d):
			cells.append(origin_cell + Vector3i(dx, 0, dz))
	return cells


func display_name() -> String:
	return String(def.get("display_name", furniture_key))


# ── Work source (doc 19 §3.3) ─────────────────────────────────────────────────

## Owner id for the ghost's item claim in ItemDropManager's reservation
## table. POSITIVE and far outside the dwarf-id range, so unreserve()'s
## owner guard stays effective (a negative id would read as "unconditional"
## there). source_id comes from TaskManager.allocate_source_id() (>= 10M),
## so claim owners live at >= 1_010_000_000 — no dwarf id ever collides.
func claim_owner_id() -> int:
	return 1_000_000_000 + source_id


func _claim_valid() -> bool:
	return _claim != null and is_instance_valid(_claim)


## A matching item exists somewhere the fetch can reach it: claimed by this
## ghost, loose and unreserved, or stored in colony storage (aggregates).
func item_available() -> bool:
	if _claim_valid():
		return true
	if StockpileManager.get_total(item_key) > 0:
		return true
	if drop_manager == null or not is_instance_valid(drop_manager):
		return false
	return drop_manager.call("nearest_loose_of_key", item_key, origin_cell, {}) != null


## Posts/retires the single FETCH_BUILD lease, and keeps the item claim
## current (see header — the claim is what stops haulers pouching the item
## out from under a pending lease). Called by the controller on wake events
## (drop spawned, stockpile changed, ghost placed) — never per frame
## (doc 16 §2.5 discipline).
func update_lease() -> void:
	if source_id < 0:
		return
	_ensure_claim()
	if _lease_id < 0 and item_available():
		_lease_id = int(TaskManager.add_task(
			Task.Type.FETCH_BUILD, origin_cell, { "ghost_id": ghost_id }, source_id))


## Claim the nearest matching loose item if we hold none and no fetching
## dwarf already owns one for this ghost. Claimed = reserved under
## claim_owner_id(), invisible to every unreserved-only scan (haul pouches,
## other ghosts' claims and fetches).
func _ensure_claim() -> void:
	if not _fetches.is_empty():
		return                        # a dwarf already holds an item for this ghost
	if _claim_valid():
		return
	_claim = null
	if drop_manager == null or not is_instance_valid(drop_manager):
		return
	var item: Node3D = drop_manager.call("nearest_loose_of_key", item_key, origin_cell, {})
	if item != null and bool(drop_manager.call("reserve", item, claim_owner_id())):
		_claim = item


## Frees the ghost's item claim (owner-guarded). Controller calls this on
## ghost teardown (cancel / build-complete); safe to call with no claim.
func release_claim() -> void:
	if _claim != null and is_instance_valid(_claim) \
			and drop_manager != null and is_instance_valid(drop_manager):
		drop_manager.call("unreserve", _claim, claim_owner_id())
	_claim = null


func has_lease() -> bool:
	return _lease_id >= 0


## The lease left the system FOR GOOD (completed / cancelled / failed) —
## NOT on releases (a released lease returns to PENDING and stays counted).
func on_task_gone(task_id: int, dwarf_id: int) -> void:
	if task_id == _lease_id:
		_lease_id = -1
	if dwarf_id >= 0:
		cancel_fetch(dwarf_id)


## Scheduler probe / builder stand target: the nearest walkable cell BESIDE
## the footprint — NEVER the footprint itself. DEFECT FIX (Alen, 2026-07-11):
## the first cut returned origin_cell; the builder stood ON the ghost, the
## install registered occupancy around them, and the trapped dwarf's every
## subsequent probe failed — each install silently ate a worker until the
## whole crew stood frozen inside furniture. Build from beside, like mining.
func nearest_stand_target(dwarf_cell: Vector3i) -> Vector3i:
	if String(def.get("placement", "floor")) == "wall":
		return preload("res://scripts/components/WallFurnitureMount.gd").nearest_stand(origin_cell, dwarf_cell)
	var best := Vector3i(-1, -1, -1)
	var best_dist: int = 0x7FFFFFFF
	for cell: Vector3i in footprint_cells():
		for offset: Vector3i in [Vector3i(1, 0, 0), Vector3i(-1, 0, 0), Vector3i(0, 0, 1), Vector3i(0, 0, -1)]:
			var stand := cell + offset
			if _cell_in_footprint(stand):
				continue
			if not NavGrid.is_walkable(stand):
				continue
			var d := stand - dwarf_cell
			var dist := absi(d.x) + absi(d.y) + absi(d.z)
			if dist < best_dist:
				best = stand
				best_dist = dist
	return best


func _cell_in_footprint(cell: Vector3i) -> bool:
	for fp_cell: Vector3i in footprint_cells():
		if fp_cell == cell:
			return true
	return false


## Step 1 of the fetch (doc 19 §3.3): hand over the ghost's claim if it
## holds one (claimed items are reserved, so the unreserved-only scan below
## would never find them) — else the nearest matching loose item, else a
## storage withdraw. {} = nothing available (the lease completes early and
## re-posts on the next wake).
func reserve_fetch(dwarf_id: int, dwarf_cell: Vector3i) -> Dictionary:
	if drop_manager == null or not is_instance_valid(drop_manager):
		return {}
	var item: Node3D = null
	if _claim_valid():
		# Transfer the claim to the fetching dwarf (owner-guarded swap).
		item = _claim
		_claim = null
		drop_manager.call("unreserve", item, claim_owner_id())
		if not bool(drop_manager.call("reserve", item, dwarf_id)):
			item = null
	if item == null:
		item = drop_manager.call("nearest_loose_of_key", item_key, dwarf_cell, {})
		if item != null:
			if not bool(drop_manager.call("reserve", item, dwarf_id)):
				item = null
	if item == null:
		item = StockpileManager.withdraw_item(item_key, dwarf_cell, dwarf_id)
	if item == null:
		return {}
	_fetches[dwarf_id] = item
	var item_def: Dictionary = drop_manager.call("get_item_def", item_key)
	return {
		"item": item,
		"heavy": String(item_def.get("weight_class", "light")) == "heavy",
	}


## Release protocol: frees the item reservation (owner-guarded — doc 18
## spam-robustness pass). Safe to call twice; a carried item is the dwarf's
## to drop at its feet (Hard Rule 12), not ours to unreserve. The freed item
## is immediately RE-CLAIMED for the ghost so a hauler cannot poach it in
## the gap before the next lease wake.
func cancel_fetch(dwarf_id: int) -> void:
	if not _fetches.has(dwarf_id):
		return
	var item: Node3D = _fetches[dwarf_id]
	_fetches.erase(dwarf_id)
	if item != null and is_instance_valid(item) \
			and drop_manager != null and is_instance_valid(drop_manager):
		drop_manager.call("unreserve", item, dwarf_id)
		if not _claim_valid() and bool(drop_manager.call("reserve", item, claim_owner_id())):
			_claim = item


## The dwarf picked the item up — it left the loose index; our reservation
## bookkeeping for it is done.
func notify_picked_up(dwarf_id: int) -> void:
	_fetches.erase(dwarf_id)


## Step 4: the build swing finished — hand off to the controller's shared
## install path (the same _install the DEV button uses).
func complete_build(_dwarf_id: int) -> void:
	if install_callback.is_valid():
		install_callback.call(self)


func can_complete_build() -> bool:
	return not build_valid_callback.is_valid() or bool(build_valid_callback.call(self))

source_text.scripts/components/InstalledFurnitureCom:
class_name InstalledFurnitureComponent
extends RefCounted

## An installed furniture piece (doc 19 §3.4) — occupancy-registered, solid,
## and a WORK SOURCE for its own removal: the 📤 flag is a TOGGLE (SH
## should_restock parity) that posts ONE UNINSTALL lease; clicking 📤 again
## clears flag and lease, leaving the piece untouched. The uninstalling
## dwarf walks to the stand cell, works the timer, and complete_uninstall
## hands off to the controller's teardown (contents dumped loose, occupancy
## freed, the packed item-form drop spawned — everything re-enters ordinary
## hauling).
##
## Phase 4 attaches the ContainerStorageComponent to pieces whose def
## carries a `storage` block; this component stays the placement/lifecycle
## half. Owned by FurniturePlacementController.

var installed_id: int = -1
var furniture_key: String = ""
var item_key: String = ""
var def: Dictionary = {}
var origin_cell: Vector3i = Vector3i(-1, -1, -1)
var yaw_steps: int = 0
var node: Node3D = null              # solid in-world visual (controller-owned)
var occupancy_ids: Array[int] = []   # PlacedEntityRegistry handles
var cells: Array[Vector3i] = []      # footprint floor cells

# ── Work-source state (doc 19 §3.4 — injected by the controller) ──────────────
var source_id: int = -1
var flagged_uninstall: bool = false
var uninstall_callback: Callable = Callable()   # (component) -> controller teardown

var storage: ContainerStorageComponent = null   # doc 19 Phase 4 — set for storage pieces

var _lease_id: int = -1              # the ONE UNINSTALL lease, -1 = none


func setup(id: int, key: String, definition: Dictionary, cell: Vector3i, yaw: int) -> void:
	installed_id = id
	furniture_key = key
	def = definition
	item_key = String(definition.get("item_key", ""))
	origin_cell = cell
	yaw_steps = yaw


func display_name() -> String:
	return String(def.get("display_name", furniture_key))


## 📤 toggle (SH parity). Posting/cancelling the lease happens here — the
## flag and the lease can never disagree.
func set_uninstall(flag: bool) -> void:
	if flag == flagged_uninstall:
		return
	flagged_uninstall = flag
	# A flagged container stops accepting deposits and cancels live haul
	# leases (doc 19 §3.4); un-flagging resumes.
	if storage != null:
		storage.suspended = flag
		if flag and storage.source_id >= 0:
			TaskManager.cancel_source_tasks(storage.source_id)
	if flag:
		if _lease_id < 0 and source_id >= 0:
			_lease_id = int(TaskManager.add_task(
				Task.Type.UNINSTALL, origin_cell, { "installed_id": installed_id }, source_id))
	else:
		if _lease_id >= 0:
			TaskManager.cancel_task(_lease_id)
			_lease_id = -1


func on_task_gone(task_id: int, _dwarf_id: int) -> void:
	if task_id == _lease_id:
		_lease_id = -1
		# Lease died without completing (cancel/fail while flagged): re-post
		# so the flag keeps meaning "will be uninstalled" (toggle clears it).
		if flagged_uninstall and source_id >= 0:
			_lease_id = int(TaskManager.add_task(
				Task.Type.UNINSTALL, origin_cell, { "installed_id": installed_id }, source_id))


## Scheduler probe target / dwarf walk target: the nearest walkable cell
## bordering the footprint (the footprint itself is occupied once installed).
func nearest_stand_target(dwarf_cell: Vector3i) -> Vector3i:
	if String(def.get("placement", "floor")) == "wall":
		return preload("res://scripts/components/WallFurnitureMount.gd").nearest_stand(origin_cell, dwarf_cell)
	var best := Vector3i(-1, -1, -1)
	var best_dist: int = 0x7FFFFFFF
	for cell: Vector3i in cells:
		for offset: Vector3i in [Vector3i(1, 0, 0), Vector3i(-1, 0, 0), Vector3i(0, 0, 1), Vector3i(0, 0, -1)]:
			var stand := cell + offset
			if not NavGrid.is_walkable(stand):
				continue
			var d := stand - dwarf_cell
			var dist := absi(d.x) + absi(d.y) + absi(d.z)
			if dist < best_dist:
				best = stand
				best_dist = dist
	return best


## The uninstall swing finished — hand off to the controller's teardown.
func complete_uninstall(_dwarf_id: int) -> void:
	if uninstall_callback.is_valid():
		uninstall_callback.call(self)

