class_name DwarfFactory
extends RefCounted

## Procedural dwarf generation (doc 41 §Dwarf Generation, doc 41b).
##
## All rolls are DETERMINISTIC (Hard Rule 8 applied to the roster, per doc 41):
## one RandomNumberGenerator seeded from (world_seed, birth_index) per dwarf,
## so the same world always produces the same sequence of dwarves. Never call
## global randi()/randf() here.
##
## DwarfFactory generates DATA. Scene assembly lives on DwarfAgent.setup() —
## the factory's spawn helper just instantiates the agent and hands the data
## over. Pools come from the DwarfAssets autoload (the owning registry for
## names/appearance/traits JSON).

const WORKER_KEY := "base:profession:worker"

## Profession keys initialised on every new dwarf (doc 41 §Agent Fields).
## Must stay aligned with data/professions/professions.json (drift fixed
## 2026-08-07: carpenter was missing here while present in the JSON;
## weaponsmith/armorsmith stubs were added to the JSON — docs 41/44 define
## them as Blacksmith Level 3 promotions, so their keys belong in every
## dwarf's experience dict from day one; promotion copies the blacksmith
## count into them, doc 44 §Experience Carry-Over).
const PROFESSION_KEYS: Array[String] = [
	"base:profession:worker",
	"base:profession:miner",
	"base:profession:farmer",
	"base:profession:brewer",
	"base:profession:builder",
	"base:profession:merchant",
	"base:profession:innkeeper",
	"base:profession:carpenter",
	"base:profession:blacksmith",
	"base:profession:weaponsmith",
	"base:profession:armorsmith",
]


## Rolls one dwarf's full data set. (Instance method, not static: autoload
## access — WorldGenerator, DwarfAssets — is unreliable from static functions;
## callers hold a DwarfFactory.new() instance.)
##   birth_index — 0-based roster position in this world (drives the seed)
##   used_names  — Dictionary[String -> true] of names already assigned;
##                 mutated: the chosen name is added.
## Returns: { name, gender, appearance: DwarfAppearanceData,
##            traits: Array[String], profession, profession_experience }
func generate(birth_index: int, used_names: Dictionary) -> Dictionary:
	var rng := RandomNumberGenerator.new()
	rng.seed = _dwarf_seed(WorldGenerator.world_seed, birth_index)

	var gender := "male" if rng.randf() < 0.5 else "female"
	var dwarf_name := _roll_name(gender, birth_index, used_names, rng)
	var appearance := _roll_appearance(gender, rng)
	var traits := _roll_traits(rng)

	var experience := {}
	for key in PROFESSION_KEYS:
		experience[key] = 0
	# Workers start with a small random task count so new arrivals aren't all
	# identical level-1 dwarves (doc 41).
	experience[WORKER_KEY] = rng.randi_range(0, 9)

	return {
		"name": dwarf_name,
		"gender": gender,
		"appearance": appearance,
		"traits": traits,
		"profession": WORKER_KEY,
		"profession_experience": experience,
	}


## Instantiates a DwarfAgent for already-rolled data. The caller adds it to the
## tree and positions it.
func spawn(data: Dictionary, dwarf_id: int) -> DwarfAgent:
	var agent := DwarfAgent.new()
	agent.setup(dwarf_id, data)
	return agent


# ── Seed mixing ───────────────────────────────────────────────────────────────

static func _dwarf_seed(world_seed: int, birth_index: int) -> int:
	var h := int(world_seed) * 2654435761 + 0x9E3779B9
	h ^= (birth_index + 1) * 83492791
	h ^= (h >> 13)
	h *= 1274126177
	h ^= (h >> 16)
	return h


# ── Name (doc 41: prefix + suffix; re-roll on collision; Roman fallback) ──────

func _roll_name(gender: String, birth_index: int,
		used_names: Dictionary, rng: RandomNumberGenerator) -> String:
	var pools: Dictionary = DwarfAssets.get_name_pools().get(gender, {})
	var prefixes: Array = pools.get("prefixes", [])
	var suffixes: Array = pools.get("suffixes", [])
	if prefixes.is_empty() or suffixes.is_empty():
		return "Dwarf %d" % (birth_index + 1)

	var candidate := ""
	for _attempt in range(10):
		candidate = String(prefixes[rng.randi_range(0, prefixes.size() - 1)]) \
			+ String(suffixes[rng.randi_range(0, suffixes.size() - 1)])
		if not used_names.has(candidate):
			used_names[candidate] = true
			return candidate
	# Pool effectively exhausted (~500 same-gender dwarves): Roman-numeral
	# birth-order fallback, expected never in normal play (doc 41).
	candidate = "%s %s" % [candidate, _roman(birth_index + 1)]
	used_names[candidate] = true
	return candidate


static func _roman(n: int) -> String:
	var vals := [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
	var syms := ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
	var out := ""
	var v := n
	for i in vals.size():
		while v >= vals[i]:
			out += syms[i]
			v -= vals[i]
	return out


# ── Appearance (doc 41 §Appearance Generation) ───────────────────────────────

func _roll_appearance(gender: String, rng: RandomNumberGenerator) -> DwarfAppearanceData:
	var pools: Dictionary = DwarfAssets.get_appearance_pools()
	var shared: Dictionary = pools.get("shared", {})
	var gendered: Dictionary = pools.get(gender, {})

	var a := DwarfAppearanceData.new()
	a.gender = gender
	a.skin_tone = _weighted_id(shared.get("skin_tone", []), rng, "medium")
	a.eye_color = _weighted_id(shared.get("eye_color", []), rng, "grey")
	a.hair_color = _weighted_id(shared.get("hair_color", []), rng, "brown")
	a.age_tier = _weighted_id(shared.get("age_tier", []), rng, "adult")
	a.scar = _weighted_id(shared.get("scar", []), rng, "none")
	a.hair_style = _weighted_id(gendered.get("hair_style", []), rng,
		"short_back" if gender == "male" else "bun")
	a.eyebrow_style = _weighted_id(gendered.get("eyebrow_style", []), rng, "thick_flat")

	a.beard_style = ""
	if gender == "male":
		var beard: Dictionary = gendered.get("beard", {})
		if rng.randf() < float(beard.get("beard_probability", 0.85)):
			a.beard_style = _weighted_id(beard.get("styles", []), rng, "full_long")
	return a


## Weighted pick over an array of { id, weight (default 1) } entries.
static func _weighted_id(options: Array, rng: RandomNumberGenerator, fallback: String) -> String:
	var total := 0.0
	for opt in options:
		if opt is Dictionary:
			total += float((opt as Dictionary).get("weight", 1.0))
	if total <= 0.0:
		return fallback
	var r := rng.randf() * total
	var acc := 0.0
	for opt in options:
		if not (opt is Dictionary):
			continue
		acc += float((opt as Dictionary).get("weight", 1.0))
		if r <= acc:
			return String((opt as Dictionary).get("id", fallback))
	return fallback


# ── Traits (doc 41 §Trait Assignment) ────────────────────────────────────────

func _roll_traits(rng: RandomNumberGenerator) -> Array[String]:
	var data: Dictionary = DwarfAssets.get_trait_data()
	var config: Dictionary = data.get("generation_config", {})
	var all_traits: Dictionary = data.get("traits", {})

	# 1. Slot distribution (weighted bucket roll).
	var buckets := {
		"no_traits": Vector2i(0, 0),                 # (positive, negative) slots
		"one_negative": Vector2i(0, 1),
		"one_positive": Vector2i(1, 0),
		"one_positive_one_negative": Vector2i(1, 1),
		"two_positive": Vector2i(2, 0),
		"two_positive_one_negative": Vector2i(2, 1),
	}
	var total := 0.0
	for key in buckets:
		total += float(config.get(key, 0))
	var slots := Vector2i.ZERO
	if total > 0.0:
		var r := rng.randf() * total
		var acc := 0.0
		for key in buckets:
			acc += float(config.get(key, 0))
			if r <= acc:
				slots = buckets[key]
				break

	# 2. Split pools by polarity (deterministic iteration: sorted keys).
	var positive: Array[String] = []
	var negative: Array[String] = []
	var keys := all_traits.keys()
	keys.sort()
	for key in keys:
		if String(key).begins_with("__"):
			continue
		var def: Dictionary = all_traits[key]
		if String(def.get("polarity", "")) == "positive":
			positive.append(String(key))
		elif String(def.get("polarity", "")) == "negative":
			negative.append(String(key))

	# 3. Fill slots, honouring exclusion groups (re-roll from the remaining
	#    eligible pool on conflict — doc 41).
	var chosen: Array[String] = []
	var used_groups: Dictionary = {}
	for _i in range(slots.x):
		_fill_trait_slot(positive, all_traits, chosen, used_groups, rng)
	for _i in range(slots.y):
		_fill_trait_slot(negative, all_traits, chosen, used_groups, rng)
	return chosen


static func _fill_trait_slot(pool: Array[String], all_traits: Dictionary,
		chosen: Array[String], used_groups: Dictionary, rng: RandomNumberGenerator) -> void:
	var eligible: Array[String] = []
	var weights: Array[float] = []
	var total := 0.0
	for key in pool:
		if key in chosen:
			continue
		var def: Dictionary = all_traits[key]
		var group := String(def.get("exclusion_group", ""))
		if group != "" and used_groups.has(group):
			continue
		var w := float(def.get("rarity_weight", 1.0))
		eligible.append(key)
		weights.append(w)
		total += w
	if eligible.is_empty() or total <= 0.0:
		return
	var r := rng.randf() * total
	var acc := 0.0
	for i in eligible.size():
		acc += weights[i]
		if r <= acc:
			var key := eligible[i]
			chosen.append(key)
			var group := String((all_traits[key] as Dictionary).get("exclusion_group", ""))
			if group != "":
				used_groups[group] = true
			return

source_text.scripts/registries/BlockRegistry.gd:
extends Node

# ── File paths ────────────────────────────────────────────────────────────────
const BLOCKS_PATH    := "res://data/terrain/terrain_blocks.json"
const PALETTES_PATH  := "res://data/terrain/surface_palettes.json"
const RESOURCES_PATH := "res://data/terrain/block_resources.json"

# ── Internal tables ───────────────────────────────────────────────────────────
# Keys with "__" prefix in the JSON are documentation comments — always skipped.
#
# Runtime integer IDs are session-local array indices. They must NEVER be written
# to save files. Save files always store the full namespaced StringName key.

var _key_to_id:        Dictionary = {}   # StringName  →  int
var _id_to_key:        Array      = []   # int         →  StringName
var _id_to_def:        Array      = []   # int         →  Dictionary (full block def)
var _surface_palettes: Dictionary = {}   # variant_suffix  →  { season: Color }
var _resource_defs:    Dictionary = {}

# Hot-path lookup tables (doc 11 Phase 1d). Built EAGERLY in _ready and never
# mutated afterwards, so WorkerThreadPool mesh builders can read them without
# any locking. get_color() / is_transparent() stay as the general API; these
# LUTs are the per-block fast path for the mesher's inner loops.
var _color_luts:      Dictionary      = {}   # season → PackedColorArray (runtime-id-indexed)
var _transparent_lut: PackedByteArray = PackedByteArray()   # runtime id → 1 if transparent

const _LUT_SEASONS := ["spring", "summer", "autumn", "winter"]

## Runtime ID of "base:terrain:void" — the zero/air value used everywhere.
## Set after _load_blocks() completes.
var AIR_ID: int = 0


func _ready() -> void:
	_load_blocks()
	_load_palettes()
	_load_resource_defs()
	AIR_ID = get_id(&"base:terrain:void")
	_build_luts()
	print("BlockRegistry: loaded %d block types." % _id_to_key.size())


func _build_luts() -> void:
	var count := _id_to_key.size()
	_transparent_lut.resize(count)
	for id in range(count):
		_transparent_lut[id] = 1 if is_transparent(id) else 0
	_color_luts.clear()
	for season: String in _LUT_SEASONS:
		var lut := PackedColorArray()
		lut.resize(count)
		for id in range(count):
			lut[id] = get_color(id, season)
		_color_luts[season] = lut


# ── Loaders ───────────────────────────────────────────────────────────────────

func _load_blocks() -> void:
	var file := FileAccess.open(BLOCKS_PATH, FileAccess.READ)
	if file == null:
		push_error("BlockRegistry: cannot open %s (error %d)" % [BLOCKS_PATH, FileAccess.get_open_error()])
		return

	var json := JSON.new()
	var err  := json.parse(file.get_as_text())
	file.close()

	if err != OK:
		push_error("BlockRegistry: JSON parse error in %s — %s" % [BLOCKS_PATH, json.get_error_message()])
		return

	var root: Dictionary       = json.data
	var block_types: Dictionary = root.get("block_types", {})

	for raw_key: String in block_types:
		# Skip documentation-comment keys (any key starting with "__")
		if raw_key.begins_with("__"):
			continue

		var key := StringName(raw_key)
		var def  = block_types[raw_key]

		# Defensive: skip any non-dictionary value (shouldn't happen, but guard it)
		if typeof(def) != TYPE_DICTIONARY:
			continue

		var id: int = _id_to_key.size()
		_key_to_id[key] = id
		_id_to_key.append(key)
		_id_to_def.append(def)


func _load_palettes() -> void:
	var file := FileAccess.open(PALETTES_PATH, FileAccess.READ)
	if file == null:
		push_warning("BlockRegistry: cannot open %s — seasonal surface colors will use hex_color fallback." % PALETTES_PATH)
		return

	var json := JSON.new()
	var err  := json.parse(file.get_as_text())
	file.close()

	if err != OK:
		push_error("BlockRegistry: JSON parse error in %s — %s" % [PALETTES_PATH, json.get_error_message()])
		return

	var root: Dictionary = json.data

	for variant: String in root:
		if variant.begins_with("__"):
			continue

		var seasons = root[variant]
		if typeof(seasons) != TYPE_DICTIONARY:
			continue

		var color_map: Dictionary = {}
		for season: String in seasons:
			color_map[season] = Color(seasons[season] as String)

		_surface_palettes[variant] = color_map


func _load_resource_defs() -> void:
	var file := FileAccess.open(RESOURCES_PATH, FileAccess.READ)
	if file == null:
		push_warning("BlockRegistry: cannot open %s - resource metadata unavailable." % RESOURCES_PATH)
		return

	var json := JSON.new()
	var err  := json.parse(file.get_as_text())
	file.close()

	if err != OK:
		push_error("BlockRegistry: JSON parse error in %s - %s" % [RESOURCES_PATH, json.get_error_message()])
		return

	var root: Dictionary = json.data
	_resource_defs.clear()
	for raw_key: String in root:
		if raw_key.begins_with("__"):
			continue

		var def = root[raw_key]
		if typeof(def) != TYPE_DICTIONARY:
			continue

		_resource_defs[StringName(raw_key)] = def


# ── Public API ────────────────────────────────────────────────────────────────

## Returns the runtime integer ID for a namespaced block key.
## Returns -1 if the key is not registered.
func get_id(key: StringName) -> int:
	return _key_to_id.get(key, -1)


## Returns the permanent namespaced StringName for a runtime ID.
## Returns "" if the ID is out of range.
func get_key(id: int) -> StringName:
	if id < 0 or id >= _id_to_key.size():
		return &""
	return _id_to_key[id]


## Returns the full block definition dictionary for a key.
## Returns {} if the key is not registered.
func get_def(key: StringName) -> Dictionary:
	var id := get_id(key)
	if id < 0:
		return {}
	return _id_to_def[id]


## Returns mining/generation metadata for a block key from block_resources.json.
## Returns {} if the key has no resource definition.
func get_resource_def(key: StringName) -> Dictionary:
	return _resource_defs.get(key, {})


## Returns true if the block is physically solid (not void, not water).
## Used by the nav system for walkability. Water is NOT solid — dwarves cannot
## walk on it and physics does not collide with it.
func is_solid(id: int) -> bool:
	if id < 0 or id >= _id_to_def.size():
		return false
	var kind: String = (_id_to_def[id] as Dictionary).get("kind", "void")
	return kind != "void" and kind != "water"


## Returns true if the block is visually transparent (void only).
## Water renders as opaque blue — a face adjacent to water IS rendered,
## but water itself also emits faces (so the lake surface is visible).
## Only pure void is skipped by the mesher.
func is_transparent(id: int) -> bool:
	if id < 0 or id >= _id_to_def.size():
		return true
	var kind: String = (_id_to_def[id] as Dictionary).get("kind", "void")
	return kind == "void"


## Hot-path LUT: season → PackedColorArray indexed by runtime block ID.
## Built once at boot, read-only afterwards (safe from worker threads).
## Unknown seasons fall back to summer.
func get_color_lut(season: String) -> PackedColorArray:
	return _color_luts.get(season, _color_luts.get("summer", PackedColorArray()))


## Hot-path LUT: runtime block ID → 1 if transparent (void), else 0.
## Built once at boot, read-only afterwards (safe from worker threads).
func get_transparent_lut() -> PackedByteArray:
	return _transparent_lut


## Returns the display Color for a block at a given season.
##
## For surface grass/dirt variants, reads from surface_palettes.json.
## For all other blocks, uses the hex_color field from terrain_blocks.json.
## Falls back to Color.MAGENTA on any lookup failure (visible error sentinel).
func get_color(id: int, season: String = "summer") -> Color:
	if id < 0 or id >= _id_to_def.size():
		return Color.MAGENTA

	var def: Dictionary = _id_to_def[id]

	# Surface blocks use seasonal palettes.
	# Key format: "base:terrain:surface:grass_04" — last segment is the variant suffix.
	var key: String = _id_to_key[id]
	var parts := key.split(":")
	if parts.size() >= 1:
		var suffix: String = parts[-1]   # e.g. "grass_04", "dirt_02"
		if _surface_palettes.has(suffix):
			var palette: Dictionary = _surface_palettes[suffix]
			if palette.has(season):
				return palette[season] as Color
			# Season key missing — fall through to hex_color below.

	# All other blocks (rock, ore, gem, water, bedrock, soil): use hex_color directly.
	var hex: String = def.get("hex_color", "#FF00FF")
	return Color(hex)

source_text.scripts/registries/DwarfAssets.gd:
extends Node

## Dwarf asset + data registry autoload ("DwarfAssets" in project.godot).
##
## Owns BOTH halves of dwarf creation inputs (Registry Pattern, AGENT.md):
##   1. The ~41 modular part GLBs (doc 41b) — preloaded once, queried by key.
##      No `preload`/`load` calls for dwarf parts anywhere else in the codebase.
##   2. The three generation JSON pools — names.json / appearance.json /
##      traits.json. No other script may FileAccess these files.
##
## Parts are PackedScenes (imported GLBs), instantiated per dwarf by
## DwarfFactory. Colors are NOT baked per file: parts are authored in neutral
## near-white palettes and tinted at runtime (SKIN_TONES / HAIR_COLORS /
## EYE_COLORS below, from doc 41b).

const NAMES_PATH      := "res://data/entities/dwarves/names.json"
const APPEARANCE_PATH := "res://data/entities/dwarves/appearance.json"
const TRAITS_PATH     := "res://data/entities/dwarves/traits.json"

