class_name ItemDropManager
extends Node3D

## Spawns and owns dropped-item entities. Doc 18 Phase 2 grew this into the
## LOOSE-ITEM INDEX: every drop is registered on spawn, reservable by hauling
## dwarves, takeable (picked up off the ground), and placeable back as a
## STORED node on a stockpile cell. The index is event-maintained (spawn /
## take / drop / place) — never rebuilt by scanning (doc 16 §2.5 discipline).
## Scene node in debug_world.tscn (presentation lives in the scene, not an
## autoload — the SurfaceFloraSpawner pattern), found by producers via the
## "item_drop_manager" group.
##
## Node states: LOOSE (in _loose, restockable), RESERVED (in _loose and
## _reserved — visible but claimed), CARRIED (taken — reparented under the
## dwarf, absent from the index), STORED (child of this manager on a zone
## cell, meta "stored", absent from _loose — zones own the counts).
##
## REGISTRY PATTERN (AGENT.md): this node is the ONE owner of
## data/entities/items/resources.json — no other script may open it. Item defs
## load lazily on first spawn (the file's own contract: "loaded on demand, NOT
## held in memory at boot").
##
## VISUALS (doc 61 §5.7): item GLBs are authored at 8 vox/block with the 0.125
## scale baked into vertex positions — instanced at scale 1.0 with the
## project-standard vertex-colour material (lit per-pixel, double-sided).
##
## SLICE RULE (doc 11 Phase 5): drops obey the slice like flora and dwarves —
## hidden when their block is above the cut.

@export var slice_controller_path: NodePath

const RESOURCES_PATH := "res://data/entities/items/resources.json"
const SLICE_OFF_Y := 127

## A new loose item entered the world (spawned or dropped by an interrupted
## hauler). StockpileManager wakes zone lease posting on this (doc 18 §2.2).
signal drop_spawned(item_key: String)

var _defs: Dictionary = {}          # item key (String) -> def Dictionary
var _defs_loaded: bool = false
var _scene_cache: Dictionary = {}   # model path -> PackedScene (null cached as absent)
var _material: StandardMaterial3D = null
var _slice_y: int = SLICE_OFF_Y
var _drop_count: int = 0
var _missing_models: Dictionary = {}   # path -> true (warn once per model)

# ── Loose-item index (doc 18 Phase 2) ─────────────────────────────────────────
var _loose: Dictionary = {}         # Node3D -> item_key (String)
var _reserved: Dictionary = {}      # Node3D -> dwarf_id (int)


func _ready() -> void:
	add_to_group("item_drop_manager")
	add_to_group(SaveManager.OWNER_GROUP)
	var slice_controller := get_node_or_null(slice_controller_path)
	if slice_controller != null and slice_controller.has_signal("slice_changed"):
		slice_controller.connect("slice_changed", _on_slice_changed)
	_material = StandardMaterial3D.new()
	_material.vertex_color_use_as_albedo = true
	_material.roughness = 1.0
	_material.metallic = 0.0
	_material.cull_mode = BaseMaterial3D.CULL_DISABLED
	_material.shading_mode = BaseMaterial3D.SHADING_MODE_PER_PIXEL


# ── Public API ────────────────────────────────────────────────────────────────

## Spawns `count` units of an item at a mined block position. The drop rests
## on the first solid floor at or below the block (mined columns drop their
## loot to the pit floor). Position jitter and yaw are cosmetic randomness —
## runtime behaviour, not worldgen (Hard Rule 8 does not apply to drops).
func spawn_drop(item_key: String, count: int, block: Vector3i) -> void:
	if count <= 0:
		return
	_ensure_defs()
	var def: Dictionary = _defs.get(item_key, {})
	if def.is_empty():
		push_warning("ItemDropManager: unknown item '%s' — drop skipped." % item_key)
		return
	var scene := _model_scene(String(def.get("model", "")))
	var rest_y := _rest_y(block)
	for i in range(count):
		var node := _build_drop_node(item_key, scene)
		var jitter := Vector3(randf_range(-0.28, 0.28), 0.0, randf_range(-0.28, 0.28))
		node.position = Vector3(float(block.x) + 0.5, float(rest_y), float(block.z) + 0.5) + jitter
		node.rotation.y = randf_range(0.0, TAU)
		node.set_meta("base_y", rest_y)
		node.set_meta("item_key", item_key)
		# Same rule as DwarfAgent.apply_slice: floor(position.y) <= slice_y.
		node.visible = rest_y <= _slice_y
		add_child(node)
		_drop_count += 1
		_loose[node] = item_key
		drop_spawned.emit(item_key)


func get_stats() -> Dictionary:
	return { "drops": _drop_count, "loose": _loose.size(), "reserved": _reserved.size() }


func save_section_key() -> String:
	return "items"


func save_restore_priority() -> int:
	return 50


func serialize_state() -> Dictionary:
	var entries: Array = []
	for node: Node3D in _loose:
		if not is_instance_valid(node):
			continue
		entries.append({
			"item_key": String(_loose[node]),
			"position": SaveManager.pack_v3(node.position),
			"rotation_y": node.rotation.y,
		})
	entries.sort_custom(func(a: Dictionary, b: Dictionary) -> bool:
		var ak := "%s:%s" % [String(a["item_key"]), str(a["position"])]
		var bk := "%s:%s" % [String(b["item_key"]), str(b["position"])]
		return ak < bk)
	return { "loose": entries }


func restore_state(state: Dictionary) -> void:
	for raw in state.get("loose", []):
		if not (raw is Dictionary):
			continue
		var entry := raw as Dictionary
		var key := String(entry.get("item_key", ""))
		restore_loose_item(
			key,
			SaveManager.unpack_v3(entry.get("position", [])),
			float(entry.get("rotation_y", 0.0)))


## Builds one unindexed item visual for save restoration consumers (shelf
## anchors and ground-stockpile stored nodes).
func create_item_visual(item_key: String) -> Node3D:
	_ensure_defs()
	var def: Dictionary = _defs.get(item_key, {})
	if def.is_empty():
		push_warning("ItemDropManager: unknown restored item '%s'." % item_key)
		return null
	var node := _build_drop_node(item_key, _model_scene(String(def.get("model", ""))))
	node.set_meta("item_key", item_key)
	_drop_count += 1
	return node


func restore_stored_item(item_key: String, cell: Vector3i) -> void:
	var node := create_item_visual(item_key)
	if node == null:
		return
	add_child(node)
	place_stored(node, cell)


## Restores an exact loose item without rest-scanning or random jitter. Also
## used for items that were in transit at snapshot time: tasks are transient,
## so those materialize safely at their saved carrier's feet on load.
func restore_loose_item(item_key: String, restored_position: Vector3,
		rotation_y: float = 0.0) -> void:
	var node := create_item_visual(item_key)
	if node == null:
		return
	node.position = restored_position
	node.rotation.y = rotation_y
	node.set_meta("base_y", restored_position.y)
	node.set_meta("stored", false)
	node.visible = floori(restored_position.y) <= _slice_y
	add_child(node)
	_loose[node] = item_key
	drop_spawned.emit(item_key)


# ── Loose-item index API (doc 18 §2.1) ────────────────────────────────────────

## Public item-definition accessor (Registry Pattern: this node owns
## resources.json; everyone else queries through here). {} if unknown.
func get_item_def(item_key: String) -> Dictionary:
	_ensure_defs()
	return _defs.get(item_key, {})


## Nearest unreserved loose item whose material_tags overlap accepted_tags,
## by flat Manhattan distance from `from`. `exclude` is a per-dwarf blacklist
## (Node -> true) of items that failed pathing this round. Null if none.
func nearest_loose(accepted_tags: Array, from: Vector3i, exclude: Dictionary = {}) -> Node3D:
	_ensure_defs()
	var best: Node3D = null
	var best_dist: int = 0x7FFFFFFF
	for node: Node3D in _loose:
		if _reserved.has(node) or exclude.has(node) or not is_instance_valid(node):
			continue
		var def: Dictionary = _defs.get(_loose[node], {})
		var tags: Array = def.get("material_tags", [])
		var accepted := false
		for tag: String in accepted_tags:
			if tags.has(tag):
				accepted = true
				break
		if not accepted:
			continue
		var cell := item_floor_cell(node)
		var dist := absi(cell.x - from.x) + absi(cell.y - from.y) + absi(cell.z - from.z)
		if dist < best_dist:
			best = node
			best_dist = dist
	return best


## Nearest unreserved loose item of EXACTLY this key (type-matched fetch,
## doc 19 §3.3 — SH parity: any item of the URI satisfies a ghost).
func nearest_loose_of_key(item_key: String, from: Vector3i, exclude: Dictionary = {}) -> Node3D:
	var best: Node3D = null
	var best_dist: int = 0x7FFFFFFF
	for node: Node3D in _loose:
		if _reserved.has(node) or exclude.has(node) or not is_instance_valid(node):
			continue
		if String(_loose[node]) != item_key:
			continue
		var cell := item_floor_cell(node)
		var dist := absi(cell.x - from.x) + absi(cell.y - from.y) + absi(cell.z - from.z)
		if dist < best_dist:
			best = node
			best_dist = dist
	return best


## Unreserved loose accepted items within `radius` blocks (flat Chebyshev) of
## `center`, nearest first, capped at `limit`. The pouch bundle search (doc 18
## pouch — SH NearbyItemSearch equivalent). `exclude` = blacklist + main item.
func loose_near(accepted_tags: Array, center: Vector3i, radius: int, limit: int, exclude: Dictionary = {}) -> Array[Node3D]:
	_ensure_defs()
	var found: Array = []   # [dist, node] pairs
	for node: Node3D in _loose:
		if _reserved.has(node) or exclude.has(node) or not is_instance_valid(node):
			continue
		var cell := item_floor_cell(node)
		var dx := absi(cell.x - center.x)
		var dz := absi(cell.z - center.z)
		if maxi(dx, dz) > radius or absi(cell.y - center.y) > 2:
			continue
		var tags: Array = (_defs.get(_loose[node], {}) as Dictionary).get("material_tags", [])
		var accepted := false
		for tag: String in accepted_tags:
			if tags.has(tag):
				accepted = true
				break
		if accepted:
			found.append([dx + dz, node])
	found.sort_custom(func(a: Array, b: Array) -> bool:
		return int(a[0]) < int(b[0]))
	var result: Array[Node3D] = []
	for pair: Array in found:
		result.append(pair[1] as Node3D)
		if result.size() >= limit:
			break
	return result


## Unreserved loose items whose tags overlap accepted_tags, capped at `cap`
## (lease posting only needs "are there at least N?", doc 18 §2.2).
func count_loose(accepted_tags: Array, cap: int) -> int:
	_ensure_defs()
	var found: int = 0
	for node: Node3D in _loose:
		if _reserved.has(node) or not is_instance_valid(node):
			continue
		var tags: Array = (_defs.get(_loose[node], {}) as Dictionary).get("material_tags", [])
		for tag: String in accepted_tags:
			if tags.has(tag):
				found += 1
				break
		if found >= cap:
			return found
	return found


## The FLOOR cell a dwarf stands on to pick this item up (the item rests on
## that cell's top face — spawn_drop sets position.y to floor top).
func item_floor_cell(node: Node3D) -> Vector3i:
	return Vector3i(
		floori(node.position.x),
		int(round(node.position.y)) - 1,
		floori(node.position.z))


func item_key_of(node: Node3D) -> String:
	return String(_loose.get(node, node.get_meta("item_key", "")))


func reserve(node: Node3D, dwarf_id: int) -> bool:
	if not _loose.has(node) or _reserved.has(node):
		return false
	_reserved[node] = dwarf_id
	return true


## Owner-guarded (doc 18 spam-robustness pass): pass the reserving dwarf_id so
## a stale unreserve (an interrupted hauler cancelling a bundle whose skipped
## items were re-reserved by another hauler in the meantime) cannot clobber
## the new owner's reservation. -1 = unconditional (trusted callers only).
func unreserve(node: Node3D, dwarf_id: int = -1) -> void:
	if dwarf_id >= 0 and int(_reserved.get(node, -1)) != dwarf_id:
		return
	_reserved.erase(node)


## Pickup: removes the node from the index and this manager; the caller
## (the hauling dwarf) reparents it as its carried visual. Returns the
## item key, or "" if the node was not a loose item.
func take(node: Node3D) -> String:
	if not _loose.has(node):
		return ""
	var key: String = _loose[node]
	_loose.erase(node)
	_reserved.erase(node)
	remove_child(node)
	return key


## Deposit: re-adopts a carried node as a STORED item centred on a stockpile
## floor cell. Stored nodes are NOT in the loose index — the zone's
## cell_stacks own the counts (doc 18 §2.4: storage is physical).
func place_stored(node: Node3D, cell: Vector3i) -> void:
	if node.get_parent() != null:
		node.get_parent().remove_child(node)
	add_child(node)
	node.position = Vector3(float(cell.x) + 0.5, float(cell.y + 1), float(cell.z) + 0.5)
	node.rotation = Vector3.ZERO
	node.set_meta("base_y", cell.y + 1)
	node.set_meta("stored", true)
	node.visible = cell.y + 1 <= _slice_y


## Release protocol (doc 18 §2.3 step 5 / Hard Rule 12): an interrupted
## hauler drops its carried node at its feet as a normal loose item.
## Position jitter matches spawn_drop: a full pouch dropped on one cell must
## read as N items, not one (the WYSIWYG rule that drove one-item-per-tile).
func drop_loose(node: Node3D, floor_cell: Vector3i) -> void:
	var key := String(node.get_meta("item_key", ""))
	if node.get_parent() != null:
		node.get_parent().remove_child(node)
	add_child(node)
	var jitter := Vector3(randf_range(-0.28, 0.28), 0.0, randf_range(-0.28, 0.28))
	node.position = Vector3(float(floor_cell.x) + 0.5, float(floor_cell.y + 1), float(floor_cell.z) + 0.5) + jitter
	node.set_meta("base_y", floor_cell.y + 1)
	node.set_meta("stored", false)
	node.visible = floor_cell.y + 1 <= _slice_y
	_loose[node] = key
	drop_spawned.emit(key)


## Container withdraw (doc 19 Phase 4): spawn ONE item at a floor cell,
## pre-reserved for the withdrawing dwarf — containers hold counts, not
## nodes. No drop_spawned emit (the item is claimed the instant it exists).
func spawn_reserved(item_key: String, floor_cell: Vector3i, dwarf_id: int) -> Node3D:
	_ensure_defs()
	var def: Dictionary = _defs.get(item_key, {})
	if def.is_empty():
		push_warning("ItemDropManager: unknown item '%s' — spawn_reserved skipped." % item_key)
		return null
	var node := _build_drop_node(item_key, _model_scene(String(def.get("model", ""))))
	node.position = Vector3(float(floor_cell.x) + 0.5, float(floor_cell.y + 1), float(floor_cell.z) + 0.5)
	node.set_meta("base_y", floor_cell.y + 1)
	node.set_meta("item_key", item_key)
	node.visible = floor_cell.y + 1 <= _slice_y
	add_child(node)
	_drop_count += 1
	_loose[node] = item_key
	_reserved[node] = dwarf_id
	return node


## The STORED node sitting on a zone cell, or null (fetch withdraw, doc 19
## §3.3 — zones store one item per tile, so cell -> node is unique).
func stored_node_at(cell: Vector3i) -> Node3D:
	for child in get_children():
		if child is Node3D and bool(child.get_meta("stored", false)) \
				and item_floor_cell(child as Node3D) == cell:
			return child as Node3D
	return null


## Withdraw (doc 19 §3.3): a stored node re-enters the loose index already
## RESERVED by the withdrawing dwarf — no other hauler can grab it between
## withdrawal and pickup.
func withdraw_stored(node: Node3D, dwarf_id: int) -> void:
	node.set_meta("stored", false)
	var key := String(node.get_meta("item_key", ""))
	_loose[node] = key
	_reserved[node] = dwarf_id


## Zone removal: stored nodes on the given cells become loose again, and
## stacked counts beyond the one visible node respawn as fresh drops so no
## items are lost (doc 18 §2.4 one-node-per-stack rule).
func release_stored_cells(stacks: Dictionary) -> void:
	var by_cell: Dictionary = {}
	for child in get_children():
		if child is Node3D and bool(child.get_meta("stored", false)):
			var node := child as Node3D
			by_cell[item_floor_cell(node)] = node
	for cell: Vector3i in stacks:
		var stack: Dictionary = stacks[cell]
		var key := String(stack.get("item", ""))
		var count := int(stack.get("count", 0))
		if by_cell.has(cell):
			var node: Node3D = by_cell[cell]
			node.set_meta("stored", false)
			_loose[node] = key
			drop_spawned.emit(key)
			count -= 1
		if count > 0:
			spawn_drop(key, count, Vector3i(cell.x, cell.y + 1, cell.z))


# ── Internals ─────────────────────────────────────────────────────────────────

func _build_drop_node(item_key: String, scene: PackedScene) -> Node3D:
	var node: Node3D = null
	if scene != null:
		node = scene.instantiate() as Node3D
	if node == null:
		# Fallback: a small neutral cube so a missing model is visible, not silent.
		var mesh_instance := MeshInstance3D.new()
		var box := BoxMesh.new()
		box.size = Vector3(0.4, 0.4, 0.4)
		mesh_instance.mesh = box
		node = mesh_instance
	node.name = "Drop_%s_%d" % [item_key.get_slice(":", item_key.get_slice_count(":") - 1), _drop_count]
	_apply_material(node)
	return node


func _apply_material(node: Node) -> void:
	if node is MeshInstance3D:
		(node as MeshInstance3D).material_override = _material
	for child in node.get_children():
		_apply_material(child)


## Top face of the first solid block at or below the drop position.
## Scans all the way down to bedrock (2026-08-06 bugfix): the old fixed
## REST_SCAN_DEPTH=8 cap silently gave up on any column whose straight-down
## air ran deeper than 8 blocks before hitting a floor — common when mining
## a wall/ceiling block of a deep or diagonal tunnel, where the actual floor
## is well below the mined block but not directly beneath it within 8 cells.
## Past that cap the function fell back to `return block.y`, leaving the
## drop hovering at its original mined height with nothing under it —
## reported as "floating blocks that were recently mined". A plain downward
## scan to bedrock is still O(~100) dictionary/array lookups worst case, and
## only runs on a drop spawn (already probability-gated), so the extra range
## costs nothing measurable.
func _rest_y(block: Vector3i) -> int:
	var y := block.y - 1
	while y > WorldGenerator.BEDROCK_MAX_Y:
		if BlockRegistry.is_solid(_block_id(block.x, y, block.z)):
			return y + 1
		y -= 1
	# Nothing solid found all the way to bedrock (should not happen — Hard
	# Rule 1 forbids mining bedrock itself) — rest one cell above it as a
	# guaranteed-solid last resort rather than floating.
	return WorldGenerator.BEDROCK_MAX_Y + 1


func _block_id(wx: int, wy: int, wz: int) -> int:
	if WorldData.chunk_exists(wx >> 4, wy >> 4, wz >> 4):
		return WorldData.get_block(wx, wy, wz)
	return WorldGenerator.get_generated_block_id(wx, wy, wz)


func _model_scene(path: String) -> PackedScene:
	if path.is_empty():
		return null
	if _scene_cache.has(path):
		return _scene_cache[path]
	var scene: PackedScene = null
	if ResourceLoader.exists(path):
		scene = load(path) as PackedScene
	if scene == null and not _missing_models.has(path):
		_missing_models[path] = true
		push_warning("ItemDropManager: model missing at '%s' — using fallback cube." % path)
	_scene_cache[path] = scene
	return scene


func _ensure_defs() -> void:
	if _defs_loaded:
		return
	_defs_loaded = true
	var file := FileAccess.open(RESOURCES_PATH, FileAccess.READ)
	if file == null:
		push_error("ItemDropManager: cannot open %s." % RESOURCES_PATH)
		return
	var json := JSON.new()
	var err := json.parse(file.get_as_text())
	file.close()
	if err != OK:
		push_error("ItemDropManager: JSON parse error in %s — %s" % [RESOURCES_PATH, json.get_error_message()])
		return
	var root: Dictionary = json.data
	for raw_key: String in root:
		if raw_key.begins_with("__"):
			continue
		var def = root[raw_key]
		if typeof(def) != TYPE_DICTIONARY:
			continue
		_defs[raw_key] = def
	print("ItemDropManager: loaded %d item definitions." % _defs.size())


# ── Slice culling (doc 11 Phase 5 — same hook as flora and dwarves) ──────────

func _on_slice_changed(new_slice_y: int) -> void:
	if new_slice_y == _slice_y:
		return
	_slice_y = new_slice_y
	for child in get_children():
		if child is Node3D and child.has_meta("base_y"):
			(child as Node3D).visible = int(child.get_meta("base_y")) <= _slice_y

source_text.scripts/systems/NavGrid.gd:
extends Node

## Custom 3D A* navigation (doc 32, doc 16 step 3b). Autoload, loaded after
## PlacedEntityRegistry (walkability reads it), before the future TaskManager
## (reachability probes need it).
##
## WALKABILITY (doc 32, Hard Rule 3): a floor cell (x, y, z) is walkable iff
##   1. the block at y is SOLID (water is not solid — no walking on lakes),
##   2. the blocks at y+1, y+2, y+3 are air (the 3-block clearance envelope),
##   3. none of those three clearance cells is occupied by a placed entity
##      (tree trunks, the Settlement Flag — PlacedEntityRegistry.occupies).
## Logical dwarf height is 3 blocks — NEVER the 3.3 visual mesh (doc 41).
##
## TERRAIN SOURCE: WorldData where the chunk exists (real, mined-aware once
## mining execution writes void); otherwise the deterministic generated block
## (`WorldGenerator.get_generated_block_id`) so dwarves can walk the whole map
## without waiting for render streaming.
##   KNOWN DEV WART: DEV-instant-mined blocks in UNgenerated chunks live only
##   in the renderer's mined set, not WorldData — nav sees authored rock there.
##   Real mining execution (step 6) writes through WorldData.set_block (which
##   lazily creates chunks), closing the gap. Recorded in doc 16 build log.
##
## CACHING (doc 32): walkability memoised per CHUNK (lazy, invalidated by
## WorldData.chunk_dirtied and PlacedEntityRegistry.occupancy_changed);
## completed paths cached by (start, goal) with a 5 s TTL, dropped when an
## invalidation touches any chunk the path crosses.
##
## STEP RULES: cardinal moves with floor delta -1/0/+1 per step, PLUS flat
## diagonals (enabled 2026-06-10, Alen — L-shaped routes read wrong in play;
## doc 32 updated). Diagonal rules: same-level only (vertical steps stay
## cardinal), and NO corner cutting — both cardinal in-between cells must be
## walkable, so dwarves never clip tree trunks or wall corners.
## Costs: lateral 1.0, diagonal 1.414, up 1.2, down 0.9. Heuristic: octile XZ
## + |dy| (admissible with diagonals; Manhattan would overestimate).

const CLEARANCE := 3                  # air blocks above every floor cell
const PATH_CACHE_TTL_MSEC := 5000     # doc 32
const DEFAULT_MAX_NODES := 6000      # full-path expansion cap (never hangs)
const PROBE_NODE_CAP := 200           # scheduler reachability probes (doc 32)

const COST_LATERAL := 1.0
const COST_DIAGONAL := 1.414
const COST_UP := 1.2
const COST_DOWN := 0.9

var _walkable_cache: Dictionary = {}   # Vector3i chunk -> Dictionary[Vector3i cell -> bool]
var _path_cache: Dictionary = {}       # [start, goal] key -> { path, expires, chunks }
var _paths_served: int = 0
var _path_cache_hits: int = 0
var _probes_run: int = 0
var _nodes_expanded_total: int = 0


func _ready() -> void:
	WorldData.chunk_dirtied.connect(_on_chunk_dirtied, CONNECT_DEFERRED)
	PlacedEntityRegistry.occupancy_changed.connect(_on_occupancy_changed)
	print("NavGrid: ready.")


# ── Public API ────────────────────────────────────────────────────────────────

## Full pathfind between two FLOOR cells. Returns the ordered floor-cell path
## INCLUDING start and goal, or an empty array if unreachable within the node
## cap. Results are cached for PATH_CACHE_TTL_MSEC.
func find_path(start: Vector3i, goal: Vector3i, max_nodes: int = DEFAULT_MAX_NODES) -> Array[Vector3i]:
	var now := Time.get_ticks_msec()
	var key := [start, goal]
	if _path_cache.has(key):
		var entry: Dictionary = _path_cache[key]
		if now < int(entry["expires"]):
			_path_cache_hits += 1
			var cached: Array[Vector3i] = entry["path"]
			return cached
		_path_cache.erase(key)

	var result := _astar(start, goal, max_nodes, false)
	if not result.is_empty():
		_path_cache[key] = {
			"path": result,
			"expires": now + PATH_CACHE_TTL_MSEC,
			"chunks": _path_chunk_set(result),
		}
		_paths_served += 1
	return result


## Capped reachability probe (doc 16 §2.6 — the scheduler's question). True if
## `goal` or any cell laterally adjacent to it is reached within the node cap.
## A capped failure counts as unreachable (caller applies backoff). The caller
## may pass its configured cap (task_config.json probe_node_cap); the default
## is the doc-32 value.
func probe_reachable(start: Vector3i, goal: Vector3i, node_cap: int = PROBE_NODE_CAP) -> bool:
	_probes_run += 1
	return not _astar(start, goal, node_cap, true).is_empty()


## The doc-32 walkability test for one floor cell (cached).
func is_walkable(cell: Vector3i) -> bool:
	if cell.y < 1 or cell.y + CLEARANCE >= WorldData.WORLD_SIZE_Y \
			or cell.x < 0 or cell.x >= WorldData.WORLD_SIZE_X \
			or cell.z < 0 or cell.z >= WorldData.WORLD_SIZE_Z:
		return false
	var chunk_key := Vector3i(cell.x >> 4, cell.y >> 4, cell.z >> 4)
	var chunk_cache: Dictionary = _walkable_cache.get(chunk_key, {})
	if chunk_cache.has(cell):
		return chunk_cache[cell]
	var walkable := _compute_walkable(cell)
	if chunk_cache.is_empty():
		_walkable_cache[chunk_key] = chunk_cache
	chunk_cache[cell] = walkable
	return walkable


## Finds the walkable floor cell of a column near an expected Y (snap helper
## for click targets and spawn points). Returns cell or Vector3i(-1,-1,-1).
func walkable_floor_at(wx: int, wz: int, near_y: int, scan: int = 4) -> Vector3i:
	var offsets: Array[int] = [0]
	for dy in range(1, scan + 1):
		offsets.append(dy)
		offsets.append(-dy)
	for dy in offsets:
		var cell := Vector3i(wx, near_y + dy, wz)
		if is_walkable(cell):
			return cell
	return Vector3i(-1, -1, -1)


## String-pulling support (agent movement smoothing): true if an agent can walk
## a straight FLAT line between two same-level floor-cell centres without
## crossing an unwalkable cell. Samples the segment with a small agent radius —
## the corner-safety margin. Grid paths stay the correctness authority; this
## only lets agents cut the staircase zigzag between waypoints.
func line_walkable_flat(a: Vector3i, b: Vector3i, radius: float = 0.3) -> bool:
	if a.y != b.y:
		return false
	var from := Vector2(float(a.x) + 0.5, float(a.z) + 0.5)
	var to := Vector2(float(b.x) + 0.5, float(b.z) + 0.5)
	var length := from.distance_to(to)
	if length < 0.001:
		return true
	var dir := (to - from) / length
	var side := Vector2(-dir.y, dir.x) * radius
	var t := 0.0
	while t <= length:
		var p := from + dir * t
		for offset in [Vector2.ZERO, side, -side]:
			var q: Vector2 = p + offset
			if not is_walkable(Vector3i(floori(q.x), a.y, floori(q.y))):
				return false
		t += 0.25
	return true


func get_stats() -> Dictionary:
	return {
		"paths_served": _paths_served,
		"path_cache_hits": _path_cache_hits,
		"path_cache_size": _path_cache.size(),
		"probes_run": _probes_run,
		"walkable_chunks_cached": _walkable_cache.size(),
		"nodes_expanded_total": _nodes_expanded_total,
	}


func clear_runtime_state() -> void:
	_walkable_cache.clear()
	_path_cache.clear()
	_paths_served = 0
	_path_cache_hits = 0
	_probes_run = 0
	_nodes_expanded_total = 0


# ── Walkability ───────────────────────────────────────────────────────────────

func _compute_walkable(cell: Vector3i) -> bool:
	if not BlockRegistry.is_solid(_block_id(cell.x, cell.y, cell.z)):
		return false
	for k in range(1, CLEARANCE + 1):
		var above := Vector3i(cell.x, cell.y + k, cell.z)
		if BlockRegistry.is_solid(_block_id(above.x, above.y, above.z)):
			return false
		if PlacedEntityRegistry.occupies(above):
			return false
	return true


## Real block where a chunk exists; deterministic generated block elsewhere.
func _block_id(wx: int, wy: int, wz: int) -> int:
	if WorldData.chunk_exists(wx >> 4, wy >> 4, wz >> 4):
		return WorldData.get_block(wx, wy, wz)
	return WorldGenerator.get_generated_block_id(wx, wy, wz)


# ── A* core ───────────────────────────────────────────────────────────────────

const _DIRS: Array[Vector2i] = [Vector2i(1, 0), Vector2i(-1, 0), Vector2i(0, 1), Vector2i(0, -1)]
const _DIAGS: Array[Vector2i] = [Vector2i(1, 1), Vector2i(1, -1), Vector2i(-1, 1), Vector2i(-1, -1)]

func _astar(start: Vector3i, goal: Vector3i, max_nodes: int, adjacent_ok: bool) -> Array[Vector3i]:
	var empty: Array[Vector3i] = []
	if not is_walkable(start):
		return empty
	if not adjacent_ok and not is_walkable(goal):
		return empty
	if start == goal:
		var trivial: Array[Vector3i] = [start]
		return trivial

	# Binary min-heap of [f, tie, cell]; g + came-from maps.
	var heap: Array = []
	var g: Dictionary = { start: 0.0 }
	var came: Dictionary = {}
	var closed: Dictionary = {}
	var tie := 0
	_heap_push(heap, [_heuristic(start, goal), tie, start])

	var expanded := 0
	while not heap.is_empty():
		var top: Array = _heap_pop(heap)
		var current: Vector3i = top[2]
		if closed.has(current):
			continue
		closed[current] = true
		expanded += 1
		_nodes_expanded_total += 1

		if current == goal or (adjacent_ok and _lateral_adjacent(current, goal)):
			return _reconstruct(came, current)
		if expanded >= max_nodes:
			return empty

		var g_cur: float = g[current]
		for dir: Vector2i in _DIRS:
			var nx := current.x + dir.x
			var nz := current.z + dir.y
			# At most one walkable floor exists among y-1/y/y+1 in a column
			# (a walkable floor's clearance forbids another directly above).
			for dy: int in [0, 1, -1]:
				var neighbor := Vector3i(nx, current.y + dy, nz)
				if closed.has(neighbor) or not is_walkable(neighbor):
					continue
				var step_cost := COST_LATERAL
				if dy > 0:
					step_cost = COST_UP
				elif dy < 0:
					step_cost = COST_DOWN
				var g_new := g_cur + step_cost
				if g.has(neighbor) and g_new >= float(g[neighbor]):
					break
				g[neighbor] = g_new
				came[neighbor] = current
				tie += 1
				_heap_push(heap, [g_new + _heuristic(neighbor, goal), tie, neighbor])
				break   # one floor per column — stop scanning dy

		# Flat diagonals (no corner cutting): destination at the SAME level,
		# and both cardinal in-between cells walkable.
		for dir: Vector2i in _DIAGS:
			var neighbor := Vector3i(current.x + dir.x, current.y, current.z + dir.y)
			if closed.has(neighbor) or not is_walkable(neighbor):
				continue
			if not is_walkable(Vector3i(current.x + dir.x, current.y, current.z)):
				continue
			if not is_walkable(Vector3i(current.x, current.y, current.z + dir.y)):
				continue
			var g_new := g_cur + COST_DIAGONAL
			if g.has(neighbor) and g_new >= float(g[neighbor]):
				continue
			g[neighbor] = g_new
			came[neighbor] = current
			tie += 1
			_heap_push(heap, [g_new + _heuristic(neighbor, goal), tie, neighbor])
	return empty


## Octile distance in XZ (diagonals allowed) + vertical Manhattan. Admissible:
## never overestimates the true cost under the step rules above.
func _heuristic(a: Vector3i, b: Vector3i) -> float:
	var dx := absi(a.x - b.x)
	var dz := absi(a.z - b.z)
	var dy := absi(a.y - b.y)
	return float(maxi(dx, dz)) + 0.414 * float(mini(dx, dz)) + 0.9 * float(dy)


func _lateral_adjacent(a: Vector3i, b: Vector3i) -> bool:
	return absi(a.x - b.x) + absi(a.z - b.z) == 1 and absi(a.y - b.y) <= 1


func _reconstruct(came: Dictionary, current: Vector3i) -> Array[Vector3i]:
	var path: Array[Vector3i] = [current]
	while came.has(current):
		current = came[current]
		path.push_front(current)
	return path


# ── Binary heap (min on element[0], tie-break element[1]) ─────────────────────

func _heap_push(heap: Array, item: Array) -> void:
	heap.append(item)
	var i := heap.size() - 1
	while i > 0:
		@warning_ignore("integer_division")
		var parent := (i - 1) / 2
		if _heap_less(heap[i], heap[parent]):
			var tmp = heap[i]
			heap[i] = heap[parent]
			heap[parent] = tmp
			i = parent
		else:
			break


func _heap_pop(heap: Array) -> Array:
	var top: Array = heap[0]
	var last = heap.pop_back()
	if not heap.is_empty():
		heap[0] = last
		var i := 0
		var n := heap.size()
		while true:
			var smallest := i
			var l := i * 2 + 1
			var r := i * 2 + 2
			if l < n and _heap_less(heap[l], heap[smallest]):
				smallest = l
			if r < n and _heap_less(heap[r], heap[smallest]):
				smallest = r
			if smallest == i:
				break
			var tmp = heap[i]
			heap[i] = heap[smallest]
			heap[smallest] = tmp
			i = smallest
	return top


func _heap_less(a: Array, b: Array) -> bool:
	if float(a[0]) != float(b[0]):
		return float(a[0]) < float(b[0])
	return int(a[1]) < int(b[1])


# ── Invalidation (doc 32: rebuild lazily on change) ──────────────────────────

func _on_chunk_dirtied(cx: int, cy: int, cz: int) -> void:
	_invalidate_chunk(Vector3i(cx, cy, cz))
	# A floor cell's walkability depends on CLEARANCE air blocks *above* it,
	# which can live in the chunk above the floor's own chunk. The worldgen
	# path (WorldData.submit_chunk) dirties all six neighbours, but the
	# gameplay path (WorldData.set_block → mark_chunk_dirty) dirties only the
	# edited chunk — so a block mined in this chunk's bottom rows must also
	# refresh cached walkability for floors in the chunk below (mirrors the
	# downward CLEARANCE extension in _on_occupancy_changed). Without this,
	# floors exposed near vertical chunk boundaries (y = 15/31/47…) stayed
	# cached unwalkable until an unrelated invalidation.
	if cy > 0:
		_invalidate_chunk(Vector3i(cx, cy - 1, cz))


func _on_occupancy_changed(box_min: Vector3i, box_size: Vector3i) -> void:
	# Occupancy affects walkability of cells whose CLEARANCE intersects the box,
	# so extend down by the clearance height before mapping to chunks.
	var lo := Vector3i(box_min.x, maxi(box_min.y - CLEARANCE, 0), box_min.z)
	var hi := box_min + box_size - Vector3i.ONE
	for cx in range(lo.x >> 4, (hi.x >> 4) + 1):
		for cy in range(lo.y >> 4, (hi.y >> 4) + 1):
			for cz in range(lo.z >> 4, (hi.z >> 4) + 1):
				_invalidate_chunk(Vector3i(cx, cy, cz))


func _invalidate_chunk(chunk_key: Vector3i) -> void:
	_walkable_cache.erase(chunk_key)
	if _path_cache.is_empty():
		return
	var stale: Array = []
	for key in _path_cache:
		var chunks: Dictionary = (_path_cache[key] as Dictionary)["chunks"]
		if chunks.has(chunk_key):
			stale.append(key)
	for key in stale:
		_path_cache.erase(key)


func _path_chunk_set(path: Array[Vector3i]) -> Dictionary:
	var chunks: Dictionary = {}
	for cell in path:
		chunks[Vector3i(cell.x >> 4, cell.y >> 4, cell.z >> 4)] = true
	return chunks

source_text.scripts/systems/RoomOverlayController.gd:
class_name RoomOverlayController
extends Node3D

## The Rooms tool (🚪 dock entry, Alen's ask 2026-08-07) — makes sealed rooms
## visible and clickable instead of hunting them with the Block Inspector.
##
## While active, every sealed room `RoomManager` tracks gets a translucent
## floor overlay (fill + exterior outline, drawn at the room's floor cells —
## the lowest air cell per column). Overlays render with NO depth test (the
## mining ghost-layer treatment): a room reads through the mountain whether
## or not the slice is cut down to it — that IS the point of the tool. Amber
## = sealed; icy blue = Frozen Vault.
##
## Clicking marches the mouse ray through the world and selects the first
## room whose interior air it crosses (cells above the slice plane are
## skipped; solid rock does NOT stop the march — clicks are as x-ray as the
## overlays, so a room visible through rock is also clickable through rock).
## Selection opens a compact info window: sealed/frozen state, depth-zone
## name, temperature, volume, heat units (+computed bonus), door count,
## seasonal influence — everything doc 34's "UI — Room Temperature Display"
## specifies, fed by RoomManager.get_room_at()/get_rooms().
##
## Tool conventions (the StockpileDesignationController shape): dock announce
## via tool_requested — this controller self-toggles on its own id and
## deactivates on any other; ESC deactivates; right-mouse is never consumed
## (camera orbit contract, 21_camera.md). Scene node, not an autoload
## (presentation — doc 13 dividing line). Overlays and selection are derived
## presentation state: never saved, rebuilt from RoomManager on activation
## and on room_updated/room_removed.

signal tool_active_changed(active: bool)

const TOOL_ID := "rooms"
const RAY_STEP := 0.25
const RAY_MAX := 700.0
const SLICE_OFF_Y := 127
const _FACE_NORMALS: Array[Vector3i] = [
	Vector3i(1, 0, 0), Vector3i(-1, 0, 0),
	Vector3i(0, 1, 0), Vector3i(0, -1, 0),
	Vector3i(0, 0, 1), Vector3i(0, 0, -1),
]
const REBUILD_THROTTLE_S := 0.3      # RoomManager fires room_updated per room per rebuild
const WINDOW_REFRESH_S := 0.5        # temp drifts hourly at most — 2 Hz is plenty

## Green — deliberately distinct from every other overlay family: mining
## zones own yellow, stockpile zones own blue-cyan, furniture ghosts own
## cyan/red validity tints. Frozen Vaults stay icy blue.
const SEALED_FILL := Color(0.30, 0.80, 0.45, 0.14)
const SEALED_LINE := Color(0.45, 1.00, 0.60, 0.95)
const FROZEN_FILL := Color(0.42, 0.68, 0.95, 0.14)
const FROZEN_LINE := Color(0.62, 0.86, 1.00, 0.95)
const SELECTED_FILL_ALPHA := 0.28    # fill alpha bump on the selected room
const SHELL_INSET := 0.04            # pull shell faces inside the cell boundary
                                     # (they'd otherwise sit exactly on the wall
                                     # faces and z-fight where depth applies)

@export var dock_ui_path: NodePath
@export var slice_controller_path: NodePath

var _active: bool = false
var _slice_y: int = SLICE_OFF_Y
var _overlay_root: Node3D = null
var _overlays: Dictionary = {}       # room_id -> { "root": Node3D, "base_y": int }
var _overlays_dirty: bool = false
var _rebuild_accum: float = 0.0
var _material: StandardMaterial3D = null

var _selected_room_id: int = -1
var _selected_cell: Vector3i = Vector3i(-1, -1, -1)   # re-resolves the id across RoomManager rebuilds

var _window_layer: CanvasLayer = null
var _window_panel: PanelContainer = null
var _window_title: Label = null
var _window_info: Label = null
var _window_accum: float = 0.0


func _ready() -> void:
	var dock := get_node_or_null(dock_ui_path)
	if dock != null:
		if dock.has_method("register_room_controller"):
			dock.call("register_room_controller", self)
		if dock.has_signal("tool_requested"):
			dock.connect("tool_requested", _on_tool_requested)
	var slice_controller := get_node_or_null(slice_controller_path)
	if slice_controller != null:
		if slice_controller.has_signal("slice_changed"):
			slice_controller.connect("slice_changed", _on_slice_changed)
		if slice_controller.has_method("get_slice_y"):
			_slice_y = int(slice_controller.call("get_slice_y"))
	# Autoload → safe to reference directly (scene→autoload direction).
	RoomManager.room_updated.connect(_on_room_changed)
	RoomManager.room_removed.connect(_on_room_changed)
	_material = StandardMaterial3D.new()
	_material.vertex_color_use_as_albedo = true
	_material.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	_material.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	_material.cull_mode = BaseMaterial3D.CULL_DISABLED
	_material.no_depth_test = true    # the through-rock ghost read (see header)
	_material.render_priority = 10
	_build_window()


func _process(delta: float) -> void:
	if _window_panel != null and _window_panel.visible:
		_window_accum += delta
		if _window_accum >= WINDOW_REFRESH_S:
			_window_accum = 0.0
			_refresh_window()
	if not _active:
		return
	if _overlays_dirty:
		_rebuild_accum += delta
		if _rebuild_accum >= REBUILD_THROTTLE_S:
			_rebuild_accum = 0.0
			_overlays_dirty = false
			_rebuild_overlays()


func _unhandled_input(event: InputEvent) -> void:
	if not _active:
		return
	if event is InputEventKey and (event as InputEventKey).pressed \
			and (event as InputEventKey).keycode == KEY_ESCAPE:
		deactivate()
		get_viewport().set_input_as_handled()
		return
	if event is InputEventMouseButton:
		var mb := event as InputEventMouseButton
		if mb.button_index == MOUSE_BUTTON_LEFT and mb.pressed:
			_pick_room_at_screen(mb.position)
			get_viewport().set_input_as_handled()


# ── Tool state ────────────────────────────────────────────────────────────────

func is_active() -> bool:
	return _active


func toggle_active() -> void:
	if _active:
		deactivate()
	else:
		activate()


func activate() -> void:
	if _active:
		return
	_active = true
	_rebuild_overlays()
	tool_active_changed.emit(true)


func deactivate() -> void:
	if not _active:
		return
	_active = false
	_clear_overlays()
	_close_window()
	_selected_room_id = -1
	_selected_cell = Vector3i(-1, -1, -1)
	tool_active_changed.emit(false)


func _on_tool_requested(tool_id: String) -> void:
	# One active click-tool at a time: our id toggles us; any other closes us.
	if tool_id == TOOL_ID:
		toggle_active()
	elif _active:
		deactivate()


func _on_slice_changed(new_slice_y: int) -> void:
	_slice_y = new_slice_y
	if _active:
		_apply_slice_visibility()


func _on_room_changed(_room_id: int) -> void:
	if _active:
		_overlays_dirty = true


# ── Overlays ──────────────────────────────────────────────────────────────────

func _clear_overlays() -> void:
	if _overlay_root != null and is_instance_valid(_overlay_root):
		_overlay_root.queue_free()
	_overlay_root = null
	_overlays.clear()


## Full rebuild from RoomManager (room ids are reassigned on every manager
## rebuild, so per-room diffing would buy nothing — room counts are small).
func _rebuild_overlays() -> void:
	_clear_overlays()
	_overlay_root = Node3D.new()
	_overlay_root.name = "RoomOverlays"
	add_child(_overlay_root)
	# Re-resolve the selection across the id churn (see _selected_cell).
	if _selected_cell.x >= 0:
		_selected_room_id = int(RoomManager.get_room_id_at(_selected_cell))
		if _selected_room_id < 0:
			_close_window()   # the clicked room no longer exists (seal broke)
	var rooms: Dictionary = RoomManager.get_rooms()
	for room_id: int in rooms.keys():
		var room: Dictionary = rooms[room_id]
		_overlays[room_id] = _build_room_overlay(room_id, room)
	_apply_slice_visibility()
	_refresh_window()


## Volume shell (Alen, 2026-08-07 second Rooms session — "make the volume of
## the room more obvious, draw it similar to a mining zone"): instead of a
## flat floor quad, emit every EXTERIOR face of the room's air-cell volume
## (a face whose neighbour cell is outside the room), inset by SHELL_INSET,
## plus outline edges. Interior edges shared by two coplanar emitted faces
## are deduped away so the outline traces the volume's silhouette, not a
## per-block grid (the mining-zone exterior-lines lesson).
func _build_room_overlay(room_id: int, room: Dictionary) -> Dictionary:
	var cells: Dictionary = room.get("cells", {})
	var is_frozen: bool = bool(room.get("is_frozen_vault", false))
	var fill_color: Color = FROZEN_FILL if is_frozen else SEALED_FILL
	var line_color: Color = FROZEN_LINE if is_frozen else SEALED_LINE
	if room_id == _selected_room_id:
		fill_color.a = SELECTED_FILL_ALPHA

	var fill_verts := PackedVector3Array()
	var fill_colors := PackedColorArray()
	var fill_indices := PackedInt32Array()
	var edge_count: Dictionary = {}     # edge key -> [count, Vector3 a, Vector3 b]
	var base_y := SLICE_OFF_Y
	for cell: Vector3i in cells.keys():
		if cell.y < base_y:
			base_y = cell.y
		for face: int in range(6):
			var normal: Vector3i = _FACE_NORMALS[face]
			if cells.has(cell + normal):
				continue   # interior face — the volume continues
			var corners := _face_corners(cell, face, SHELL_INSET)
			var i0 := fill_verts.size()
			for corner: Vector3 in corners:
				fill_verts.append(corner)
				fill_colors.append(fill_color)
			# Winding both ways is irrelevant — material is CULL_DISABLED.
			fill_indices.append_array(PackedInt32Array([i0, i0 + 1, i0 + 2, i0, i0 + 2, i0 + 3]))
			# Outline edges are counted at the TRUE cell boundary (inset 0),
			# so the two perpendicular faces meeting at a corner contribute
			# IDENTICAL endpoints and merge into ONE drawn line (Alen,
			# 2026-08-07 third Rooms session: the inset edge positions drew
			# visible double lines at every corner).
			var line_corners := _face_corners(cell, face, 0.0)
			for e: int in range(4):
				_count_edge(edge_count, line_corners[e], line_corners[(e + 1) % 4], face)

	var line_verts := PackedVector3Array()
	var line_colors := PackedColorArray()
	for key: String in edge_count.keys():
		var entry: Array = edge_count[key]
		var faces: Dictionary = entry[2]
		# Skip only FLAT-WALL CONTINUATIONS: every contribution from one face
		# orientation (two coplanar faces sharing the edge). A crease — two
		# different orientations meeting (corner), with or without a flat run
		# through it — and a single-face rim (e.g. a doorway border) draw.
		if faces.size() == 1 and int(faces.values()[0]) >= 2:
			continue
		line_verts.append(entry[0])
		line_verts.append(entry[1])
		line_colors.append(line_color)
		line_colors.append(line_color)

	var root := Node3D.new()
	root.name = "Room%d" % room_id
	_overlay_root.add_child(root)
	if not fill_verts.is_empty():
		var fill_mesh := ArrayMesh.new()
		var arrays: Array = []
		arrays.resize(Mesh.ARRAY_MAX)
		arrays[Mesh.ARRAY_VERTEX] = fill_verts
		arrays[Mesh.ARRAY_COLOR] = fill_colors
		arrays[Mesh.ARRAY_INDEX] = fill_indices
		fill_mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)
		var fill_node := MeshInstance3D.new()
		fill_node.mesh = fill_mesh
		fill_node.material_override = _material
		root.add_child(fill_node)
	if not line_verts.is_empty():
		var line_mesh := ArrayMesh.new()
		var line_arrays: Array = []
		line_arrays.resize(Mesh.ARRAY_MAX)
		line_arrays[Mesh.ARRAY_VERTEX] = line_verts
		line_arrays[Mesh.ARRAY_COLOR] = line_colors
		line_mesh.add_surface_from_arrays(Mesh.PRIMITIVE_LINES, line_arrays)
		var line_node := MeshInstance3D.new()
		line_node.mesh = line_mesh
		line_node.material_override = _material
		root.add_child(line_node)
	return { "root": root, "base_y": base_y }


## Four corners of `face` of the unit cell at `cell`, pulled `inset` inward
## along the face NORMAL only — tangent extents stay full-cell, so adjacent
## coplanar faces share exact edge endpoints and the outline dedupe in
## _build_room_overlay works by string key. Fill uses SHELL_INSET (avoids
## z-fighting the walls); outline edges use 0.0 (single line per corner).
func _face_corners(cell: Vector3i, face: int, inset: float) -> Array[Vector3]:
	var x0 := float(cell.x)
	var y0 := float(cell.y)
	var z0 := float(cell.z)
	var x1 := x0 + 1.0
	var y1 := y0 + 1.0
	var z1 := z0 + 1.0
	if face == 0:
		var xa := x1 - inset
		return [Vector3(xa, y0, z0), Vector3(xa, y1, z0), Vector3(xa, y1, z1), Vector3(xa, y0, z1)]
	if face == 1:
		var xb := x0 + inset
		return [Vector3(xb, y0, z0), Vector3(xb, y1, z0), Vector3(xb, y1, z1), Vector3(xb, y0, z1)]
	if face == 2:
		var ya := y1 - inset
		return [Vector3(x0, ya, z0), Vector3(x1, ya, z0), Vector3(x1, ya, z1), Vector3(x0, ya, z1)]
	if face == 3:
		var yb := y0 + inset
		return [Vector3(x0, yb, z0), Vector3(x1, yb, z0), Vector3(x1, yb, z1), Vector3(x0, yb, z1)]
	if face == 4:
		var za := z1 - inset
		return [Vector3(x0, y0, za), Vector3(x1, y0, za), Vector3(x1, y1, za), Vector3(x0, y1, za)]
	var zb := z0 + inset
	return [Vector3(x0, y0, zb), Vector3(x1, y0, zb), Vector3(x1, y1, zb), Vector3(x0, y1, zb)]


## Undirected edge counter keyed on quantised endpoints (the mining
## controller's string-key edge dedupe, at 1/100 precision). Tracks which
## FACE ORIENTATION (0..5) contributed each occurrence, so the draw pass can
## tell a flat-wall continuation (same orientation twice → skip) from a
## crease or rim (draw).
func _count_edge(edges: Dictionary, a: Vector3, b: Vector3, face: int) -> void:
	var ka := "%d,%d,%d" % [roundi(a.x * 100.0), roundi(a.y * 100.0), roundi(a.z * 100.0)]
	var kb := "%d,%d,%d" % [roundi(b.x * 100.0), roundi(b.y * 100.0), roundi(b.z * 100.0)]
	var key := ka + "|" + kb if ka < kb else kb + "|" + ka
	if edges.has(key):
		var faces: Dictionary = edges[key][2]
		faces[face] = int(faces.get(face, 0)) + 1
	else:
		edges[key] = [a, b, { face: 1 }]


## Coarse per-room slice culling (the SurfaceFloraSpawner convention): a room
## whose floor sits above the cut plane hides; slice off (Y127) shows all.
func _apply_slice_visibility() -> void:
	for room_id: int in _overlays.keys():
		var entry: Dictionary = _overlays[room_id]
		var root_node: Node3D = entry["root"]
		if root_node != null and is_instance_valid(root_node):
			root_node.visible = int(entry["base_y"]) <= _slice_y


# ── Picking ───────────────────────────────────────────────────────────────────

## March the mouse ray through the grid; select the first room whose interior
## air it crosses. Cells above the slice are skipped; solid rock does NOT stop
## the march (x-ray clicks, matching the no-depth overlays — see header).
func _pick_room_at_screen(screen_pos: Vector2) -> void:
	var camera := get_viewport().get_camera_3d()
	if camera == null:
		return
	var origin := camera.project_ray_origin(screen_pos)
	var direction := camera.project_ray_normal(screen_pos).normalized()
	var last_cell := Vector3i(-999999, -999999, -999999)
	var distance := 0.0
	while distance <= RAY_MAX:
		var sample := origin + direction * distance
		var cell := Vector3i(floori(sample.x), floori(sample.y), floori(sample.z))
		if cell != last_cell:
			last_cell = cell
			if cell.y <= _slice_y:
				var room_id := int(RoomManager.get_room_id_at(cell))
				if room_id >= 0:
					_select_room(room_id, cell)
					return
		distance += RAY_STEP
	# Clicked empty space: keep the current selection (closing is the ✕'s job).


func _select_room(room_id: int, cell: Vector3i) -> void:
	var previous := _selected_room_id
	_selected_room_id = room_id
	_selected_cell = cell
	if previous != room_id:
		_overlays_dirty = true   # retint selected/deselected fills on the throttle
	_open_window()
	_refresh_window()


# ── Info window (doc 34 "UI — Room Temperature Display") ─────────────────────

func _build_window() -> void:
	_window_layer = CanvasLayer.new()
	_window_layer.name = "RoomInfoWindow"
	_window_layer.layer = 22
	add_child(_window_layer)

	_window_panel = PanelContainer.new()
	_window_panel.position = Vector2(24.0, 432.0)   # below the slice palette
	_window_panel.visible = false
	var style := StyleBoxFlat.new()
	style.bg_color = Color(0.065, 0.070, 0.075, 0.94)
	style.border_color = Color(1, 1, 1, 0.12)
	style.set_border_width_all(1)
	style.set_corner_radius_all(8)
	style.set_content_margin_all(10.0)
	_window_panel.add_theme_stylebox_override("panel", style)
	_window_layer.add_child(_window_panel)

	var column := VBoxContainer.new()
	column.add_theme_constant_override("separation", 6)
	_window_panel.add_child(column)

	var header := HBoxContainer.new()
	header.add_theme_constant_override("separation", 8)
	column.add_child(header)

	_window_title = Label.new()
	_window_title.text = "🚪 Room"
	_window_title.add_theme_font_size_override("font_size", 14)
	_window_title.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	header.add_child(_window_title)

	var close := Button.new()
	close.text = "✕"
	close.flat = true
	close.pressed.connect(func() -> void: _close_window())
	header.add_child(close)

	_window_info = Label.new()
	_window_info.add_theme_font_size_override("font_size", 13)
	_window_info.text = ""
	column.add_child(_window_info)


func _open_window() -> void:
	_window_accum = 0.0
	if _window_panel != null:
		_window_panel.visible = true


func _close_window() -> void:
	if _window_panel != null:
		_window_panel.visible = false


## EXPLICIT TYPES at every Dictionary read — the RoomManager/WorldClock
## Variant-inference trap (see RoomManager._recompute_temp header note).
func _refresh_window() -> void:
	if _window_panel == null or not _window_panel.visible:
		return
	if _selected_room_id < 0:
		_close_window()
		return
	var room: Dictionary = RoomManager.get_rooms().get(_selected_room_id, {})
	if room.is_empty():
		_window_title.text = "🚪 Room %d" % _selected_room_id
		_window_info.text = "No longer sealed —\nthe seal was broken."
		return
	var temp_c: float = float(room.get("temp_c", 0.0))
	var volume: int = int(room.get("volume", 0))
	var heat_units: int = int(room.get("heat_units", 0))
	var mean_floor_y: float = float(room.get("mean_floor_y", 0.0))
	var seasonal: float = float(room.get("seasonal_influence", 0.0))
	var is_frozen: bool = bool(room.get("is_frozen_vault", false))
	var doors: int = room.get("door_cells", {}).size()
	var heat_bonus: float = float(heat_units) / float(max(volume, 1))
	_window_title.text = "🚪 Room %d" % _selected_room_id
	var status := "FROZEN VAULT ❄" if is_frozen else "Sealed (%s)" % _zone_name(mean_floor_y)
	_window_info.text = "\n".join([
		status,
		"Temperature: %.1f°C" % temp_c,
		"Volume: %d blocks" % volume,
		"Heat sources: %d units (+%.1f°C)" % [heat_units, heat_bonus],
		"Doors: %d" % doors,
		"Seasonal influence: %d%%" % roundi(seasonal * 100.0),
		"Mean floor Y: %.1f" % mean_floor_y,
	])


## Depth-zone label from mean floor Y (doc 34 "Depth–Temperature Gradient").
func _zone_name(mean_floor_y: float) -> String:
	if mean_floor_y >= 65.0:
		return "Cool Cave"
	if mean_floor_y >= 50.0:
		return "Cold Cave"
	if mean_floor_y >= 37.0:
		return "Deep Cold"
	return "Frozen Zone"

source_text.scripts/systems/SaveManager.gd:
extends Node

## Versioned manual/autosave coordinator. The deterministic world seed is the
## base; scene owners persist only authoritative player/colony deltas.
## Scheduler tasks, reservations, renderer caches, and derived interior/nav
## data rebuild.

const SAVE_DIRECTORY := "user://saves"
const SAVE_PATH := "user://saves/quicksave.json"
const BACKUP_SAVE_PATH := "user://saves/quicksave.backup.json"
const TEMP_SAVE_PATH := "user://saves/quicksave.tmp.json"
const BACKUP_STAGE_PATH := "user://saves/quicksave.backup.tmp.json"
const AUTOSAVE_PATH := "user://saves/autosave.json"
const AUTOSAVE_BACKUP_PATH := "user://saves/autosave.backup.json"
const AUTOSAVE_TEMP_PATH := "user://saves/autosave.tmp.json"
const AUTOSAVE_BACKUP_STAGE_PATH := "user://saves/autosave.backup.tmp.json"
const AUTOSAVE_INTERVAL_SECONDS := 300.0
const SAVE_SCHEMA_VERSION := 1
const OWNER_GROUP := "save_state_owner"

signal save_finished(success: bool)
signal autosave_finished(success: bool)
signal load_finished(success: bool, used_backup: bool)

var _dock_ui: Node = null
var _pending_restore: Dictionary = {}
var _loading: bool = false
var _ready_frames: int = 0
var _loading_from_backup: bool = false
var _loading_autosave: bool = false
var _clock_was_paused_before_load: bool = false
var _autosave_elapsed_seconds: float = 0.0
# ── LoadPerformance stamps ────────────────────────────────────────────────────
# Times the load pipeline: request → read/validate → scene reload + regen wait
# → per-owner restore. Printed by _print_load_performance at restore end. The
# post-restore overview tile rebuild is timed separately by SliceTiming.
var _load_request_msec: int = 0
var _load_validated_msec: int = 0

var _save_directory_path: String = SAVE_DIRECTORY
var _save_path: String = SAVE_PATH
var _backup_save_path: String = BACKUP_SAVE_PATH
var _temp_save_path: String = TEMP_SAVE_PATH
var _backup_stage_path: String = BACKUP_STAGE_PATH
var _autosave_path: String = AUTOSAVE_PATH
var _autosave_backup_path: String = AUTOSAVE_BACKUP_PATH
var _autosave_temp_path: String = AUTOSAVE_TEMP_PATH
var _autosave_backup_stage_path: String = AUTOSAVE_BACKUP_STAGE_PATH


## Isolates automated tests from the player's real quick-save files. This is
## intentionally unavailable in release builds.
func configure_storage_for_testing(directory: String) -> bool:
	if not OS.is_debug_build():
		push_error("SaveManager: test storage can only be configured in a debug build.")
		return false
	var normalized := directory.trim_suffix("/")
	if not normalized.begins_with("user://") or normalized == "user://":
		push_error("SaveManager: test storage must be a dedicated user:// subdirectory.")
		return false
	_save_directory_path = normalized
	_save_path = normalized.path_join("quicksave.json")
	_backup_save_path = normalized.path_join("quicksave.backup.json")
	_temp_save_path = normalized.path_join("quicksave.tmp.json")
	_backup_stage_path = normalized.path_join("quicksave.backup.tmp.json")
	_autosave_path = normalized.path_join("autosave.json")
	_autosave_backup_path = normalized.path_join("autosave.backup.json")
	_autosave_temp_path = normalized.path_join("autosave.tmp.json")
	_autosave_backup_stage_path = normalized.path_join("autosave.backup.tmp.json")
	_autosave_elapsed_seconds = 0.0
	return true


func reset_storage_after_testing() -> void:
	_save_directory_path = SAVE_DIRECTORY
	_save_path = SAVE_PATH
	_backup_save_path = BACKUP_SAVE_PATH
	_temp_save_path = TEMP_SAVE_PATH
	_backup_stage_path = BACKUP_STAGE_PATH
	_autosave_path = AUTOSAVE_PATH
	_autosave_backup_path = AUTOSAVE_BACKUP_PATH
	_autosave_temp_path = AUTOSAVE_TEMP_PATH
	_autosave_backup_stage_path = AUTOSAVE_BACKUP_STAGE_PATH
	_autosave_elapsed_seconds = 0.0


func register_dock(dock: Node) -> void:
	_dock_ui = dock
	if not dock.is_connected("save_game_requested", request_save):
		dock.connect("save_game_requested", request_save)
	if not dock.is_connected("load_game_requested", request_load):
		dock.connect("load_game_requested", request_load)
	if not dock.is_connected("load_autosave_requested", request_load_autosave):
		dock.connect("load_autosave_requested", request_load_autosave)
	if _loading:
		_notify("Loading autosave…" if _loading_autosave else "Loading quick save…")


func generation_seed_for_new_scene(fallback: int) -> int:
	if _loading and not _pending_restore.is_empty():
		return int(_pending_restore.get("world_seed", fallback))
	return fallback


## Slice height stored in the pending restore snapshot, or `fallback` when no
## load is in flight. WorldRenderer polls this right before queueing the first
## overview tiles, so a load builds every tile cut at the restored plane the
## FIRST time — previously the startup tiles built at the default plane (127)
## and the slice restore (priority 80) re-queued and re-built them.
## SliceController's own restore then applies the same value and its setter
## no-ops the requeue (old_y == v).
func pending_slice_for_new_scene(fallback: int) -> int:
	if not _loading or _pending_restore.is_empty():
		return fallback
	var scene_state: Dictionary = _pending_restore.get("scene", {})
	var slice_state: Dictionary = scene_state.get("slice", {})
	return int(slice_state.get("slice_y", fallback))


func request_save() -> bool:
	if _loading:
		return _fail_save("A save is currently loading.")
	if not bool(WorldGenerator.get_streaming_stats().get("maps_ready", false)):
		return _fail_save("The world is still generating; try Save again shortly.")

	var commit_error := _commit_snapshot(_build_snapshot(), _quick_save_paths())
	if not commit_error.is_empty():
		return _fail_save("Save failed: %s" % commit_error)
	_notify("Game saved.")
	print("SaveManager: validated quick save written to %s." % _save_path)
	save_finished.emit(true)
	return true


func request_autosave() -> bool:
	if _loading or not _world_ready_for_autosave():
		return false
	var commit_error := _commit_snapshot(_build_snapshot(), _autosave_paths())
	if not commit_error.is_empty():
		_notify("Autosave failed: %s" % commit_error, true)
		autosave_finished.emit(false)
		return false
	_notify("Autosaved.")
	print("SaveManager: validated autosave written to %s." % _autosave_path)
	autosave_finished.emit(true)
	return true


func _build_snapshot() -> Dictionary:
	return {
		"schema_version": SAVE_SCHEMA_VERSION,
		"project": "Deepdraft",
		"saved_at_utc": Time.get_datetime_string_from_system(true, true),
		"world_seed": WorldGenerator.world_seed,
		"clock": WorldClock.serialize_state(),
		"weather": WeatherManager.serialize_state(),
		"scene": _collect_scene_state(),
	}


func request_load() -> bool:
	return _request_load_slot(_quick_save_paths(), false)


func request_load_autosave() -> bool:
	return _request_load_slot(_autosave_paths(), true)


func _request_load_slot(paths: Dictionary, is_autosave: bool) -> bool:
	if _loading:
		return _fail_load("A save is already loading.")

	_load_request_msec = Time.get_ticks_msec()
	var primary_path := String(paths.get("primary", ""))
	var backup_path := String(paths.get("backup", ""))
	var slot_name := "autosave" if is_autosave else "quick save"
	var primary_result := _read_snapshot(primary_path)
	var selected_result: Dictionary = primary_result
	var use_backup := false
	if not bool(primary_result.get("ok", false)):
		var backup_result := _read_snapshot(backup_path)
		if not bool(backup_result.get("ok", false)):
			if bool(primary_result.get("missing", false)) \
					and bool(backup_result.get("missing", false)):
				return _fail_load("No autosave exists yet." if is_autosave else "No quick save exists yet.")
			var details: Array[String] = []
			if not bool(primary_result.get("missing", false)):
				details.append("primary %s" % String(primary_result.get("error", "is invalid")))
			if not bool(backup_result.get("missing", false)):
				details.append("backup %s" % String(backup_result.get("error", "is invalid")))
			return _fail_load("Load failed: %s." % "; ".join(details))
		selected_result = backup_result
		use_backup = true
		push_warning("SaveManager: primary %s unavailable (%s); using backup." \
			% [slot_name, String(primary_result.get("error", "missing"))])
		var repair_error := _restore_primary_from_backup(paths)
		if not repair_error.is_empty():
			push_warning("SaveManager: %s backup is valid but primary repair failed: %s" \
				% [slot_name, repair_error])

	var snapshot: Dictionary = selected_result.get("snapshot", {})
	_load_validated_msec = Time.get_ticks_msec()
	_pending_restore = snapshot
	_loading = true
	_ready_frames = 0
	_loading_from_backup = use_backup
	_loading_autosave = is_autosave
	_clock_was_paused_before_load = WorldClock.paused
	if is_autosave:
		_notify("Recovering autosave backup…" if use_backup else "Loading autosave…")
	else:
		_notify("Recovering backup save…" if use_backup else "Loading quick save…")
	WorldClock.set_paused(true)
	TaskManager.reset_runtime_state()
	StockpileManager.reset_runtime_state()
	InteriorTracker.clear_runtime_state()
	NavGrid.clear_runtime_state()
	PlacedEntityRegistry.clear_runtime_state()
	WorldGenerator.prepare_for_world_reload()
	WorldData.clear_world()
	var scene_tree := get_tree()
	var scene_changed_callback := Callable(self, "_on_scene_reloaded")
	if not scene_tree.scene_changed.is_connected(scene_changed_callback):
		scene_tree.scene_changed.connect(scene_changed_callback, CONNECT_ONE_SHOT)
	var reload_error := scene_tree.reload_current_scene()
	if reload_error != OK:
		if scene_tree.scene_changed.is_connected(scene_changed_callback):
			scene_tree.scene_changed.disconnect(scene_changed_callback)
		_loading = false
		_pending_restore.clear()
		WorldClock.set_paused(_clock_was_paused_before_load)
		var failed_from_backup := _loading_from_backup
		_loading_from_backup = false
		_loading_autosave = false
		_notify("Load failed: the world scene could not be reloaded.", true)
		load_finished.emit(false, failed_from_backup)
		return false
	return true


func _on_scene_reloaded() -> void:
	if _loading:
		SkyController.rebind_to_current_scene()


func _process(delta: float) -> void:
	if not _loading:
		_tick_autosave(delta)
		return
	if _pending_restore.is_empty():
		return
	var stats := WorldGenerator.get_streaming_stats()
	if not bool(stats.get("maps_ready", false)) or WorldGenerator.is_generating():
		_ready_frames = 0
		return
	# Two quiet frames let scene owners and seed-derived flora finish their
	# ready/deferred hookups before player state is reapplied.
	_ready_frames += 1
	if _ready_frames < 2:
		return
	_restore_pending_snapshot()


func _tick_autosave(delta: float) -> void:
	if not _world_ready_for_autosave():
		return
	_autosave_elapsed_seconds += delta
	if _autosave_elapsed_seconds < AUTOSAVE_INTERVAL_SECONDS:
		return
	# Reset after the attempt so a disk error reports at most once per interval.
	_autosave_elapsed_seconds = 0.0
	request_autosave()


func _world_ready_for_autosave() -> bool:
	var stats := WorldGenerator.get_streaming_stats()
	return bool(stats.get("maps_ready", false)) and not WorldGenerator.is_generating()


func _collect_scene_state() -> Dictionary:
	var result: Dictionary = {}
	for state_owner in get_tree().get_nodes_in_group(OWNER_GROUP):
		if not state_owner.has_method("save_section_key") or not state_owner.has_method("serialize_state"):
			continue
		var key := String(state_owner.call("save_section_key"))
		if key.is_empty():
			continue
		result[key] = state_owner.call("serialize_state")
	return result


func _restore_pending_snapshot() -> void:
	var t_restore_start := Time.get_ticks_msec()
	var owner_lines: Array[String] = []
	var scene_state: Dictionary = _pending_restore.get("scene", {})
	var owners: Array = get_tree().get_nodes_in_group(OWNER_GROUP)
	owners.sort_custom(func(a: Node, b: Node) -> bool:
		var ap := int(a.call("save_restore_priority")) if a.has_method("save_restore_priority") else 100
		var bp := int(b.call("save_restore_priority")) if b.has_method("save_restore_priority") else 100
		return ap < bp)
	for state_owner in owners:
		if not state_owner.has_method("save_section_key") or not state_owner.has_method("restore_state"):
			continue
		var key := String(state_owner.call("save_section_key"))
		if scene_state.has(key):
			var t_owner := Time.get_ticks_msec()
			state_owner.call("restore_state", scene_state[key] as Dictionary)
			owner_lines.append("    %s: %d ms" % [key, Time.get_ticks_msec() - t_owner])

	var t_owners_end := Time.get_ticks_msec()
	StockpileManager.rebuild_totals()
	WorldClock.restore_state(_pending_restore.get("clock", {}) as Dictionary)
	WeatherManager.restore_state(_pending_restore.get("weather", {}) as Dictionary)
	_print_load_performance(t_restore_start, t_owners_end, owner_lines)
	var restored_from_backup := _loading_from_backup
	var restored_autosave := _loading_autosave
	_pending_restore.clear()
	_loading = false
	_ready_frames = 0
	_loading_from_backup = false
	_loading_autosave = false
	_autosave_elapsed_seconds = 0.0
	if restored_autosave:
		_notify("Autosave backup recovered and loaded." if restored_from_backup else "Autosave loaded.")
	else:
		_notify("Backup recovered and loaded." if restored_from_backup else "Game loaded.")
	var slot_name := "autosave" if restored_autosave else "quick save"
	print("SaveManager: %s%s restored." % ["backup " if restored_from_backup else "", slot_name])
	load_finished.emit(true, restored_from_backup)


## Where did load time go? request→validate is disk + JSON parse; validate→
## restore-start is the scene reload plus the FULL deterministic regen (map
## precompute dominates — the same ~10 s StartupPerformance reports on a cold
## boot) plus the two quiet frames; then each owner's restore_state is timed
## individually so growth in one section (e.g. mined_blocks) shows up by name.
## The overview tile rebuild the restored slice triggers AFTER this point is
## reported by SliceTiming when its queue drains.
func _print_load_performance(t_restore_start: int, t_owners_end: int, owner_lines: Array[String]) -> void:
	var t_end := Time.get_ticks_msec()
	print("LoadPerformance:")
	print("  total_request_to_restored: %.3f s" % (float(t_end - _load_request_msec) / 1000.0))
	print("  read_validate: %d ms" % (_load_validated_msec - _load_request_msec))
	print("  reload_regen_wait: %.3f s (map precompute + quiet frames — see StartupPerformance)" \
		% (float(t_restore_start - _load_validated_msec) / 1000.0))
	print("  restore_owners: %d ms" % (t_owners_end - t_restore_start))
	for line in owner_lines:
		print(line)
	print("  totals_clock_weather: %d ms" % (t_end - t_owners_end))
	print("  note: post-restore overview tile rebuild reported by SliceTiming.")


func _quick_save_paths() -> Dictionary:
	return {
		"primary": _save_path,
		"backup": _backup_save_path,
		"temp": _temp_save_path,
		"backup_stage": _backup_stage_path,
	}


func _autosave_paths() -> Dictionary:
	return {
		"primary": _autosave_path,
		"backup": _autosave_backup_path,
		"temp": _autosave_temp_path,
		"backup_stage": _autosave_backup_stage_path,
	}


func _commit_snapshot(snapshot: Dictionary, paths: Dictionary) -> String:
	var dir_error := DirAccess.make_dir_recursive_absolute(
		ProjectSettings.globalize_path(_save_directory_path))
	if dir_error != OK and dir_error != ERR_ALREADY_EXISTS:
		return "could not create the saves folder (%s)." % error_string(dir_error)

	var temp_path := String(paths.get("temp", ""))
	var backup_stage_path := String(paths.get("backup_stage", ""))
	var cleanup_error := _remove_if_exists(temp_path)
	if not cleanup_error.is_empty():
		return cleanup_error
	cleanup_error = _remove_if_exists(backup_stage_path)
	if not cleanup_error.is_empty():
		return cleanup_error

	var write_error := _write_text_file(temp_path, JSON.stringify(snapshot, "\t"))
	if not write_error.is_empty():
		return write_error
	var temp_result := _read_snapshot(temp_path)
	if not bool(temp_result.get("ok", false)):
		_remove_if_exists(temp_path)
		return "temporary save validation failed: %s" % String(temp_result.get("error", "invalid file"))

	var rotation_error := _rotate_primary_to_backup_if_valid(paths)
	if not rotation_error.is_empty():
		_remove_if_exists(temp_path)
		return rotation_error

	var replace_error := _replace_primary_with_temp(paths)
	if not replace_error.is_empty():
		_remove_if_exists(temp_path)
		return replace_error
	return ""


func _rotate_primary_to_backup_if_valid(paths: Dictionary) -> String:
	var primary_path := String(paths.get("primary", ""))
	var backup_path := String(paths.get("backup", ""))
	var backup_stage_path := String(paths.get("backup_stage", ""))
	var primary_result := _read_snapshot(primary_path)
	if not bool(primary_result.get("ok", false)):
		if not bool(primary_result.get("missing", false)):
			push_warning("SaveManager: existing primary is invalid and will not replace the backup (%s)." \
				% String(primary_result.get("error", "invalid file")))
		return ""

	var copy_error := DirAccess.copy_absolute(
		ProjectSettings.globalize_path(primary_path),
		ProjectSettings.globalize_path(backup_stage_path))
	if copy_error != OK:
		return "could not stage the previous save as a backup (%s)." % error_string(copy_error)
	var staged_result := _read_snapshot(backup_stage_path)
	if not bool(staged_result.get("ok", false)):
		_remove_if_exists(backup_stage_path)
		return "staged backup validation failed: %s" % String(staged_result.get("error", "invalid file"))

	var remove_error := _remove_if_exists(backup_path)
	if not remove_error.is_empty():
		_remove_if_exists(backup_stage_path)
		return remove_error
	var rename_error := DirAccess.rename_absolute(
		ProjectSettings.globalize_path(backup_stage_path),
		ProjectSettings.globalize_path(backup_path))
	if rename_error != OK:
		_remove_if_exists(backup_stage_path)
		return "could not install the validated backup (%s)." % error_string(rename_error)
	return ""


func _replace_primary_with_temp(paths: Dictionary) -> String:
	var primary_path := String(paths.get("primary", ""))
	var temp_path := String(paths.get("temp", ""))
	var remove_error := _remove_if_exists(primary_path)
	if not remove_error.is_empty():
		return remove_error
	var rename_error := DirAccess.rename_absolute(
		ProjectSettings.globalize_path(temp_path),
		ProjectSettings.globalize_path(primary_path))
	if rename_error != OK:
		var recovery_error := _restore_primary_from_backup(paths)
		if recovery_error.is_empty():
			return "could not install the new save; the previous backup was restored (%s)." \
				% error_string(rename_error)
		return "could not install the new save (%s); recovery also failed: %s" \
			% [error_string(rename_error), recovery_error]

	var installed_result := _read_snapshot(primary_path)
	if not bool(installed_result.get("ok", false)):
		var validation_error := String(installed_result.get("error", "invalid file"))
		var recovery_error := _restore_primary_from_backup(paths)
		if recovery_error.is_empty():
			return "installed save failed validation; the previous backup was restored (%s)." \
				% validation_error
		return "installed save failed validation (%s); recovery also failed: %s" \
			% [validation_error, recovery_error]
	return ""


func _restore_primary_from_backup(paths: Dictionary) -> String:
	var primary_path := String(paths.get("primary", ""))
	var backup_path := String(paths.get("backup", ""))
	var backup_result := _read_snapshot(backup_path)
	if not bool(backup_result.get("ok", false)):
		return "no valid backup is available (%s)." % String(backup_result.get("error", "missing"))
	var remove_error := _remove_if_exists(primary_path)
	if not remove_error.is_empty():
		return remove_error
	var copy_error := DirAccess.copy_absolute(
		ProjectSettings.globalize_path(backup_path),
		ProjectSettings.globalize_path(primary_path))
	if copy_error != OK:
		return "could not copy the backup into the primary slot (%s)." % error_string(copy_error)
	var restored_result := _read_snapshot(primary_path)
	if not bool(restored_result.get("ok", false)):
		return "recovered primary failed validation: %s" \
			% String(restored_result.get("error", "invalid file"))
	return ""


func _write_text_file(path: String, contents: String) -> String:
	var file := FileAccess.open(path, FileAccess.WRITE)
	if file == null:
		return "could not open %s for writing." % path
	file.store_string(contents)
	file.flush()
	var write_error := file.get_error()
	file.close()
	if write_error != OK:
		return "write failed for %s (%s)." % [path, error_string(write_error)]
	return ""


func _read_snapshot(path: String) -> Dictionary:
	if not FileAccess.file_exists(path):
		return { "ok": false, "missing": true, "error": "is missing" }
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		return { "ok": false, "missing": false, "error": "could not be opened" }
	var contents := file.get_as_text()
	file.close()
	var json := JSON.new()
	var parse_error := json.parse(contents)
	if parse_error != OK or not (json.data is Dictionary):
		return { "ok": false, "missing": false, "error": "contains invalid JSON" }
	var snapshot: Dictionary = json.data
	var validation_error := _validate_snapshot(snapshot)
	if not validation_error.is_empty():
		return { "ok": false, "missing": false, "error": validation_error }
	return { "ok": true, "missing": false, "error": "", "snapshot": snapshot }


func _remove_if_exists(path: String) -> String:
	if not FileAccess.file_exists(path):
		return ""
	var remove_error := DirAccess.remove_absolute(ProjectSettings.globalize_path(path))
	if remove_error != OK:
		return "could not remove %s (%s)." % [path, error_string(remove_error)]
	return ""


func _fail_save(message: String) -> bool:
	_notify(message, true)
	save_finished.emit(false)
	return false


func _fail_load(message: String) -> bool:
	_notify(message, true)
	load_finished.emit(false, false)
	return false


func _validate_snapshot(snapshot: Dictionary) -> String:
	if String(snapshot.get("project", "")) != "Deepdraft":
		return "this file belongs to a different project."
	var version := int(snapshot.get("schema_version", 0))
	if version < 1:
		return "the save schema is missing."
	if version > SAVE_SCHEMA_VERSION:
		return "this save was made by a newer game version."
	if int(snapshot.get("world_seed", 0)) == 0:
		return "the world seed is missing."
	if not (snapshot.get("scene", null) is Dictionary):
		return "scene state is missing."
	return ""


func _notify(message: String, is_error: bool = false) -> void:
	if _dock_ui != null and is_instance_valid(_dock_ui) \
			and _dock_ui.has_method("show_persistence_status"):
		_dock_ui.call("show_persistence_status", message, is_error)
	elif is_error:
		push_warning("SaveManager: %s" % message)
	else:
		print("SaveManager: %s" % message)


func pack_v3i(value: Vector3i) -> Array:
	return [value.x, value.y, value.z]


func unpack_v3i(value: Variant) -> Vector3i:
	if not (value is Array) or (value as Array).size() < 3:
		return Vector3i.ZERO
	var a := value as Array
	return Vector3i(int(a[0]), int(a[1]), int(a[2]))


func pack_v3(value: Vector3) -> Array:
	return [value.x, value.y, value.z]


func unpack_v3(value: Variant) -> Vector3:
	if not (value is Array) or (value as Array).size() < 3:
		return Vector3.ZERO
	var a := value as Array
	return Vector3(float(a[0]), float(a[1]), float(a[2]))

source_text.scripts/systems/SkyController.gd:
extends Node

## Drives the scene's WorldEnvironment sky + fog and the Sun/Moon directional lights from
## data/sky/sky_settings.json, animated against WorldClock (the day/night cycle).
##
## Registered as an autoload (project.godot [autoload]), loaded after WorldClock. Render concerns
## are usually scene nodes here (WorldRenderer, Camera), but an autoload mirrors Stonehearth's
## sky_renderer *service* and avoids editing the main scene; 08_sky_plan.md §D.2 allows either.
##
## PHASE 2 (this file): each frame, evaluate the keyframed curves at the current in-game hour and
##   - tint the ProceduralSkyMaterial gradient (sky_gradient_colors curve),
##   - match the fog colour to the sky horizon and set fog density/distance (height_fog curve),
##   - move + recolour the Sun and a runtime Moon (sun/moon colour + angle_pitch curves).
## Non-time-varying renderer params (aerial perspective, sky affect, sun scatter, fog enabled,
## ambient energy) are applied once from the static 'environment' block. Ambient stays sky-sourced,
## so it darkens for free as the sky gradient darkens at night.
##
## JSON = what things are (the curves); GDScript = what things do (interpolating + applying them).

const SETTINGS_PATH := "res://data/sky/sky_settings.json"

# ── Tuning (safe to tweak; calibrate against screenshots) ─────────────────────
const SUN_ENERGY_SCALE   := 1.5    # light_energy = colour_brightness × this
const MOON_ENERGY_SCALE   := 1.5
const LIGHT_OFF_THRESHOLD := 0.02  # celestial colour brightness below this = light switched off
const UPDATE_INTERVAL     := 0.05  # seconds between sky updates (~20 Hz; sky changes slowly)
const DAY_HOURS           := 24.0
const TWILIGHT_HOURS      := 1.0   # dawn/dusk shoulder either side of sunrise/sunset
const MIN_DAYLIGHT        := 8.0   # winter-solstice daylight span (hours)
const MAX_DAYLIGHT        := 16.0  # summer-solstice daylight span (hours)
const WEATHER_BLEND       := 0.04  # per-update smoothing toward weather targets (~1.5 s settle)
const DARK_FACTOR         := 0.65  # sky/fog brightness scale when is_dark_during_daytime
const FOG_END_FRACTION    := 0.9   # fog hits FULL opacity at 0.9×far — BEFORE the far clip, so the
								   # clip only ever cuts already-invisible terrain (no hard edge).
const EDGE_FADE_START     := 0.55  # fade begins at 0.55×(fog end) — a wide, clearly visible dissolve.
const MIN_VIEW            := 32.0  # never collapse the fogged view below this many blocks
const FAR_FALLBACK        := 512.0 # used if no Camera3D is found in the scene
const FOG_DIAGNOSTIC      := false # TEMP debug: forces an unmistakable RED fog. Leave false.
const FOG_SATURATION      := 3.0   # exponential density × distance at the saturation point (~95% opacity)
const MANAGE_FOG          := false # keep Environment fog inactive; sky/fog solution is still under review.

# Fallback event hours if WorldClock has none (matches data/calendar/calendar.json).
const DEFAULT_EVENT_HOURS := {
	"midnight": 0, "sunrise_start": 5, "sunrise": 6, "sunrise_end": 7,
	"midday": 14, "sunset_start": 20, "sunset": 21, "sunset_end": 22,
}

var _settings: Dictionary = {}
var _clock: Node = null
var _world_env: WorldEnvironment = null
var _env: Environment = null
var _sky_mat: ProceduralSkyMaterial = null
var _sun: DirectionalLight3D = null
var _moon: DirectionalLight3D = null
var _camera: Camera3D = null
var _renderer: Node = null   # optional renderer hook for future fog/radius coupling.
var _sun_yaw: float = 45.0
var _moon_yaw: float = 225.0

# Precomputed curves — each is a sorted Array of [hour: float, value] (value = Color or float).
var _c_sky_top: Array = []
var _c_sky_horizon: Array = []
var _c_sky_ground: Array = []
var _c_sun_color: Array = []
var _c_sun_pitch: Array = []
var _c_moon_color: Array = []
var _c_moon_pitch: Array = []
var _c_fog_thickness: Array = []
var _c_fog_distance: Array = []

var _event_hours: Dictionary = {}
var _accum: float = 0.0
var _ready_ok: bool = false

# Weather state — applied target, smoothed by _update for soft transitions.
var _active_weather: Dictionary = {}
var _c_fog_thickness_w: Array = []
var _c_fog_distance_w: Array = []
var _darken: float = 1.0
var _vision: float = 1.0


func _ready() -> void:
	_settings = _load_settings()
	_clock = get_node_or_null("/root/WorldClock")
	# Autoloads run _ready BEFORE the main scene exists; wait one frame, then bind + start driving.
	await get_tree().process_frame
	_bind_to_scene()
	_connect_clock()
	_refresh_event_hours()
	_build_curves()
	_apply_static_base()
	if _ready_ok:
		_update(_current_hour())
		print("SkyController: day/night driver active (%s)." % SETTINGS_PATH)


func _process(delta: float) -> void:
	if not _ready_ok:
		return
	_accum += delta
	if _accum < UPDATE_INTERVAL:
		return
	_accum = 0.0
	_update(_current_hour())


# ── Settings loader ───────────────────────────────────────────────────────────

func _load_settings() -> Dictionary:
	var file := FileAccess.open(SETTINGS_PATH, FileAccess.READ)
	if file == null:
		push_warning("SkyController: cannot open %s — leaving scene sky/fog as authored." % SETTINGS_PATH)
		return {}
	var json := JSON.new()
	var err := json.parse(file.get_as_text())
	file.close()
	if err != OK:
		push_error("SkyController: JSON parse error in %s — %s" % [SETTINGS_PATH, json.get_error_message()])
		return {}
	return json.data


# ── Scene binding ─────────────────────────────────────────────────────────────

func _bind_to_scene() -> void:
	_ready_ok = false
	_world_env = null
	_env = null
	_sky_mat = null
	_sun = null
	_moon = null
	_camera = null
	_renderer = null
	var scene := get_tree().current_scene
	if scene == null:
		push_warning("SkyController: no current scene — cannot bind sky/fog.")
		return

	_world_env = _find_by_class(scene, "WorldEnvironment") as WorldEnvironment
	_sun = _find_by_class(scene, "DirectionalLight3D") as DirectionalLight3D
	_camera = _find_by_class(scene, "Camera3D") as Camera3D   # fog pins to its far plane
	_renderer = scene.get_node_or_null("Renderer")
	if _renderer == null or not _renderer.has_method("set_terrain_fog"):
		_renderer = _find_by_method(scene, "set_terrain_fog")

	if _world_env != null:
		_env = _world_env.environment
		if _env != null and _env.sky != null and _env.sky.sky_material is ProceduralSkyMaterial:
			_sky_mat = _env.sky.sky_material as ProceduralSkyMaterial

	if _sun != null:
		preload("res://scripts/components/TerrainLighting.gd").configure_sun(_sun)
		_sun_yaw = _sun.rotation_degrees.y
		_moon_yaw = _sun_yaw + 180.0

	# Create a Moon directional light at runtime so nights are not pitch black. It never casts
	# shadows (one shadow-caster — the Sun — keeps the cost down).
	_moon = DirectionalLight3D.new()
	_moon.name = "Moon"
	_moon.shadow_enabled = false
	_moon.light_energy = 0.0
	_moon.visible = false
	scene.add_child(_moon)

	_ready_ok = _env != null
	if _env == null:
		push_warning("SkyController: WorldEnvironment has no Environment resource.")


## SaveManager reloads the gameplay scene while this autoload survives. Rebind
## every scene-owned render reference before the next sky update.
func rebind_to_current_scene() -> void:
	_bind_to_scene()
	_apply_static_base()
	if _ready_ok:
		_update(_current_hour())


func _find_by_class(node: Node, cls: StringName) -> Node:
	if node == null:
		return null
	if node.is_class(cls):
		return node
	for child in node.get_children():
		var found := _find_by_class(child, cls)
		if found != null:
			return found
	return null


func _find_by_method(node: Node, m: StringName) -> Node:
	if node == null:
		return null
	if node.has_method(m):
		return node
	for child in node.get_children():
		var found := _find_by_method(child, m)
		if found != null:
			return found
	return null


# ── Seasonal day length ──────────────────────────────────────────────────────

func _connect_clock() -> void:
	if _clock == null:
		return
	# Recompute rise/set hours when the day or season changes — daylight length is seasonal.
	if not _clock.is_connected("day_changed", _on_calendar_changed):
		_clock.connect("day_changed", _on_calendar_changed)
	if not _clock.is_connected("season_changed", _on_calendar_changed):
		_clock.connect("season_changed", _on_calendar_changed)


func _on_calendar_changed(_value = null) -> void:
	_refresh_event_hours()
	_build_curves()


## Computes today's event-time anchors. midnight and midday (solar noon) stay fixed; the
## sunrise/sunset events move so the lit span equals the seasonal daylight length — ~8 h at the
## winter solstice, ~16 h at the summer solstice (WorldClock.daylight_hours). The keyframed curves
## are anchored to these event names, so they stretch/compress automatically with the season.
func _refresh_event_hours() -> void:
	var base := DEFAULT_EVENT_HOURS.duplicate()
	if _clock != null and _clock.has_method("get_event_times"):
		var e = _clock.call("get_event_times")
		if e is Dictionary and not (e as Dictionary).is_empty():
			base = e
	var midnight: float = float(base.get("midnight", 0))
	var midday: float = float(base.get("midday", 14))

	var daylight := 12.0
	if _clock != null and _clock.has_method("daylight_hours") and _clock.has_method("day_of_year"):
		var doy: int = int(_clock.call("day_of_year"))
		daylight = clampf(float(_clock.call("daylight_hours", doy)), MIN_DAYLIGHT, MAX_DAYLIGHT)
	var half := daylight * 0.5
	var sunrise := midday - half
	var sunset := midday + half

	_event_hours = {
		"midnight":      midnight,
		"sunrise_start": clampf(sunrise - TWILIGHT_HOURS, 0.0, DAY_HOURS),
		"sunrise":       clampf(sunrise, 0.0, DAY_HOURS),
		"sunrise_end":   clampf(sunrise + TWILIGHT_HOURS, 0.0, DAY_HOURS),
		"midday":        midday,
		"sunset_start":  clampf(sunset - TWILIGHT_HOURS, 0.0, DAY_HOURS),
		"sunset":        clampf(sunset, 0.0, DAY_HOURS),
		"sunset_end":    clampf(sunset + TWILIGHT_HOURS, 0.0, DAY_HOURS),
	}


# ── Curve construction ────────────────────────────────────────────────────────

func _build_curves() -> void:
	# _event_hours is precomputed by _refresh_event_hours() (seasonal day length).
	var sky: Dictionary = _settings.get("sky_gradient_colors", {})
	_c_sky_top     = _color_curve(sky.get("top", []))
	_c_sky_horizon = _color_curve(sky.get("horizon", []))
	_c_sky_ground  = _color_curve(sky.get("ground_bottom", []))

	var sun: Dictionary = _settings.get("sun", {})
	_c_sun_color = _color_curve(sun.get("light_color", []))
	_c_sun_pitch = _scalar_curve(sun.get("angle_pitch", []), "deg")

	var moon: Dictionary = _settings.get("moon", {})
	_c_moon_color = _color_curve(moon.get("light_color", []))
	_c_moon_pitch = _scalar_curve(moon.get("angle_pitch", []), "deg")

	var hf = _settings.get("height_fog", [])
	_c_fog_thickness = _scalar_curve(hf, "thickness")
	_c_fog_distance  = _scalar_curve(hf, "distance")
	_build_weather_curves()


# ── Weather ───────────────────────────────────────────────────────────────────

## Called by WeatherManager. Stores the active weather and rebuilds its fog-override curves.
## The look is blended in smoothly by _update (darkening, fog density/distance, vision range).
func apply_weather(weather: Dictionary) -> void:
	_active_weather = weather if weather != null else {}
	_build_weather_curves()


func _build_weather_curves() -> void:
	_c_fog_thickness_w = []
	_c_fog_distance_w = []
	var ov: Dictionary = _active_weather.get("sky_overrides", {})
	var hf = ov.get("height_fog", [])
	if hf is Array and not (hf as Array).is_empty():
		_c_fog_thickness_w = _scalar_curve(hf, "thickness")
		_c_fog_distance_w  = _scalar_curve(hf, "distance")


func _color_curve(arr) -> Array:
	var out: Array = []
	if arr is Array:
		for pt in arr:
			if not (pt is Dictionary):
				continue
			var h := _event_hour(String(pt.get("at", "")))
			if h < 0.0:
				continue
			out.append([h, _to_color(pt.get("rgb", [1, 0, 1]))])
	out.sort_custom(func(a, b): return a[0] < b[0])
	return out


func _scalar_curve(arr, key: String) -> Array:
	var out: Array = []
	if arr is Array:
		for pt in arr:
			if not (pt is Dictionary) or not (pt as Dictionary).has(key):
				continue
			var h := _event_hour(String(pt.get("at", "")))
			if h < 0.0:
				continue
			out.append([h, float(pt[key])])
	out.sort_custom(func(a, b): return a[0] < b[0])
	return out


func _event_hour(event_name: String) -> float:
	return float(_event_hours.get(event_name, -1.0))


# ── Evaluation (keyframe interpolation with 24-hour wraparound) ───────────────

## Returns [i0, i1, t] — the bracketing indices and the 0–1 blend factor for hour h.
func _frac(curve: Array, h: float) -> Array:
	var n := curve.size()
	if n == 0:
		return []
	if n == 1:
		return [0, 0, 0.0]

	var idx := -1
	for i in n:
		if curve[i][0] > h:
			idx = i
			break

	var i0: int
	var i1: int
	var h0: float
	var h1: float
	if idx == -1:
		# h is at/after the last keyframe — wrap to the first (+24h).
		i0 = n - 1; i1 = 0
		h0 = curve[i0][0]; h1 = curve[i1][0] + DAY_HOURS
	elif idx == 0:
		# h is before the first keyframe — wrap from the last (-24h).
		i0 = n - 1; i1 = 0
		h0 = curve[i0][0] - DAY_HOURS; h1 = curve[i1][0]
	else:
		i0 = idx - 1; i1 = idx
		h0 = curve[i0][0]; h1 = curve[i1][0]

	var span := h1 - h0
	var t := 0.0 if span <= 0.0 else clampf((h - h0) / span, 0.0, 1.0)
	return [i0, i1, t]


func _eval_color(curve: Array, h: float) -> Color:
	var b := _frac(curve, h)
	if b.is_empty():
		return Color.MAGENTA
	return (curve[b[0]][1] as Color).lerp(curve[b[1]][1] as Color, b[2])


func _eval_scalar(curve: Array, h: float) -> float:
	var b := _frac(curve, h)
	if b.is_empty():
		return 0.0
	return lerpf(float(curve[b[0]][1]), float(curve[b[1]][1]), b[2])


# ── Per-frame apply ───────────────────────────────────────────────────────────

func _update(h: float) -> void:
	# Weather targets, smoothed toward for soft transitions.
	var darken_target := DARK_FACTOR if bool(_active_weather.get("is_dark_during_daytime", false)) else 1.0
	var vision_target := float(_active_weather.get("vision_multiplier", 1.0))
	_darken = lerpf(_darken, darken_target, WEATHER_BLEND)
	_vision = lerpf(_vision, vision_target, WEATHER_BLEND)

	var horizon := _scale_color(_eval_color(_c_sky_horizon, h), _darken)

	# Sky gradient (dimmed by overcast/fog/snow weather).
	if _sky_mat != null:
		_sky_mat.sky_top_color        = _scale_color(_eval_color(_c_sky_top, h), _darken)
		_sky_mat.sky_horizon_color    = horizon
		_sky_mat.ground_horizon_color = horizon                       # match the sky horizon
		_sky_mat.ground_bottom_color  = _scale_color(_eval_color(_c_sky_ground, h), _darken)

	# Fog: colour tracks the sky horizon (sky/fog match). Density + distance come from the weather
	# height_fog override when present (else base); distance is further scaled by the weather's
	# vision multiplier (fog closes in during foggy/snow). Both are smoothed for a soft transition.
	if MANAGE_FOG and _renderer != null:
		_renderer.call("set_terrain_fog", horizon, _vision, FOG_END_FRACTION, EDGE_FADE_START, FOG_DIAGNOSTIC)

	# Celestial lights.
	_apply_light(_sun,  _eval_color(_c_sun_color, h),  _eval_scalar(_c_sun_pitch, h),  _sun_yaw,  SUN_ENERGY_SCALE)
	_apply_light(_moon, _eval_color(_c_moon_color, h), _eval_scalar(_c_moon_pitch, h), _moon_yaw, MOON_ENERGY_SCALE)


func _apply_light(light: DirectionalLight3D, c: Color, pitch: float, yaw: float, energy_scale: float) -> void:
	if light == null:
		return
	var b := maxf(c.r, maxf(c.g, c.b))
	if b <= LIGHT_OFF_THRESHOLD:
		light.visible = false
		return
	light.visible = true
	light.light_color  = Color(c.r / b, c.g / b, c.b / b)   # normalised hue (brightness -> energy)
	light.light_energy = b * energy_scale
	light.rotation_degrees = Vector3(pitch, yaw, 0.0)


# ── Static (non-time-varying) base from the 'environment' block ───────────────

func _apply_static_base() -> void:
	if _env == null:
		return
	var look: Dictionary = _settings.get("environment", {})
	if look.is_empty():
		return
	_env.ambient_light_source = Environment.AMBIENT_SOURCE_SKY
	if look.has("ambient_color"):
		_env.ambient_light_color = _to_color(look["ambient_color"])
	if look.has("ambient_energy"):
		_env.ambient_light_energy = float(look["ambient_energy"])
	if MANAGE_FOG:
		_env.fog_enabled = false


# ── Helpers ───────────────────────────────────────────────────────────────────

func _current_hour() -> float:
	if _clock != null:
		return float(_clock.get("hour"))
	return 12.0


## The camera far plane (in blocks) the edge fog dissolves at. Read live so it tracks far_clip.
func _far_distance() -> float:
	if _camera != null:
		return _camera.far
	return FAR_FALLBACK


## Multiplies a colour's RGB by a scalar (alpha untouched). Used for weather darkening.
func _scale_color(c: Color, s: float) -> Color:
	return Color(c.r * s, c.g * s, c.b * s, c.a)


## Converts a JSON [r, g, b] or [r, g, b, a] array (0–1 floats) to a Color.
func _to_color(arr) -> Color:
	if arr is Array and (arr as Array).size() >= 3:
		var a: float = 1.0
		if (arr as Array).size() >= 4:
			a = float(arr[3])
		return Color(float(arr[0]), float(arr[1]), float(arr[2]), a)
	return Color.MAGENTA

source_text.scripts/systems/SliceController.gd:
class_name SliceController
extends Node

## The Slice tool (doc 11 Phase 2) — manual control of WorldRenderer.slice_y.
##
## After the Phase SO consolidation the renderer's sliced overview IS the slice
## view at every depth, so this controller has NO mode management: every path
## here simply writes `WorldRenderer.slice_y` and the renderer's setter does the
## localized invalidation. "Off" is slice_y = 127 — one code path (ref doc 10
## rule S1), so toggling off is just a plane move, never a special state.
##
## Responsibilities (ref doc 10 rules in parentheses):
##   - Stepping: cell ±4 and single ±1, snapped to cell tops (S2; Deepdraft cell
##     height = 4, NOT Stonehearth's 5).
##   - Clamps: slice_y in [4, 127]. Y4 keeps one mineable layer visible above
##     bedrock — the Bedrock Protocol stays inviolate. 127 = slice off.
##   - Seeding: first activation seeds from the camera's surface column (S3),
##     once per session; SaveManager persists active/height state (S4).
##   - Hotkeys (H1): slice_toggle (\), slice_cell_up (]), slice_cell_down ([),
##     slice_single_up (Ctrl+]), slice_single_down (Ctrl+[) — registered in
##     project.godot [input] (ownership note: AGENT.md, approved 2026-06-05).
##   - Palette window (H2): cell/single steppers + live Y readout, in the Clock
##     window's visual language.
##   - Mutual exclusion (S7): the future X-Ray tool calls deactivate_if_active();
##     exclusion is enforced at the tool layer, never in the renderer.
##
## Scene wiring: @export paths (Scene Decoupling Contract). DockUI's `slice`
## dock entry routes its toggle here via register on _ready.

# ── Scene references (wire in Inspector) ─────────────────────────────────────

@export var renderer_path: NodePath
@export var camera_path: NodePath
@export var dock_ui_path: NodePath
@export var window_manager_path: NodePath

# ── Constants ─────────────────────────────────────────────────────────────────

## Mining cell height. MUST match data/terrain/mining_config.json →
## dig_tool.y_cell_size (owned/loaded by MiningDesignationController — kept as a
## named constant here rather than a second raw reader of that file).
const CELL_HEIGHT: int = 4

## Floor clamp: Y4 = first mineable layer above the Y0–3 bedrock slab.
const MIN_SLICE_Y: int = 4

## Ceiling clamp = slice off (world top; identical output to the unsliced view).
const MAX_SLICE_Y: int = 127

# ── Signals ───────────────────────────────────────────────────────────────────

## Fired whenever the slice plane moves (active or not). UI readouts connect here.
signal slice_changed(new_slice_y: int)

## Fired when the tool turns on/off. DockUI uses it to refresh button state.
signal slice_active_changed(active: bool)

# ── State ─────────────────────────────────────────────────────────────────────

var _renderer: Node = null
var _camera_rig: Node3D = null
var _dock_ui: Node = null

var _active: bool = false
var _seeded: bool = false          # S3: seed exactly once per session
var _last_slice_y: int = MAX_SLICE_Y   # restored on re-activation

var _window_manager: UIWindowManager = null
var _readout_label: Label

## Manager window id for the palette. Tool state — not a persistent window:
## visibility follows the tool's active flag (which round-trips through the
## save file, doc 20); the layout file remembers only its position (doc 24 §2).
const PALETTE_WINDOW_ID := "slice_palette"


func _ready() -> void:
	add_to_group(SaveManager.OWNER_GROUP)
	_renderer = get_node_or_null(renderer_path)
	_camera_rig = get_node_or_null(camera_path) as Node3D
	_dock_ui = get_node_or_null(dock_ui_path)
	_window_manager = get_node_or_null(window_manager_path) as UIWindowManager
	_build_palette()

	if _renderer == null:
		push_warning("SliceController: renderer_path is not wired — slice tool inert.")
	if _dock_ui != null and _dock_ui.has_method("register_slice_controller"):
		_dock_ui.call("register_slice_controller", self)


func _unhandled_input(event: InputEvent) -> void:
	# exact_match = true so plain ] / [ (cell) never double-fire with Ctrl+] /
	# Ctrl+[ (single), and vice versa.
	if event.is_action_pressed(&"slice_toggle", false, true):
		toggle_active()
		get_viewport().set_input_as_handled()
		return

	if not _active:
		return

	if event.is_action_pressed(&"slice_cell_up", false, true):
		step_cell_up()
		get_viewport().set_input_as_handled()
	elif event.is_action_pressed(&"slice_cell_down", false, true):
		step_cell_down()
		get_viewport().set_input_as_handled()
	elif event.is_action_pressed(&"slice_single_up", false, true):
		step_single_up()
		get_viewport().set_input_as_handled()
	elif event.is_action_pressed(&"slice_single_down", false, true):
		step_single_down()
		get_viewport().set_input_as_handled()


# ── Public API ────────────────────────────────────────────────────────────────

func is_active() -> bool:
	return _active


func get_slice_y() -> int:
	if _renderer == null:
		return MAX_SLICE_Y
	return int(_renderer.get("slice_y"))


func save_section_key() -> String:
	return "slice"


func save_restore_priority() -> int:
	return 80


func serialize_state() -> Dictionary:
	return {
		"active": _active,
		"seeded": _seeded,
		"slice_y": get_slice_y(),
		"last_slice_y": _last_slice_y,
	}


func restore_state(state: Dictionary) -> void:
	_seeded = bool(state.get("seeded", false))
	_last_slice_y = clampi(int(state.get("last_slice_y", MAX_SLICE_Y)), MIN_SLICE_Y, MAX_SLICE_Y)
	_active = bool(state.get("active", false))
	if _active:
		_set_slice_y(int(state.get("slice_y", _last_slice_y)))
		_set_palette_visible(true)
	else:
		_set_slice_y(MAX_SLICE_Y)
		_set_palette_visible(false)
	slice_active_changed.emit(_active)


func toggle_active() -> void:
	if _active:
		deactivate()
	else:
		activate()


## Turns the slice view on. First activation seeds the plane from the camera's
## surface column (S3); later activations restore the last manual height.
func activate() -> void:
	if _active or _renderer == null:
		return
	_active = true

	if not _seeded:
		var seed_y := _seed_from_camera()
		if seed_y >= 0:
			_seeded = true
			_last_slice_y = seed_y
		# Maps not ready yet (seed_y < 0): keep _seeded false so the next
		# activation retries; fall through with the previous value (127 = no
		# visible cut, harmless).

	_set_slice_y(_last_slice_y)
	_set_palette_visible(true)
	slice_active_changed.emit(true)


## Turns the slice view off: the plane returns to the world top (S1 — "off" is
## just a plane move; visibility-level cost, no special rebuild path).
func deactivate() -> void:
	if not _active:
		return
	_active = false
	_last_slice_y = get_slice_y()
	_set_slice_y(MAX_SLICE_Y)
	_set_palette_visible(false)
	slice_active_changed.emit(false)


## Mutual exclusion hook (S7): the future X-Ray tool calls this before
## activating itself. Exclusion lives at the tool layer, not the renderer.
func deactivate_if_active() -> void:
	deactivate()


# ── Stepping (S2 — cell = 4; cell tops are n*4 - 1: Y7, Y11, … Y127) ──────────

func step_cell_up() -> void:
	var y := get_slice_y()
	_set_slice_y(y - ((y + 1) % CELL_HEIGHT) + CELL_HEIGHT)


func step_cell_down() -> void:
	var y := get_slice_y()
	var delta := (y + 1) % CELL_HEIGHT
	if delta == 0:
		delta = CELL_HEIGHT
	_set_slice_y(y - delta)


func step_single_up() -> void:
	_set_slice_y(get_slice_y() + 1)


func step_single_down() -> void:
	_set_slice_y(get_slice_y() - 1)


# ── Internals ─────────────────────────────────────────────────────────────────

func _set_slice_y(value: int) -> void:
	if _renderer == null:
		return
	var clamped := clampi(value, MIN_SLICE_Y, MAX_SLICE_Y)
	if clamped != get_slice_y():
		_renderer.set("slice_y", clamped)   # setter runs the localized invalidation
	_update_readout()
	slice_changed.emit(clamped)


## S3 seeding: cell top of the camera's surface column — the same math as
## Stonehearth's embark seed (quantize to the cell, minus the ceiling):
##   cell_top(y) = floor(y / 4) * 4 + 3
## Returns -1 while the generator maps are not ready.
func _seed_from_camera() -> int:
	if _camera_rig == null or not WorldGenerator.has_method("get_visible_surface_y"):
		return -1
	var wx := clampi(floori(_camera_rig.global_position.x), 0, WorldGenerator.WORLD_SIZE_X - 1)
	var wz := clampi(floori(_camera_rig.global_position.z), 0, WorldGenerator.WORLD_SIZE_Z - 1)
	var surface_y := int(WorldGenerator.get_visible_surface_y(wx, wz))
	if surface_y < 0:
		return -1
	@warning_ignore("integer_division")
	var cell_top := (surface_y / CELL_HEIGHT) * CELL_HEIGHT + CELL_HEIGHT - 1
	return clampi(cell_top, MIN_SLICE_Y, MAX_SLICE_Y)


# ── Palette window (H2; doc 24: content only — chrome in UIWindowManager) ─────

func _build_palette() -> void:
	if _window_manager == null:
		push_warning("SliceController: UIWindowManager not found at '%s' — palette disabled." % window_manager_path)
		return

	var column := VBoxContainer.new()
	column.add_theme_constant_override("separation", 8)

	column.add_child(_make_step_button("▲▲  Cell up", "Raise the slice one 4-block cell  ( ] )", step_cell_up))
	column.add_child(_make_step_button("▲  Block up", "Raise the slice one block  (Ctrl+])", step_single_up))

	_readout_label = Label.new()
	_readout_label.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	_readout_label.add_theme_font_size_override("font_size", 17)
	column.add_child(_readout_label)

	column.add_child(_make_step_button("▼  Block down", "Lower the slice one block  (Ctrl+[)", step_single_down))
	column.add_child(_make_step_button("▼▼  Cell down", "Lower the slice one 4-block cell  ( [ )", step_cell_down))

	_window_manager.register_window(PALETTE_WINDOW_ID, "Slice", "👀", column,
		{"default_pos": Vector2(18.0, 130.0)})
	# Closing the palette with its X IS turning the slice tool off — the
	# window has no meaning without the tool.
	_window_manager.window_state_changed.connect(_on_window_state_changed)
	_update_readout()


func _on_window_state_changed(id: String, open: bool) -> void:
	if id == PALETTE_WINDOW_ID and not open and _active:
		deactivate()


func _set_palette_visible(shown: bool) -> void:
	if _window_manager == null:
		return
	if shown:
		_window_manager.open(PALETTE_WINDOW_ID)
	else:
		_window_manager.close(PALETTE_WINDOW_ID)


func _make_step_button(text: String, tooltip: String, on_press: Callable) -> Button:
	var button := UITheme.make_button(text, tooltip, Vector2(126.0, 30.0))
	button.pressed.connect(on_press)
	return button


func _update_readout() -> void:
	if _readout_label == null:
		return
	var y := get_slice_y()
	_readout_label.text = "Y = %d" % y if y < MAX_SLICE_Y else "Off"

source_text.scripts/systems/StockpileDesignationCont:
class_name StockpileDesignationController
extends Node3D

## Stockpile zone designation tool (doc 18 Phase 1). The player toggles the
## tool (dock 'storage_zone' panel → Draw Zone), hovers a validity-tinted
## ghost tile, and click-drags a flat rectangle on walkable floor. Confirmed
## zones render a per-zone ground overlay (never merged — the doc 43
## adjacency lesson) and persist until removed via the zone window.
##
## Tool input contract (doc 21): ESC exits the mode; right-mouse stays camera
## orbit and is never consumed. The tool stays active after each confirm for
## repeated painting (the mining-tool pattern). Clicking an EXISTING zone cell
## (no drag) while the tool is active opens its compact zone window.
##
## Drag rules (doc 18 Phase 1):
##   - The anchor cell fixes the zone's floor Y — the marquee is FLAT; hover
##     cells clamp to the anchor plane (the mining drag-height-lock lesson).
##   - Per-cell validity: walkable floor (NavGrid — solid + 3-air clearance +
##     no entity), exactly at anchor Y, dry, in bounds. Invalid cells drop out
##     of the preview; confirm designates exactly the valid subset (WYSIWYG).
##   - No grid snapping; max extent per drag is MAX_ZONE_EXTENT.
##
## Raycasting: a slice-aware voxel DDA against the live block grid (doc 22b,
## 2026-08-06 — previously a STATIC height-field march, the flag-tool
## approach, which meant zones could only ever be drawn on the untouched
## world-gen surface, never inside a mined interior). See
## _surface_cell_for()'s header for the full story.
##
## Slice rule (doc 11 Phase 5): zone overlays hide when their floor is above
## the cut, same hook as flora/dwarves/drops.

@export var camera_path: NodePath
@export var dock_ui_path: NodePath
@export var slice_controller_path: NodePath

const TOOL_ID := "storage_zone"
const MAX_ZONE_EXTENT := 16          # max cells per axis in one drag
const WORLD_EDGE_MARGIN := 2
const RAY_MAX := 700.0
const SLICE_OFF_Y := 127
const OVERLAY_LIFT := 1.04           # overlay quad height above the floor top
const DRAG_THRESHOLD_PX := 6.0       # below this, a click = zone select (doc 22)

const COLOR_VALID := Color(0.25, 0.65, 0.90, 0.30)     # fill, blue-cyan (mining zones own yellow)
const COLOR_VALID_EDGE := Color(0.35, 0.80, 1.00, 0.85)
const COLOR_INVALID := Color(1.00, 0.30, 0.25, 0.35)
const COLOR_ZONE := Color(0.25, 0.65, 0.90, 0.22)      # confirmed zone fill
const COLOR_ZONE_EDGE := Color(0.35, 0.80, 1.00, 0.60)
const EDGE_INSET := 0.08             # perimeter strip width (blocks)

## DEV drop mix (doc 18 Phase 0): item_key -> count, total 20. Keys must match
## resources.json; all have real GLBs so no fallback cubes appear.
const DEV_DROP_MIX: Dictionary = {
	"base:resources:stone:rough_stone": 6,
	"base:resources:ore:copper": 3,
	"base:resources:ore:tin": 3,
	"base:resources:ore:iron": 3,
	"base:resources:ore:coal": 2,
	"base:resources:soil:light_soil": 2,
	"base:resources:soil:cave_soil": 1,
}

## DEV: one packed furniture item of each kind (doc 19 Phase 0 - the v1 item
## source until crafting/trade produce furniture for real; doc 21 adds the
## tavern set; doc 22 adds the door; art docs 37–40 add counter/table/chair/bed;
## art doc 42 adds the brewing vat).
const DEV_FURNITURE_MIX: Dictionary = {
	"base:resources:furniture:barrel": 1,
	"base:resources:furniture:storage_chest": 1,
	"base:resources:furniture:storage_shelf": 1,
	"base:resources:furniture:tavern_bar": 1,
	"base:resources:furniture:bench": 1,
	"base:resources:furniture:hearth": 1,
	"base:resources:furniture:door": 1,
	"base:resources:furniture:trade_counter": 1,
	"base:resources:furniture:wooden_table": 1,
	"base:resources:furniture:wooden_chair": 1,
	"base:resources:furniture:dwarf_bunk": 1,
	"base:resources:furniture:brewing_vat": 1,
	"base:resources:furniture:wall_torch": 4,
}

signal zone_created(zone_id: int)
signal zone_removed(zone_id: int)

## Fired on every activate/deactivate — DockUI refreshes button pressed-state
## from it (the SliceController slice_active_changed pattern), so Esc-cancel
## no longer leaves the 📦 button lit until the next dock interaction.
signal tool_active_changed(active: bool)

var _dock_ui: Node = null

var _active: bool = false
var _dragging: bool = false
var _anchor_cell: Vector3i = Vector3i(-1, -1, -1)
var _drag_start_px: Vector2 = Vector2.ZERO
var _hover_cell: Vector3i = Vector3i(-1, -1, -1)
var _hover_valid: bool = false
var _preview_cells: Array[Vector3i] = []

var _slice_y: int = SLICE_OFF_Y
var _next_zone_id: int = 1
var _zones: Dictionary = {}          # zone_id -> StockpileZoneComponent
var _zone_overlays: Dictionary = {}  # zone_id -> MeshInstance3D
var _cell_to_zone: Dictionary = {}   # Vector3i -> zone_id (click lookup)

var _preview_mesh: MeshInstance3D = null
var _size_label: Label3D = null
var _overlay_material: StandardMaterial3D = null

var _window_layer: CanvasLayer = null
var _window_panel: PanelContainer = null
var _window_zone_id: int = -1
var _window_info_label: Label = null


func _ready() -> void:
	add_to_group("stockpile_controller")
	add_to_group(SaveManager.OWNER_GROUP)
	_dock_ui = get_node_or_null(dock_ui_path)
	if _dock_ui != null:
		if _dock_ui.has_method("register_stockpile_controller"):
			_dock_ui.call("register_stockpile_controller", self)
		if _dock_ui.has_signal("tool_requested"):
			_dock_ui.connect("tool_requested", _on_tool_requested)
	var slice_controller := get_node_or_null(slice_controller_path)
	if slice_controller != null and slice_controller.has_signal("slice_changed"):
		slice_controller.connect("slice_changed", _on_slice_changed)
	_overlay_material = StandardMaterial3D.new()
	_overlay_material.vertex_color_use_as_albedo = true
	_overlay_material.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	_overlay_material.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	_overlay_material.cull_mode = BaseMaterial3D.CULL_DISABLED
	_build_window()


func _process(_delta: float) -> void:
	if not _active:
		return
	_update_hover()


func _unhandled_input(event: InputEvent) -> void:
	if not _active:
		# Mining parity (defect, Alen 2026-07-11: a stocked zone was unremovable
		# with the tool off): zones stay click-selectable while the tool is
		# INACTIVE, exactly like MiningDesignationController's inactive branch —
		# the zone window (and its Remove button) must always be reachable.
		if event is InputEventMouseButton:
			var mb_inactive := event as InputEventMouseButton
			if mb_inactive.pressed and mb_inactive.button_index == MOUSE_BUTTON_LEFT \
					and _try_select_zone_at_screen(mb_inactive.position):
				get_viewport().set_input_as_handled()
		return
	if event is InputEventKey and (event as InputEventKey).pressed \
			and (event as InputEventKey).keycode == KEY_ESCAPE:
		deactivate()
		get_viewport().set_input_as_handled()
		return
	if event is InputEventMouseButton:
		var mb := event as InputEventMouseButton
		if mb.button_index != MOUSE_BUTTON_LEFT:
			return
		if mb.pressed:
			_on_left_press(mb.position)
			get_viewport().set_input_as_handled()
		elif _dragging:
			_on_left_release(mb.position)
			get_viewport().set_input_as_handled()


# ── Tool state ────────────────────────────────────────────────────────────────

func is_active() -> bool:
	return _active


func toggle_active() -> void:
	if _active:
		deactivate()
	else:
		activate()


func activate() -> void:
	if _active:
		return
	if not bool(WorldGenerator.get_streaming_stats().get("maps_ready", false)):
		push_warning("StockpileDesignationController: maps not ready.")
		return
	_active = true
	_ensure_preview_mesh()
	tool_active_changed.emit(true)


func deactivate() -> void:
	if not _active:
		return
	_active = false
	_dragging = false
	_preview_cells.clear()
	if _preview_mesh != null:
		_preview_mesh.visible = false
	if _size_label != null:
		_size_label.visible = false
	tool_active_changed.emit(false)


func _on_tool_requested(tool_id: String) -> void:
	# One active tool at a time: our id toggles us; any other id closes us.
	if tool_id == TOOL_ID:
		toggle_active()
	elif _active:
		deactivate()


# ── Input flow ────────────────────────────────────────────────────────────────

func _on_left_press(screen_pos: Vector2) -> void:
	if not _hover_valid:
		# Clicking an existing zone opens its window even on invalid hover
		# (a stocked zone cell is not a valid NEW cell, but is selectable).
		if _cell_to_zone.has(_hover_cell):
			_open_zone_window(int(_cell_to_zone[_hover_cell]))
		return
	if _cell_to_zone.has(_hover_cell):
		_open_zone_window(int(_cell_to_zone[_hover_cell]))
		return
	_dragging = true
	_anchor_cell = _hover_cell
	_drag_start_px = screen_pos
	_rebuild_preview()


func _on_left_release(screen_pos: Vector2) -> void:
	_dragging = false
	if _size_label != null:
		_size_label.visible = false
	# Short click on empty valid ground = 1×1 zone (DRAG_THRESHOLD, doc 22).
	# NOTE: built explicitly, never via ternary — `[x] if c else []` yields a
	# plain Array and crashes assigning to Array[Vector3i] (runtime-only error;
	# the 2026-07-06 flag-click crash).
	if screen_pos.distance_to(_drag_start_px) < DRAG_THRESHOLD_PX:
		var single: Array[Vector3i] = []
		if _is_valid_cell(_anchor_cell, _anchor_cell.y):
			single.append(_anchor_cell)
		_preview_cells = single
	if not _preview_cells.is_empty():
		_confirm_zone(_preview_cells.duplicate())
	_preview_cells.clear()
	if _preview_mesh != null:
		_preview_mesh.visible = false


func _update_hover() -> void:
	var hit := _mouse_surface_cell()
	if hit.is_empty():
		_hover_cell = Vector3i(-1, -1, -1)
		_hover_valid = false
		if not _dragging and _preview_mesh != null:
			_preview_mesh.visible = false
		return
	var cell := Vector3i(int(hit["x"]), int(hit["y"]), int(hit["z"]))
	if _dragging:
		# Drag height lock: the marquee lives on the anchor plane.
		cell.y = _anchor_cell.y
	if cell == _hover_cell and _preview_mesh != null and _preview_mesh.visible:
		return
	_hover_cell = cell
	_hover_valid = _is_valid_cell(cell, cell.y) and not _cell_to_zone.has(cell)
	_rebuild_preview()


# ── Preview ───────────────────────────────────────────────────────────────────

func _rebuild_preview() -> void:
	_ensure_preview_mesh()
	if _dragging:
		_preview_cells = _marquee_valid_cells(_anchor_cell, _hover_cell)
		_draw_cells(_preview_mesh, _preview_cells, COLOR_VALID, COLOR_VALID_EDGE, _anchor_cell.y)
		_update_size_label()
	else:
		var color_fill := COLOR_VALID if _hover_valid else COLOR_INVALID
		var color_edge := COLOR_VALID_EDGE if _hover_valid else COLOR_INVALID
		var cells: Array[Vector3i] = [_hover_cell]
		_draw_cells(_preview_mesh, cells, color_fill, color_edge, _hover_cell.y)
	_preview_mesh.visible = _hover_cell.x >= 0


## The extent-clamped marquee rectangle as (min_x, min_z, max_x, max_z).
func _marquee_rect(anchor: Vector3i, current: Vector3i) -> Vector4i:
	var min_x := mini(anchor.x, current.x)
	var max_x := maxi(anchor.x, current.x)
	var min_z := mini(anchor.z, current.z)
	var max_z := maxi(anchor.z, current.z)
	# Clamp extent, growing away from the anchor.
	max_x = mini(max_x, min_x + MAX_ZONE_EXTENT - 1) if anchor.x == min_x else max_x
	min_x = maxi(min_x, max_x - MAX_ZONE_EXTENT + 1) if anchor.x == max_x else min_x
	max_z = mini(max_z, min_z + MAX_ZONE_EXTENT - 1) if anchor.z == min_z else max_z
	min_z = maxi(min_z, max_z - MAX_ZONE_EXTENT + 1) if anchor.z == max_z else min_z
	return Vector4i(min_x, min_z, max_x, max_z)


## The flat rectangle between anchor and current, valid cells only (WYSIWYG).
func _marquee_valid_cells(anchor: Vector3i, current: Vector3i) -> Array[Vector3i]:
	var rect := _marquee_rect(anchor, current)
	var cells: Array[Vector3i] = []
	for x: int in range(rect.x, rect.z + 1):
		for z: int in range(rect.y, rect.w + 1):
			var cell := Vector3i(x, anchor.y, z)
			if _cell_to_zone.has(cell):
				continue   # zones never merge or overlap (doc 43 lesson)
			if _is_valid_cell(cell, anchor.y):
				cells.append(cell)
	return cells


## Live drag readout — "W × D — N cells" floating above the marquee centre
## (Alen playtest note 2026-07-06: never make the player count voxels).
func _update_size_label() -> void:
	if _size_label == null:
		_size_label = Label3D.new()
		_size_label.name = "SizeLabel"
		_size_label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
		_size_label.fixed_size = true
		_size_label.pixel_size = 0.0008
		_size_label.font_size = 96
		_size_label.outline_size = 24
		_size_label.modulate = Color(0.85, 0.95, 1.0)
		_size_label.outline_modulate = Color(0.0, 0.0, 0.0, 0.85)
		_size_label.no_depth_test = true
		add_child(_size_label)
	var rect := _marquee_rect(_anchor_cell, _hover_cell)
	var w := rect.z - rect.x + 1
	var d := rect.w - rect.y + 1
	var valid := _preview_cells.size()
	if valid == w * d:
		_size_label.text = "%d × %d — %d cells" % [w, d, valid]
	else:
		_size_label.text = "%d × %d — %d of %d valid" % [w, d, valid, w * d]
	_size_label.position = Vector3(
		(float(rect.x) + float(rect.z) + 1.0) * 0.5,
		float(_anchor_cell.y) + 2.4,
		(float(rect.y) + float(rect.w) + 1.0) * 0.5)
	_size_label.visible = true


# ── Validity ──────────────────────────────────────────────────────────────────

## A designatable stockpile cell: in bounds (with margin), above bedrock, dry,
## the visible surface at exactly the marquee plane, and NavGrid-walkable
## (solid floor + 3-air clearance + no entity footprint).
func _is_valid_cell(cell: Vector3i, plane_y: int) -> bool:
	if cell.x < WORLD_EDGE_MARGIN or cell.x >= WorldGenerator.WORLD_SIZE_X - WORLD_EDGE_MARGIN \
			or cell.z < WORLD_EDGE_MARGIN or cell.z >= WorldGenerator.WORLD_SIZE_Z - WORLD_EDGE_MARGIN:
		return false
	if cell.y <= 3 or cell.y != plane_y:
		return false
	var col := Vector2i(cell.x, cell.z)
	if WorldGenerator.lake_columns.has(col) or WorldGenerator.tarn_columns.has(col):
		return false
	# Zones never overlap furniture ghosts or installed pieces (doc 19 Phase 2;
	# installed occupancy already fails is_walkable, ghosts are non-solid so
	# they need the explicit check).
	var furniture := get_tree().get_first_node_in_group("furniture_controller")
	if furniture != null and furniture.has_method("blocks_zone_cell") \
			and bool(furniture.call("blocks_zone_cell", cell)):
		return false
	return NavGrid.is_walkable(cell)


# ── Zone lifecycle ────────────────────────────────────────────────────────────

func _confirm_zone(cells: Array[Vector3i]) -> void:
	_create_zone(cells)


func _create_zone(cells: Array[Vector3i], requested_id: int = -1) -> StockpileZoneComponent:
	var zone_id := requested_id if requested_id > 0 else _next_zone_id
	var zone := StockpileZoneComponent.new()
	zone.setup(zone_id, cells)
	_zones[zone_id] = zone
	for cell: Vector3i in cells:
		_cell_to_zone[cell] = zone_id
	var overlay := MeshInstance3D.new()
	overlay.name = "StockpileZone_%d" % zone_id
	add_child(overlay)
	_draw_cells(overlay, cells, COLOR_ZONE, COLOR_ZONE_EDGE, zone.floor_y)
	overlay.visible = zone.floor_y <= _slice_y
	_zone_overlays[zone_id] = overlay
	StockpileManager.register_zone(zone)   # work source goes live (doc 18 Phase 3)
	print("StockpileDesignationController: zone %d created (%d cells at Y %d)." % [
		zone_id, cells.size(), zone.floor_y])
	zone_created.emit(zone_id)
	_next_zone_id = maxi(_next_zone_id, zone_id + 1)
	return zone


func remove_zone(zone_id: int) -> void:
	if not _zones.has(zone_id):
		return
	var zone: StockpileZoneComponent = _zones[zone_id]
	StockpileManager.deregister_zone(zone)   # cancels leases, frees stored items
	for cell: Vector3i in zone.tile_cells:
		_cell_to_zone.erase(cell)
	_zones.erase(zone_id)
	if _zone_overlays.has(zone_id):
		(_zone_overlays[zone_id] as MeshInstance3D).queue_free()
		_zone_overlays.erase(zone_id)
	if _window_zone_id == zone_id:
		_close_zone_window()
	zone_removed.emit(zone_id)


## Cross-system lookup (doc 19 Phase 2): the furniture tool must not place
## on zone cells. Mirrored by our own _is_valid_cell rejecting furniture.
func is_zone_cell(cell: Vector3i) -> bool:
	return _cell_to_zone.has(cell)


func get_zone(zone_id: int) -> StockpileZoneComponent:
	return _zones.get(zone_id)


func get_stats() -> Dictionary:
	var cells: int = 0
	var stored: int = 0
	for zone_id: int in _zones:
		var zone: StockpileZoneComponent = _zones[zone_id]
		cells += zone.cell_count()
		stored += zone.stored_count()
	return { "zones": _zones.size(), "cells": cells, "stored": stored }


func save_section_key() -> String:
	return "stockpiles"


func save_restore_priority() -> int:
	return 30


func serialize_state() -> Dictionary:
	var saved_zones: Array = []
	var ids: Array = _zones.keys()
	ids.sort()
	for value in ids:
		var zone_id := int(value)
		var zone: StockpileZoneComponent = _zones[zone_id]
		var cells: Array = []
		for cell: Vector3i in zone.tile_cells:
			cells.append(SaveManager.pack_v3i(cell))
		var stacks: Array = []
		for cell: Vector3i in zone.cell_stacks:
			var stack: Dictionary = zone.cell_stacks[cell]
			stacks.append({
				"cell": SaveManager.pack_v3i(cell),
				"item": String(stack.get("item", "")),
				"count": int(stack.get("count", 0)),
			})
		saved_zones.append({
			"id": zone_id,
			"cells": cells,
			"filter_tags": zone.filter_tags.duplicate(),
			"stacks": stacks,
		})
	return { "zones": saved_zones }


func restore_state(state: Dictionary) -> void:
	var drop_manager := get_tree().get_first_node_in_group("item_drop_manager")
	for raw in state.get("zones", []):
		if not (raw is Dictionary):
			continue
		var entry := raw as Dictionary
		var cells: Array[Vector3i] = []
		for packed in entry.get("cells", []):
			cells.append(SaveManager.unpack_v3i(packed))
		if cells.is_empty():
			continue
		var zone := _create_zone(cells, int(entry.get("id", -1)))
		zone.filter_tags.assign(entry.get("filter_tags", StockpileZoneComponent.DEFAULT_FILTER_TAGS))
		for stack_raw in entry.get("stacks", []):
			if not (stack_raw is Dictionary):
				continue
			var saved_stack := stack_raw as Dictionary
			var cell := SaveManager.unpack_v3i(saved_stack.get("cell", []))
			var item_key := String(saved_stack.get("item", ""))
			var count := maxi(int(saved_stack.get("count", 0)), 0)
			if count <= 0 or item_key.is_empty() or not zone.has_cell(cell):
				continue
			zone.cell_stacks[cell] = { "item": item_key, "count": count }
			if drop_manager != null and drop_manager.has_method("restore_stored_item"):
				drop_manager.call("restore_stored_item", item_key, cell)


# ── DEV: drop spawner (doc 18 Phase 0) ────────────────────────────────────────

## DEV: drops one packed furniture item of each kind at the view centre
## (doc 19 Phase 0). Wired to the dock's Storage Zone panel.
func dev_spawn_furniture() -> void:
	_dev_spawn_mix(DEV_FURNITURE_MIX)


## Spawns the DEV_DROP_MIX (20 mixed drops) around the ground point at the
## screen centre. Wired to the dock's Storage Zone panel.
func dev_spawn_drops() -> void:
	_dev_spawn_mix(DEV_DROP_MIX)


func _dev_spawn_mix(mix: Dictionary) -> void:
	var center := _screen_center_surface_cell()
	if center.x < 0:
		push_warning("StockpileDesignationController: no ground at view centre for DEV drops.")
		return
	var manager := get_tree().get_first_node_in_group("item_drop_manager")
	if manager == null or not manager.has_method("spawn_drop"):
		push_warning("StockpileDesignationController: ItemDropManager not found.")
		return
	for item_key: String in mix:
		var count := int(mix[item_key])
		for i: int in range(count):
			var jitter := Vector3i(randi_range(-3, 3), 0, randi_range(-3, 3))
			var cell := center + jitter
			# spawn_drop expects the MINED block position; its rest scan walks
			# down to the floor, so hand it the air block above the surface.
			manager.call("spawn_drop", item_key, 1, Vector3i(cell.x, center.y + 1, cell.z))


# ── Rendering helpers ─────────────────────────────────────────────────────────

func _ensure_preview_mesh() -> void:
	if _preview_mesh != null:
		return
	_preview_mesh = MeshInstance3D.new()
	_preview_mesh.name = "StockpilePreview"
	add_child(_preview_mesh)


## Builds flat quads (fill + perimeter strips) for `cells` into `target`.
func _draw_cells(target: MeshInstance3D, cells: Array[Vector3i], fill: Color, edge: Color, plane_y: int) -> void:
	var mesh := ImmediateMesh.new()
	if not cells.is_empty():
		var y := float(plane_y) + OVERLAY_LIFT
		var cell_set: Dictionary = {}
		for cell: Vector3i in cells:
			cell_set[cell] = true
		mesh.surface_begin(Mesh.PRIMITIVE_TRIANGLES)
		for cell: Vector3i in cells:
			_emit_quad(mesh, float(cell.x), float(cell.z), 1.0, 1.0, y, fill)
			# Perimeter strips where a neighbour is outside the set.
			var fx := float(cell.x)
			var fz := float(cell.z)
			if not cell_set.has(cell + Vector3i(-1, 0, 0)):
				_emit_quad(mesh, fx, fz, EDGE_INSET, 1.0, y + 0.005, edge)
			if not cell_set.has(cell + Vector3i(1, 0, 0)):
				_emit_quad(mesh, fx + 1.0 - EDGE_INSET, fz, EDGE_INSET, 1.0, y + 0.005, edge)
			if not cell_set.has(cell + Vector3i(0, 0, -1)):
				_emit_quad(mesh, fx, fz, 1.0, EDGE_INSET, y + 0.005, edge)
			if not cell_set.has(cell + Vector3i(0, 0, 1)):
				_emit_quad(mesh, fx, fz + 1.0 - EDGE_INSET, 1.0, EDGE_INSET, y + 0.005, edge)
		mesh.surface_end()
	target.mesh = mesh
	target.material_override = _overlay_material


func _emit_quad(mesh: ImmediateMesh, x: float, z: float, w: float, d: float, y: float, color: Color) -> void:
	mesh.surface_set_color(color)
	mesh.surface_add_vertex(Vector3(x, y, z))
	mesh.surface_add_vertex(Vector3(x + w, y, z))
	mesh.surface_add_vertex(Vector3(x + w, y, z + d))
	mesh.surface_set_color(color)
	mesh.surface_add_vertex(Vector3(x, y, z))
	mesh.surface_add_vertex(Vector3(x + w, y, z + d))
	mesh.surface_add_vertex(Vector3(x, y, z + d))


# ── Raycasting (the flag-tool height-field march) ─────────────────────────────

func _mouse_surface_cell() -> Dictionary:
	return _surface_cell_for(get_viewport().get_mouse_position())


func _screen_center_surface_cell() -> Vector3i:
	var hit := _surface_cell_for(get_viewport().get_visible_rect().size * 0.5)
	if hit.is_empty():
		return Vector3i(-1, -1, -1)
	return Vector3i(int(hit["x"]), int(hit["y"]), int(hit["z"]))


## Voxel DDA raycast from the camera through the mouse, returning the cell
## (the floor cell itself -- NavGrid's convention; see the off-by-one note
## below).
##
## 2026-08-06 bugfix (doc 22b follow-on): this used to march the ray against
## WorldGenerator.get_visible_surface_y() — the STATIC world-gen heightmap,
## set once at generation and never updated by mining. Zones were
## deliberately documented as "surface designations" for that reason, but
## that meant a stockpile zone could never be drawn inside a mined-out
## interior room — a hard blocker for the doc 22 door/sealed-room work this
## zones can never reach the storage rooms doors are built to protect.
## Ported from FurniturePlacementController._surface_cell_for()'s fix (same
## day): a real voxel DDA against the live block grid (_block_id — WorldData
## first, WorldGenerator fallback), gated by _slice_y exactly like
## MiningDesignationController._raycast_voxel(). Above-ground zone drawing is
## unaffected — the first solid cell hit for an untouched column is still
## the natural terrain surface.
##
## OFF-BY-ONE FOLLOW-UP FIX (2026-08-06, same day): this first shipped
## returning `pos.y + 1` ("one above the hit block"), on the wrong
## assumption that cell.y meant the walkable AIR cell. It doesn't --
## NavGrid._compute_walkable(cell) requires cell.y ITSELF to be solid, with
## clearance checked at cell.y+1..+CLEARANCE. WorldGenerator.get_visible_
## surface_y() (the old raycast's source) returns that same solid-floor
## convention -- confirmed via get_visible_surface_block_id(), which
## generates the SURFACE block at exactly that Y. Returning pos.y + 1 meant
## every returned cell was air, so is_walkable() rejected literally
## everything and placement broke outright -- reported as "lost the ability
## to draw storage zones". Fixed to return pos.y (the solid block itself).
func _surface_cell_for(screen_pos: Vector2) -> Dictionary:
	var camera := get_viewport().get_camera_3d()
	if camera == null:
		return {}
	var origin := camera.project_ray_origin(screen_pos)
	var direction := camera.project_ray_normal(screen_pos).normalized()

	var pos := Vector3i(floori(origin.x), floori(origin.y), floori(origin.z))
	var step := Vector3i(
		1 if direction.x > 0.0 else -1,
		1 if direction.y > 0.0 else -1,
		1 if direction.z > 0.0 else -1)
	var t_delta := Vector3(
		abs(1.0 / direction.x) if not is_zero_approx(direction.x) else INF,
		abs(1.0 / direction.y) if not is_zero_approx(direction.y) else INF,
		abs(1.0 / direction.z) if not is_zero_approx(direction.z) else INF)
	var t_max := Vector3(
		_axis_t_max(origin.x, direction.x, pos.x),
		_axis_t_max(origin.y, direction.y, pos.y),
		_axis_t_max(origin.z, direction.z, pos.z))
	var travelled := 0.0

	while travelled <= RAY_MAX:
		if pos.x >= 0 and pos.x < WorldGenerator.WORLD_SIZE_X \
				and pos.z >= 0 and pos.z < WorldGenerator.WORLD_SIZE_Z:
			if pos.y >= 0 and pos.y <= _slice_y:
				var block_id := _block_id(pos.x, pos.y, pos.z)
				if BlockRegistry.is_solid(block_id):
					return { "x": pos.x, "y": pos.y, "z": pos.z }
		elif pos.y < 0:
			return {}

		if t_max.x <= t_max.y and t_max.x <= t_max.z:
			pos.x += step.x
			travelled = t_max.x
			t_max.x += t_delta.x
		elif t_max.y <= t_max.z:
			pos.y += step.y
			travelled = t_max.y
			t_max.y += t_delta.y
		else:
			pos.z += step.z
			travelled = t_max.z
			t_max.z += t_delta.z

	return {}


func _axis_t_max(origin_axis: float, direction_axis: float, pos_axis: int) -> float:
	if is_zero_approx(direction_axis):
		return INF
	var boundary := float(pos_axis + 1) if direction_axis > 0.0 else float(pos_axis)
	return (boundary - origin_axis) / direction_axis


func _block_id(wx: int, wy: int, wz: int) -> int:
	if WorldData.chunk_exists(wx >> 4, wy >> 4, wz >> 4):
		return WorldData.get_block(wx, wy, wz)
	return WorldGenerator.get_generated_block_id(wx, wy, wz)


# ── Slice culling (doc 11 Phase 5 hook) ───────────────────────────────────────

func _on_slice_changed(new_slice_y: int) -> void:
	if new_slice_y == _slice_y:
		return
	_slice_y = new_slice_y
	for zone_id: int in _zone_overlays:
		var zone: StockpileZoneComponent = _zones.get(zone_id)
		if zone != null:
			(_zone_overlays[zone_id] as MeshInstance3D).visible = zone.floor_y <= _slice_y


# ── Zone window (compact — Remove / stored count) ─────────────────────────────

func _build_window() -> void:
	_window_layer = CanvasLayer.new()
	_window_layer.name = "StockpileZoneWindow"
	_window_layer.layer = 22
	_window_layer.visible = false
	add_child(_window_layer)

	_window_panel = PanelContainer.new()
	_window_panel.position = Vector2(18.0, 300.0)
	_window_panel.custom_minimum_size = Vector2(200.0, 0.0)
	_window_panel.add_theme_stylebox_override("panel", _style(Color(0.065, 0.070, 0.075, 0.94), Color(1, 1, 1, 0.12), 1, 8))
	_window_layer.add_child(_window_panel)

	var margin := MarginContainer.new()
	margin.add_theme_constant_override("margin_left", 12)
	margin.add_theme_constant_override("margin_right", 12)
	margin.add_theme_constant_override("margin_top", 10)
	margin.add_theme_constant_override("margin_bottom", 10)
	_window_panel.add_child(margin)

	var column := VBoxContainer.new()
	column.add_theme_constant_override("separation", 8)
	margin.add_child(column)

	var header := HBoxContainer.new()
	header.add_theme_constant_override("separation", 8)
	column.add_child(header)

	var title := Label.new()
	title.text = "Storage Zone"
	title.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	title.add_theme_font_size_override("font_size", 16)
	header.add_child(title)

	var close := Button.new()
	close.text = "X"
	close.custom_minimum_size = Vector2(30.0, 26.0)
	close.focus_mode = Control.FOCUS_NONE
	close.pressed.connect(_close_zone_window)
	header.add_child(close)

	_window_info_label = Label.new()
	_window_info_label.add_theme_font_size_override("font_size", 14)
	column.add_child(_window_info_label)

	var remove := Button.new()
	remove.text = "Remove zone"
	remove.tooltip_text = "Deletes this storage zone. Stored items stay where they are as loose drops."
	remove.focus_mode = Control.FOCUS_NONE
	remove.custom_minimum_size = Vector2(166.0, 30.0)
	remove.add_theme_font_size_override("font_size", 13)
	remove.pressed.connect(func() -> void:
		remove_zone(_window_zone_id)
	)
	column.add_child(remove)


## Zone click-select at an arbitrary screen position — usable while the tool
## is INACTIVE (the mining controller's _try_select_zone_at_screen pattern).
## Returns true if a zone window was opened (caller consumes the click).
func _try_select_zone_at_screen(screen_pos: Vector2) -> bool:
	var hit := _surface_cell_for(screen_pos)
	if hit.is_empty():
		return false
	var cell := Vector3i(int(hit["x"]), int(hit["y"]), int(hit["z"]))
	if not _cell_to_zone.has(cell):
		return false
	_open_zone_window(int(_cell_to_zone[cell]))
	return true


func _open_zone_window(zone_id: int) -> void:
	var zone: StockpileZoneComponent = _zones.get(zone_id)
	if zone == null:
		return
	_window_zone_id = zone_id
	_window_info_label.text = "Cells: %d\nStored: %d\nFilter: all goods" % [
		zone.cell_count(), zone.stored_count()]
	_window_layer.visible = true


func _close_zone_window() -> void:
	_window_zone_id = -1
	_window_layer.visible = false


func _style(bg: Color, border: Color, border_width: int, radius: int) -> StyleBoxFlat:
	var style := StyleBoxFlat.new()
	style.bg_color = bg
	style.border_color = border
	style.border_width_left = border_width
	style.border_width_right = border_width
	style.border_width_top = border_width
	style.border_width_bottom = border_width
	style.corner_radius_top_left = radius
	style.corner_radius_top_right = radius
	style.corner_radius_bottom_left = radius
	style.corner_radius_bottom_right = radius
	return style

source_text.scripts/systems/StockpileManager.gd:
extends Node

## Colony storage coordinator (doc 18 §2.2 / Phase 3). Autoload, registered
## after InteriorTracker (needs TaskManager for work-source registration and
## config). Owns the zone registry and the aggregate view; the designation
## controller owns designation/overlay/window, ItemDropManager owns the item
## nodes and resources.json.
##
## LEASE WAKE SOURCES (event-driven, doc 16 §2.5 discipline — never a frame
## scan): drop spawned (new loose item), zone registered, HAUL task left the
## system (completed/released/cancelled/failed). Wakes are throttled to one
## lease-posting pass per LEASE_REFRESH_S (the mining stalled-zone throttle
## pattern) and iterate zones only — zones themselves cap the work.
##
## SOURCE-ID NAMESPACE: TaskManager work-source keys are shared with mining
## zones (both count from 1), so stockpile sources live at SOURCE_ID_BASE +
## zone_id. Recorded tech debt: a TaskManager-owned source-id allocator is
## the clean fix when a third work-source system appears (doc 18 build log).

signal stockpile_changed(item_key: String, delta: int)

const SOURCE_ID_BASE := 1_000_000
const LEASE_REFRESH_S := 0.25

var _zones: Dictionary = {}          # source_id -> StockpileZoneComponent
var _containers: Dictionary = {}     # source_id -> ContainerStorageComponent (doc 19 Phase 4)
var _totals: Dictionary = {}         # item_key -> stored count (aggregate)
var _max_haulers: int = 2
var _carry_mult_heavy: float = 0.7
var _pouch_capacity: int = 4
var _pouch_radius: int = 8

var _drop_manager: Node3D = null
var _drop_manager_connected: bool = false
var _lease_dirty: bool = false
var _lease_accum: float = 0.0


func _ready() -> void:
	var hauling: Dictionary = TaskManager.get_config_section("hauling")
	_max_haulers = int(hauling.get("max_haulers_per_zone", _max_haulers))
	_carry_mult_heavy = float(hauling.get("carry_speed_mult_heavy", _carry_mult_heavy))
	_pouch_capacity = int(hauling.get("pouch_capacity", _pouch_capacity))
	_pouch_radius = int(hauling.get("pouch_bundle_radius", _pouch_radius))
	TaskManager.task_completed.connect(_on_task_completed)
	TaskManager.task_released.connect(_on_task_released)
	TaskManager.task_cancelled.connect(_on_task_gone_signal)
	TaskManager.task_failed.connect(_on_task_failed)
	print("StockpileManager: ready (max haulers/zone %d, heavy carry ×%.2f)." % [
		_max_haulers, _carry_mult_heavy])


func _process(delta: float) -> void:
	# Lazy drop-manager hookup: the scene node may enter the tree after this
	# autoload's _ready. Connect once, then this branch never runs again.
	if not _drop_manager_connected:
		_drop_manager = get_tree().get_first_node_in_group("item_drop_manager") as Node3D
		if _drop_manager != null:
			_drop_manager.connect("drop_spawned", _on_drop_spawned)
			_drop_manager_connected = true
			# Backfill zones registered before the scene node entered the tree.
			for source_id: int in _zones:
				(_zones[source_id] as StockpileZoneComponent).drop_manager = _drop_manager
			for source_id: int in _containers:
				(_containers[source_id] as ContainerStorageComponent).drop_manager = _drop_manager
	if not _lease_dirty:
		return
	_lease_accum += delta
	if _lease_accum < LEASE_REFRESH_S:
		return
	_lease_accum = 0.0
	_lease_dirty = false
	for source_id: int in _zones:
		(_zones[source_id] as StockpileZoneComponent).update_leases()
	for source_id: int in _containers:
		(_containers[source_id] as ContainerStorageComponent).update_leases()


# ── Zone registry (called by StockpileDesignationController) ──────────────────

func register_zone(zone: StockpileZoneComponent) -> void:
	zone.source_id = SOURCE_ID_BASE + zone.zone_id
	zone.max_haulers = _max_haulers
	zone.carry_speed_mult_heavy = _carry_mult_heavy
	zone.pouch_capacity = _pouch_capacity
	zone.pouch_bundle_radius = _pouch_radius
	zone.drop_manager = _drop_manager
	zone.changed_callback = _on_zone_deposit
	_zones[zone.source_id] = zone
	TaskManager.register_work_source(zone.source_id, zone)
	_mark_dirty()


## Container registered by FurniturePlacementController on install (doc 19
## Phase 4). Source id comes from the caller (TaskManager.allocate_source_id).
func register_container(container: ContainerStorageComponent) -> void:
	container.max_haulers = _max_haulers
	container.carry_speed_mult_heavy = _carry_mult_heavy
	container.pouch_capacity = _pouch_capacity
	container.pouch_bundle_radius = _pouch_radius
	container.drop_manager = _drop_manager
	container.changed_callback = _on_zone_deposit
	_containers[container.source_id] = container
	TaskManager.register_work_source(container.source_id, container)
	_mark_dirty()


## Container removed (uninstall/DEV): contents are the CALLER's to dump
## (FurniturePlacementController tears down in order); this frees the slots.
func deregister_container(container: ContainerStorageComponent) -> void:
	if not _containers.has(container.source_id):
		return
	_containers.erase(container.source_id)
	TaskManager.cancel_source_tasks(container.source_id)
	TaskManager.unregister_work_source(container.source_id)
	_mark_dirty()


## Zone removed by the player: cancel its leases, free its work-source slot,
## and return its stored items to the world as loose drops (doc 18 §2.4 —
## stacked counts respawn so nothing is lost).
func deregister_zone(zone: StockpileZoneComponent) -> void:
	if not _zones.has(zone.source_id):
		return
	_zones.erase(zone.source_id)
	TaskManager.cancel_source_tasks(zone.source_id)
	TaskManager.unregister_work_source(zone.source_id)
	for cell: Vector3i in zone.cell_stacks:
		var stack: Dictionary = zone.cell_stacks[cell]
		_apply_total(String(stack.get("item", "")), -int(stack.get("count", 0)))
	if _drop_manager != null and is_instance_valid(_drop_manager):
		_drop_manager.call("release_stored_cells", zone.cell_stacks)
	_mark_dirty()


# ── Aggregates (doc 23 API surface — status-bar counters consume this later) ──

func get_total(item_key: String) -> int:
	return int(_totals.get(item_key, 0))


func get_stats() -> Dictionary:
	var cells: int = 0
	var stored: int = 0
	for source_id: int in _zones:
		var zone: StockpileZoneComponent = _zones[source_id]
		cells += zone.cell_count()
		stored += zone.stored_count()
	for source_id: int in _containers:
		stored += (_containers[source_id] as ContainerStorageComponent).stored_count()
	return { "zones": _zones.size(), "cells": cells, "stored": stored, "containers": _containers.size() }


## Scene-reload boundary. Work-source state is transient and TaskManager is
## reset separately; restored zones/containers register themselves afresh.
func reset_runtime_state() -> void:
	if _drop_manager_connected and _drop_manager != null \
			and is_instance_valid(_drop_manager) \
			and _drop_manager.is_connected("drop_spawned", _on_drop_spawned):
		_drop_manager.disconnect("drop_spawned", _on_drop_spawned)
	_zones.clear()
	_containers.clear()
	_totals.clear()
	_drop_manager = null
	_drop_manager_connected = false
	_lease_dirty = false
	_lease_accum = 0.0


## Recomputes aggregate counts after all restored storage owners are present.
func rebuild_totals() -> void:
	_totals.clear()
	for source_id: int in _zones:
		var zone: StockpileZoneComponent = _zones[source_id]
		for cell: Vector3i in zone.cell_stacks:
			var stack: Dictionary = zone.cell_stacks[cell]
			var key := String(stack.get("item", ""))
			var count := int(stack.get("count", 0))
			if not key.is_empty() and count > 0:
				_totals[key] = int(_totals.get(key, 0)) + count
	for source_id: int in _containers:
		var container: ContainerStorageComponent = _containers[source_id]
		for key: String in container.inventory:
			var count := int(container.inventory[key])
			if count > 0:
				_totals[key] = int(_totals.get(key, 0)) + count
	_mark_dirty()


## Fetch withdraw (doc 19 §3.3): pull one stored unit of `item_key` out of
## the zone nearest `near`, reserved for `dwarf_id`. Null if no zone holds
## the item. Containers join this lookup in Phase 4 via the same surface.
func withdraw_item(item_key: String, near: Vector3i, dwarf_id: int) -> Node3D:
	var best_zone: StockpileZoneComponent = null
	var best_dist: int = 0x7FFFFFFF
	for source_id: int in _zones:
		var zone: StockpileZoneComponent = _zones[source_id]
		var has_it := false
		for cell: Vector3i in zone.cell_stacks:
			if String((zone.cell_stacks[cell] as Dictionary).get("item", "")) == item_key:
				has_it = true
				break
		if not has_it:
			continue
		var target := zone.nearest_stand_target(near)
		var d := target - near
		var dist := absi(d.x) + absi(d.y) + absi(d.z)
		if dist < best_dist:
			best_zone = zone
			best_dist = dist
	if best_zone != null:
		return best_zone.withdraw_nearest(item_key, near, dwarf_id)
	# No zone holds it — try containers (doc 19 Phase 4).
	for source_id: int in _containers:
		var container: ContainerStorageComponent = _containers[source_id]
		if int(container.inventory.get(item_key, 0)) > 0:
			return container.withdraw_nearest(item_key, near, dwarf_id)
	return null


# ── Wake plumbing ─────────────────────────────────────────────────────────────

func _mark_dirty() -> void:
	_lease_dirty = true


func _on_drop_spawned(_item_key: String) -> void:
	_mark_dirty()


func _on_zone_deposit(item_key: String, delta: int) -> void:
	_apply_total(item_key, delta)


func _apply_total(item_key: String, delta: int) -> void:
	if item_key.is_empty() or delta == 0:
		return
	_totals[item_key] = int(_totals.get(item_key, 0)) + delta
	stockpile_changed.emit(item_key, delta)


func _route(task: Task, dwarf_id: int) -> void:
	if task.source_id < SOURCE_ID_BASE:
		return
	var zone: StockpileZoneComponent = _zones.get(task.source_id)
	if zone != null:
		zone.on_task_gone(task.id, dwarf_id)
	var container: ContainerStorageComponent = _containers.get(task.source_id)
	if container != null:
		container.on_task_gone(task.id, dwarf_id)
	_mark_dirty()


func _on_task_completed(task: Task) -> void:
	# Clean completion: the dwarf already resolved its pull; free the lease id
	# only (dwarf_id -1 skips the reservation cleanup).
	_route(task, -1)


func _on_task_released(task: Task, dwarf_id: int, _reason: int) -> void:
	# A released lease returns to PENDING — it still counts against
	# max_haulers, so only the dwarf's reservations are freed here.
	if task.source_id < SOURCE_ID_BASE:
		return
	var zone: StockpileZoneComponent = _zones.get(task.source_id)
	if zone != null:
		zone.cancel_haul(dwarf_id)
	var container: ContainerStorageComponent = _containers.get(task.source_id)
	if container != null:
		container.cancel_haul(dwarf_id)
	_mark_dirty()


func _on_task_gone_signal(task: Task) -> void:
	_route(task, task.assigned_to)


func _on_task_failed(task: Task, _reason: String) -> void:
	_route(task, task.assigned_to)

source_text.scripts/systems/SurfaceFloraSpawner.gd:
class_name SurfaceFloraSpawner
extends Node3D

## Surface flora placement — MIXED FOREST (pine, oak, apple, juniper).
##
## Scatters trees across the world by ECOLOGY: each species has an elevation +
## domain + moisture niche (see WorldGenerator.get_moisture). A single shared
## scatter grid holds at most one tree per cell; per cell every species is scored
## for suitability and one is chosen by a seeded weighted pick (or the cell is left
## open). This blends species across the moisture/elevation gradient and prevents
## overlapping trunks. Streams in/out with the camera like the terrain.
##
## Design + decisions: docs/00_dev_roadmap/14_flora_distribution_plan.md
##                     docs/00_dev_roadmap/13_flora_scatter_pine.md (pine first pass)
## Placement data:     data/entities/flora/<species>_tree.json -> "placement"
## Footprint / rules:  docs/40_economy_colony/42_farming_brewing.md (Surface Trees)
##
## OWNS its own data loading (the VisitorManager pattern — no separate registry
## autoload for flora). All FileAccess for flora JSON happens here.
##
## Determinism (Hard Rule 8): every decision is a pure function of
## WorldGenerator.world_seed + column XZ. No randi()/randf().

# ── Streaming geometry (mirror WorldData / WorldRenderer) ─────────────────────
const CHUNK_SIZE:    int = 16
const CHUNK_COUNT_X: int = 64
const CHUNK_COUNT_Z: int = 64

# ── Domain constants (must match WorldGenerator) ──────────────────────────────
const DOMAIN_LOWLAND:  int = 0
const DOMAIN_VALLEY:   int = 1   # foothill domain / valley corridor
const DOMAIN_MOUNTAIN: int = 2

# ── Tunables (exported so they can be adjusted in the editor) ─────────────────

## Flora definition JSON files. Each holds one "base:flora:*_tree" species block.
## A file without a "placement" block is skipped (assets exist but no niche yet).
@export var flora_json_paths: Array[String] = [
	"res://data/entities/flora/pine_tree.json",
	"res://data/entities/flora/oak_tree.json",
	"res://data/entities/flora/apple_tree.json",
	"res://data/entities/flora/juniper_tree.json",
]

## Shared scatter grid: one candidate tree per cell_size×cell_size block cell
## (bigger = sparser overall). This is the master density dial; per-species
## base_density (in each JSON) sets the relative mix within a cell.
@export_range(2, 64, 1) var scatter_cell_size: int = 14

## Cap on the chance a suitable cell holds a tree (summed species suitability is
## clamped to this). Keeps even the richest mixing zones from being 100% covered.
@export_range(0.0, 1.0, 0.01) var max_cell_occupancy: float = 0.9

## XZ chunk radius around the camera that spawns flora (only used when
## cover_whole_map is OFF). Match WorldRenderer's view_radius_chunks.
@export_range(1, 64, 1) var view_radius_chunks: int = 5

## Scale conversion. The live world renders 1 block = 1.0 Godot unit (doc 13 §5).
## Trees are authored 1:1 — 1 voxel = 1 block (the Stonehearth tree convention,
## doc 61) with .import root_scale = 1.0 (never edit .import). So instance_scale =
## godot_units_per_block / voxels_per_block = 1.0 / 1.0 = 1.0. Characters/items use
## 8 voxels/block via their own import scale.
@export var voxels_per_block: float = 1.0
@export var godot_units_per_block: float = 1.0

## Whole-map mode (default): scatter across the ENTIRE map once and keep it, so
## trees do not pop in/out or "follow" the overview camera. Columns are still
## spawned over several frames (spawn_budget_per_frame). Turn OFF to fall back to
## camera-radius streaming (view_radius_chunks) for a future close camera.
@export var cover_whole_map: bool = true

## Chunk-columns spawned per frame while filling in.
@export_range(1, 256, 1) var spawn_budget_per_frame: int = 24

## Mature/ancient trees get a StaticBody3D + box collider (dwarves path around
## them). With no agents yet, whole-map mode spawns thousands of bodies; turn off
## if physics cost is a problem until agents exist.
@export var enable_collision: bool = true

## Physics layer for mature/ancient tree colliders. MUST NOT include Layer 1: the
## RTS camera's SpringArm3D collides against Layer 1 (terrain only) to avoid
## clipping, so trees on Layer 1 yank the camera down on a quick pan. Layer 2
## keeps tree obstacles available for future dwarf pathing (see Camera.gd).
@export_flags_3d_physics var tree_collision_layer: int = 2

@export var debug_logging: bool = true

## Slice tool — placed flora hide above the active cut plane (11_slice_xray_plan.md
## Phase 5). Wire to the SliceController node; leave empty to disable slice culling.
@export var slice_controller_path: NodePath

# ── Loaded data ───────────────────────────────────────────────────────────────
## One entry per usable species: { key, name, placement, stages, domains }.
var _species: Array[Dictionary] = []

# ── Runtime state ─────────────────────────────────────────────────────────────
var _ready_to_spawn: bool = false
var _camera: Camera = null
var _camera_chunk: Vector2i = Vector2i(-9999, -9999)
var _season: String = "summer"

var _loaded_columns: Dictionary = {}    # Vector2i(cx,cz) -> Array[Node3D]
var _pending: Array[Vector2i] = []      # chunk-columns awaiting spawn
var _pending_set: Dictionary = {}       # Vector2i -> true (dedupe)

var _scene_cache: Dictionary = {}       # model path -> PackedScene
var _tree_material: Material = null
var _spawned_count: int = 0

const SLICE_OFF_Y: int = 127            # SliceController.MAX_SLICE_Y → slice off (all flora visible)
var _slice_controller: Node = null
var _slice_y: int = SLICE_OFF_Y         # active cut plane; trees with base_y > this are hidden


func _ready() -> void:
	_tree_material = _build_tree_material()
	if not _load_all_flora():
		push_error("SurfaceFloraSpawner: no usable flora definitions; disabled.")
		set_process(false)
		return

	# Arming is poll-based (see _process): the spawner needs the heightmap, domain
	# map and moisture noise, all valid once WorldGenerator reports maps_ready.
	if WorldClock.has_signal("season_changed"):
		WorldClock.season_changed.connect(_on_season_changed)
	_season = WorldClock.season

	_camera = _find_camera(get_tree().current_scene)

	# Slice culling: react to the Slice tool moving the cut plane.
	if not slice_controller_path.is_empty():
		_slice_controller = get_node_or_null(slice_controller_path)
		if _slice_controller != null and _slice_controller.has_signal("slice_changed"):
			_slice_controller.connect("slice_changed", _on_slice_changed)


func _arm() -> void:
	_ready_to_spawn = true
	_camera_chunk = Vector2i(-9999, -9999)   # force a full streaming pass
	if cover_whole_map:
		_enqueue_all_columns()
	if debug_logging:
		var names := []
		for sp in _species:
			names.append(sp["name"])
		print("SurfaceFloraSpawner: maps ready, scatter armed (seed=%d, species=%s, cell=%d, whole_map=%s, columns=%d)."
			% [WorldGenerator.world_seed, str(names), scatter_cell_size, str(cover_whole_map), _pending.size()])


## Queues every chunk-column, nearest-to-camera first so the looked-at area fills
## before the far corners. Used once in whole-map mode; never despawned.
func _enqueue_all_columns() -> void:
	var center := Vector2i(CHUNK_COUNT_X >> 1, CHUNK_COUNT_Z >> 1)
	if _camera != null:
		center = Vector2i(
			clampi(int(floor(_camera.global_position.x / CHUNK_SIZE)), 0, CHUNK_COUNT_X - 1),
			clampi(int(floor(_camera.global_position.z / CHUNK_SIZE)), 0, CHUNK_COUNT_Z - 1))
	var all: Array[Vector2i] = []
	for cx in range(CHUNK_COUNT_X):
		for cz in range(CHUNK_COUNT_Z):
			var key := Vector2i(cx, cz)
			if _loaded_columns.has(key) or _pending_set.has(key):
				continue
			all.append(key)
			_pending_set[key] = true
	all.sort_custom(func(a: Vector2i, b: Vector2i) -> bool:
		var da: int = maxi(absi(a.x - center.x), absi(a.y - center.y))
		var db: int = maxi(absi(b.x - center.x), absi(b.y - center.y))
		return da < db)
	_pending.append_array(all)


# ── Frame loop: stream + drain spawn queue ────────────────────────────────────

func _process(_delta: float) -> void:
	if not _ready_to_spawn:
		if bool(WorldGenerator.get_streaming_stats().get("maps_ready", false)):
			_arm()
		else:
			return

	if not cover_whole_map:
		if _camera == null:
			_camera = _find_camera(get_tree().current_scene)
			if _camera == null:
				return
		_update_streaming_center()

	var budget := spawn_budget_per_frame
	while budget > 0 and not _pending.is_empty():
		var key: Vector2i = _pending.pop_front()
		_pending_set.erase(key)
		if not cover_whole_map and not _column_in_radius(key.x, key.y):
			continue
		_spawn_column(key.x, key.y)
		budget -= 1


func _update_streaming_center() -> void:
	var next_chunk := Vector2i(
		clampi(int(floor(_camera.global_position.x / CHUNK_SIZE)), 0, CHUNK_COUNT_X - 1),
		clampi(int(floor(_camera.global_position.z / CHUNK_SIZE)), 0, CHUNK_COUNT_Z - 1))
	if next_chunk == _camera_chunk:
		return
	_camera_chunk = next_chunk

	var to_free: Array[Vector2i] = []
	for key: Vector2i in _loaded_columns.keys():
		if not _column_in_radius(key.x, key.y):
			to_free.append(key)
	for key: Vector2i in to_free:
		_despawn_column(key)

	for dz in range(-view_radius_chunks, view_radius_chunks + 1):
		for dx in range(-view_radius_chunks, view_radius_chunks + 1):
			var cx := _camera_chunk.x + dx
			var cz := _camera_chunk.y + dz
			if cx < 0 or cx >= CHUNK_COUNT_X or cz < 0 or cz >= CHUNK_COUNT_Z:
				continue
			if not _column_in_radius(cx, cz):
				continue
			var key := Vector2i(cx, cz)
			if _loaded_columns.has(key) or _pending_set.has(key):
				continue
			_pending.append(key)
			_pending_set[key] = true


func _column_in_radius(cx: int, cz: int) -> bool:
	var dx := cx - _camera_chunk.x
	var dz := cz - _camera_chunk.y
	return dx * dx + dz * dz <= view_radius_chunks * view_radius_chunks


# ── Per-column scatter ────────────────────────────────────────────────────────

## Spawns every tree whose scatter cell is ANCHORED in this chunk column. A cell
## is owned by the single chunk that contains its origin corner, so cells
## straddling a chunk boundary spawn exactly once.
func _spawn_column(cx: int, cz: int) -> void:
	var nodes: Array[Node3D] = []
	var x0 := cx * CHUNK_SIZE
	var z0 := cz * CHUNK_SIZE
	var size := maxi(1, scatter_cell_size)

	var cell_x_lo := int(ceil(float(x0) / float(size)))
	var cell_x_hi := int(floor(float(x0 + CHUNK_SIZE - 1) / float(size)))
	var cell_z_lo := int(ceil(float(z0) / float(size)))
	var cell_z_hi := int(floor(float(z0 + CHUNK_SIZE - 1) / float(size)))

	for cell_x in range(cell_x_lo, cell_x_hi + 1):
		for cell_z in range(cell_z_lo, cell_z_hi + 1):
			var tree := _try_spawn_cell(cell_x, cell_z, size)
			if tree != null:
				nodes.append(tree)

	_loaded_columns[Vector2i(cx, cz)] = nodes


## Evaluates one scatter cell against ALL species; returns the spawned tree or null.
func _try_spawn_cell(cell_x: int, cell_z: int, size: int) -> Node3D:
	var h_pos := _hash(cell_x, cell_z, 101)          # jitter within cell
	var jx: int = h_pos % size
	var jz: int = floori(float(h_pos) / float(size)) % size
	var wx := cell_x * size + jx
	var wz := cell_z * size + jz

	if wx < 0 or wx >= CHUNK_COUNT_X * CHUNK_SIZE:
		return null
	if wz < 0 or wz >= CHUNK_COUNT_Z * CHUNK_SIZE:
		return null

	# Environment, read once.
	var domain := WorldGenerator.get_domain(wx, wz)
	var ground_y := WorldGenerator.get_surface_y(wx, wz)
	if ground_y < 0:
		return null
	var water := _is_water(wx, wz)
	var moisture := WorldGenerator.get_moisture(wx, wz)

	# Score every species; sum suitability.
	var total := 0.0
	var scores: Array[float] = []
	scores.resize(_species.size())
	for i in range(_species.size()):
		var s := _suitability(_species[i], domain, ground_y, moisture, water, wx, wz)
		scores[i] = s
		total += s
	if total <= 0.0:
		return null

	# Presence test (clamped so even rich cells leave some gaps).
	var presence := minf(total, max_cell_occupancy)
	if _unit(_hash(cell_x, cell_z, 202)) >= presence:
		return null

	# Weighted species pick.
	var r := _unit(_hash(cell_x, cell_z, 303)) * total
	var chosen := -1
	var acc := 0.0
	for i in range(scores.size()):
		acc += scores[i]
		if r < acc:
			chosen = i
			break
	if chosen < 0:
		return null
	var sp: Dictionary = _species[chosen]
	var placement: Dictionary = sp["placement"]
	var stages: Dictionary = sp["stages"]

	# Stage + footprint.
	var stage_name := _pick_stage(placement, _hash(cell_x, cell_z, 304))
	var stage_data: Dictionary = stages.get(stage_name, {})
	if stage_data.is_empty():
		return null
	var footprint: int = _footprint_for(placement, stage_name)

	# Flatness / validity and cliff-lip setback over the footprint.
	if not _footprint_ok(placement, wx, wz, footprint, ground_y):
		return null
	if not _edge_ok(placement, wx, wz, footprint, ground_y):
		return null

	var model_path := resolve_tree_model_for_season(
		stage_data, _season, Vector3i(wx, ground_y, wz))
	if model_path == "":
		return null

	return _instance_tree(sp["name"], model_path, stage_name, stage_data, wx, wz, ground_y, footprint)


## Per-species suitability weight for a column (0 = unsuitable). Gates on domain,
## elevation band, water and moisture niche; scaled by base_density, the treeline
## falloff (if any) and the grove mask (apple).
func _suitability(sp: Dictionary, domain: int, ground_y: int, moisture: float,
		water: bool, wx: int, wz: int) -> float:
	var pl: Dictionary = sp["placement"]
	if not (sp["domains"] as Dictionary).has(domain):
		return 0.0
	if water and bool(pl.get("exclude_water", true)):
		return 0.0
	if ground_y < int(pl.get("min_surface_y", 0)):
		return 0.0
	if ground_y > int(pl.get("max_surface_y", 100000)):
		return 0.0
	var mw := _moisture_weight(pl, moisture)
	if mw <= 0.0:
		return 0.0
	var fall := _falloff_factor(pl, ground_y)
	if fall <= 0.0:
		return 0.0
	var grove := _grove_weight(pl, wx, wz)
	if grove <= 0.0:
		return 0.0
	var base := float(pl.get("base_density", pl.get("spawn_chance", 0.4)))
	return base * mw * fall * grove


# ── Instancing ────────────────────────────────────────────────────────────────

func _instance_tree(species_name: String, model_path: String, stage_name: String,
		stage_data: Dictionary, wx: int, wz: int, ground_y: int, footprint: int) -> Node3D:
	var packed := _load_scene(model_path)
	if packed == null:
		return null

	var instance_scale := godot_units_per_block / maxf(voxels_per_block, 0.0001)
	# Trunk base sits on the TOP face of the surface block: y = ground_y + 1.
	# Centre the footprint on the trunk cell.
	var origin := Vector3(
		float(wx) + 0.5 * footprint,
		float(ground_y + 1),
		float(wz) + 0.5 * footprint)

	var is_clutter := (stage_name == "sapling") or not enable_collision
	var root: Node3D
	if is_clutter:
		root = Node3D.new()
	else:
		var body := StaticBody3D.new()
		body.collision_layer = tree_collision_layer
		body.collision_mask = 0
		root = body

	root.position = origin
	root.name = "%s_%s_%d_%d" % [species_name, stage_name, wx, wz]

	var visual := packed.instantiate() as Node3D
	if visual == null:
		root.free()
		push_error("SurfaceFloraSpawner: %s did not instance as Node3D" % model_path)
		return null
	visual.scale = Vector3.ONE * instance_scale
	_apply_material_recursive(visual)
	root.add_child(visual)

	if not is_clutter:
		var height := float(int(stage_data.get("clearance_height", footprint * 4))) \
			* godot_units_per_block
		var col := CollisionShape3D.new()
		var box := BoxShape3D.new()
		box.size = Vector3(float(footprint), height, float(footprint))
		col.shape = box
		col.position = Vector3(0.0, height * 0.5, 0.0)
		root.add_child(col)

	# Slice culling: remember the base for later re-cull, and respect the current cut
	# plane immediately so trees streamed in while a slice is active spawn hidden.
	root.set_meta("base_y", ground_y)
	root.visible = ground_y <= _slice_y

	# Nav occupancy (doc 16 step 3a — dwarves walk around trees): mature/ancient
	# trunks register footprint × clearance_height with PlacedEntityRegistry.
	# Saplings (clutter) register nothing; canopy overhang carries no occupancy
	# (Hard Rule 5 spirit). Independent of enable_collision — occupancy is nav
	# data, the StaticBody3D is physics.
	if stage_name != "sapling":
		var occ_height := int(stage_data.get("clearance_height", footprint * 4))
		var occ_id := PlacedEntityRegistry.register_box(
			Vector3i(wx, ground_y + 1, wz),
			Vector3i(footprint, occ_height, footprint))
		root.set_meta("occupancy_id", occ_id)

	add_child(root)
	_spawned_count += 1
	return root


func _despawn_column(key: Vector2i) -> void:
	var nodes: Array = _loaded_columns.get(key, [])
	for n in nodes:
		if is_instance_valid(n):
			if n.has_meta("occupancy_id"):
				PlacedEntityRegistry.unregister(int(n.get_meta("occupancy_id")))
			_spawned_count -= 1
			n.queue_free()
	_loaded_columns.erase(key)


# ── Slice culling (11_slice_xray_plan.md Phase 5) ─────────────────────────────

## Hide trees whose base sits above the active cut plane. Coarse per-instance toggle:
## a tree straddling the plane shows whole (canopy may poke above) — acceptable v1; a
## per-prop clip plane would be the clean follow-up. slice_y = 127 (off) shows all.
func _on_slice_changed(new_slice_y: int) -> void:
	if new_slice_y == _slice_y:
		return
	_slice_y = new_slice_y
	for key in _loaded_columns:
		for n in _loaded_columns[key]:
			if is_instance_valid(n):
				n.visible = int(n.get_meta("base_y", 0)) <= _slice_y


# ── Canonical model variant resolution (the ONE resolution point, per doc 42) ─

## Resolves a season's model value (String or Array[String]) to one path, using a
## deterministic spatial hash so the same position always yields the same variant.
static func resolve_tree_model(models_value, world_pos: Vector3i) -> String:
	if models_value is String:
		return models_value
	if models_value is Array and not (models_value as Array).is_empty():
		var arr: Array = models_value
		var h: int = (world_pos.x * 73856093) ^ (world_pos.z * 19349663) ^ (world_pos.y * 83492791)
		return String(arr[abs(h) % arr.size()])
	push_error("resolve_tree_model: invalid models_value at %s" % str(world_pos))
	return ""


## Picks the model for a season with fallback: requested -> "summer" -> error.
static func resolve_tree_model_for_season(
		stage_data: Dictionary, season: String, world_pos: Vector3i) -> String:
	var models: Dictionary = stage_data.get("models", {})
	if season == "autumn" and stage_data.has("fruit_harvest") and models.has("autumn_fruiting"):
		return resolve_tree_model(models["autumn_fruiting"], world_pos)
	var value = models.get(season, models.get("summer", ""))
	if value is String and value == "":
		push_error("resolve_tree_model_for_season: no model for season '%s'" % season)
		return ""
	return resolve_tree_model(value, world_pos)


# ── Suitability helpers ───────────────────────────────────────────────────────

## Treeline / band falloff [0,1] by surface elevation. Species without
## full_density_max_y/falloff_max_y (only pine defines them) get a flat 1.0.
func _falloff_factor(pl: Dictionary, surface_y: int) -> float:
	if not pl.has("full_density_max_y"):
		return 1.0
	var full_max := int(pl.get("full_density_max_y", 75))
	var fall_max := int(pl.get("falloff_max_y", 90))
	if surface_y <= full_max:
		return 1.0
	if surface_y >= fall_max or fall_max <= full_max:
		return 0.0
	return 1.0 - float(surface_y - full_max) / float(fall_max - full_max)


## Moisture niche weight [0,1]: 1.0 inside [moisture_min, moisture_max], tapering
## to 0 over moisture_margin outside. Absent keys = no moisture preference (1.0).
func _moisture_weight(pl: Dictionary, m: float) -> float:
	var mmin := float(pl.get("moisture_min", 0.0))
	var mmax := float(pl.get("moisture_max", 1.0))
	var margin := float(pl.get("moisture_margin", 0.15))
	if m >= mmin and m <= mmax:
		return 1.0
	if margin <= 0.0:
		return 0.0
	if m < mmin:
		return maxf(0.0, 1.0 - (mmin - m) / margin)
	return maxf(0.0, 1.0 - (m - mmax) / margin)


## Grove clustering (apple). Returns 1.0 inside a grove cell, else 0.0. A grove
## cell is a coarse cell_size×cell_size block region selected by a hashed
## threshold, so wild apples cluster into orchards instead of even scatter.
func _grove_weight(pl: Dictionary, wx: int, wz: int) -> float:
	var g: Dictionary = pl.get("grove", {})
	if g.is_empty() or not bool(g.get("enabled", false)):
		return 1.0
	var cs := maxi(1, int(g.get("cell_size", 28)))
	var thr := float(g.get("threshold", 0.4))
	var gx := int(floor(float(wx) / float(cs)))
	var gz := int(floor(float(wz) / float(cs)))
	return 1.0 if _unit(_hash(gx, gz, 909)) < thr else 0.0


func _pick_stage(pl: Dictionary, h: int) -> String:
	var weights: Dictionary = pl.get("stage_weights", {})
	var total := 0.0
	for k in weights.keys():
		total += float(weights[k])
	if total <= 0.0:
		return "mature"
	var r := _unit(h) * total
	var acc := 0.0
	for k in ["sapling", "mature", "ancient"]:
		acc += float(weights.get(k, 0.0))
		if r < acc:
			return k
	return "mature"


func _footprint_for(pl: Dictionary, stage_name: String) -> int:
	var fp: Dictionary = pl.get("footprint", {})
	return int(fp.get(stage_name, 1))


## True if the footprint columns are solid ground, dry, and flat enough.
func _footprint_ok(pl: Dictionary, wx: int, wz: int, footprint: int, ground_y: int) -> bool:
	var max_slope := int(pl.get("max_surface_slope", 1))
	var min_y := int(pl.get("min_surface_y", 0))
	var excl_water := bool(pl.get("exclude_water", true))
	for ddx in range(footprint):
		for ddz in range(footprint):
			var sx := wx + ddx
			var sz := wz + ddz
			var sy := WorldGenerator.get_surface_y(sx, sz)
			if sy < min_y:
				return false
			if absi(sy - ground_y) > max_slope:
				return false
			if excl_water and _is_water(sx, sz):
				return false
	return true


## Keeps trees set back from drops. Scans a ring `edge_margin` blocks wide around
## the footprint and rejects if any ring column is off-world (void) or drops more
## than `edge_dropoff_max` below the trunk. edge_margin <= 0 disables the check.
func _edge_ok(pl: Dictionary, wx: int, wz: int, footprint: int, ground_y: int) -> bool:
	var margin := int(pl.get("edge_margin", 1))
	if margin <= 0:
		return true
	var dropoff_max := int(pl.get("edge_dropoff_max", 3))
	var x_lo := wx - margin
	var x_hi := wx + footprint - 1 + margin
	var z_lo := wz - margin
	var z_hi := wz + footprint - 1 + margin
	for sx in range(x_lo, x_hi + 1):
		for sz in range(z_lo, z_hi + 1):
			var on_ring := sx < wx or sx > wx + footprint - 1 \
				or sz < wz or sz > wz + footprint - 1
			if not on_ring:
				continue
			var sy := WorldGenerator.get_surface_y(sx, sz)
			if sy < 0:
				return false
			if ground_y - sy > dropoff_max:
				return false
	return true


func _is_water(wx: int, wz: int) -> bool:
	var c := Vector2i(wx, wz)
	return WorldGenerator.lake_columns.has(c) \
		or WorldGenerator.tarn_columns.has(c) \
		or WorldGenerator.water_bank_columns.has(c)


## Deterministic positive 31-bit hash of (x, z, salt) folded with the world seed.
func _hash(x: int, z: int, salt: int) -> int:
	var h: int = WorldGenerator.world_seed * 2654435761 + 0x9E3779B9
	h ^= x * 73856093
	h ^= z * 19349663
	h ^= salt * 83492791
	h ^= (h >> 13)
	h *= 1274126177
	h ^= (h >> 16)
	return h & 0x7FFFFFFF


func _unit(h: int) -> float:
	return float(h) / 2147483647.0


func _load_scene(path: String) -> PackedScene:
	if _scene_cache.has(path):
		return _scene_cache[path]
	if not ResourceLoader.exists(path):
		push_error("SurfaceFloraSpawner: model not found: %s" % path)
		_scene_cache[path] = null
		return null
	var packed := load(path) as PackedScene
	_scene_cache[path] = packed
	return packed


func _apply_material_recursive(node: Node) -> void:
	if node is MeshInstance3D:
		(node as MeshInstance3D).material_override = _tree_material
	for child in node.get_children():
		_apply_material_recursive(child)


## Mirrors WorldRenderer._create_material(): vertex colour as albedo, DOUBLE-SIDED
## (CULL_DISABLED) so the sparse canopy shell shows no see-through back faces, and
## LIT (PER_PIXEL) so the voxel facets read as 3D under the sun.
func _build_tree_material() -> StandardMaterial3D:
	var mat := StandardMaterial3D.new()
	mat.vertex_color_use_as_albedo = true
	mat.roughness    = 1.0
	mat.metallic     = 0.0
	mat.cull_mode    = BaseMaterial3D.CULL_DISABLED
	mat.shading_mode = BaseMaterial3D.SHADING_MODE_PER_PIXEL
	return mat


func _on_season_changed(new_season: String) -> void:
	if new_season == _season:
		return
	var old_season := _season
	_season = new_season
	if not _ready_to_spawn:
		return
	# Skip the rebuild only if EVERY species resolves the old and new season to the
	# same model set (e.g. evergreens map spring/summer/autumn all to "summer").
	var changed := false
	for sp in _species:
		var stages: Dictionary = sp["stages"]
		if _effective_season_for(stages, old_season) != _effective_season_for(stages, new_season):
			changed = true
			break
	if not changed:
		return
	for key: Vector2i in _loaded_columns.keys():
		_despawn_column(key)
	_pending.clear()
	_pending_set.clear()
	if cover_whole_map:
		_enqueue_all_columns()
	else:
		_camera_chunk = Vector2i(-9999, -9999)


## Resolves a season to the model key it actually uses, per the summer fallback,
## using the "mature" stage as reference (all stages share the same season keys).
func _effective_season_for(stages: Dictionary, season: String) -> String:
	var ref: Dictionary = stages.get("mature", {})
	var models: Dictionary = ref.get("models", {})
	if season == "autumn" and ref.has("fruit_harvest") and models.has("autumn_fruiting"):
		return "autumn_fruiting"
	if models.has(season):
		return season
	return "summer"


func _find_camera(node: Node) -> Camera:
	if node is Camera:
		return node as Camera
	if node == null:
		return null
	for child: Node in node.get_children():
		var found := _find_camera(child)
		if found != null:
			return found
	return null


# ── Data loading (registry pattern — this system owns its flora JSON) ─────────

## Loads every flora JSON; keeps species that have both a "placement" and "stages"
## block. Files without placement (assets exist but no niche yet) are skipped.
func _load_all_flora() -> bool:
	_species.clear()
	for path in flora_json_paths:
		if not FileAccess.file_exists(path):
			push_warning("SurfaceFloraSpawner: missing %s (skipped)" % path)
			continue
		var f := FileAccess.open(path, FileAccess.READ)
		if f == null:
			push_warning("SurfaceFloraSpawner: cannot open %s (skipped)" % path)
			continue
		var parsed = JSON.parse_string(f.get_as_text())
		f.close()
		if typeof(parsed) != TYPE_DICTIONARY:
			push_warning("SurfaceFloraSpawner: malformed JSON %s (skipped)" % path)
			continue
		var key := _species_key(parsed)
		if key == "":
			push_warning("SurfaceFloraSpawner: no 'base:flora:*' key in %s (skipped)" % path)
			continue
		var def: Dictionary = parsed[key]
		var placement: Dictionary = def.get("placement", {})
		var stages: Dictionary = def.get("stages", {})
		if placement.is_empty() or stages.is_empty():
			if debug_logging:
				print("SurfaceFloraSpawner: %s has no placement yet (skipped)." % key)
			continue
		_species.append({
			"key": key,
			"name": _short_name(key),
			"placement": placement,
			"stages": stages,
			"domains": _domains_dict(placement.get("domains", [])),
		})
	return not _species.is_empty()


func _species_key(parsed: Dictionary) -> String:
	for k in parsed.keys():
		var s := String(k)
		if s.begins_with("base:flora:"):
			return s
	return ""


## "base:flora:pine_tree" -> "pine"
func _short_name(key: String) -> String:
	var tail := key.get_slice(":", 2)        # "pine_tree"
	return tail.replace("_tree", "")


func _domains_dict(domain_names: Array) -> Dictionary:
	var d: Dictionary = {}
	for dom_name in domain_names:
		match String(dom_name):
			"lowland":            d[DOMAIN_LOWLAND] = true
			"valley", "foothill": d[DOMAIN_VALLEY] = true
			"mountain":           d[DOMAIN_MOUNTAIN] = true
	return d


# ── Debug ─────────────────────────────────────────────────────────────────────

func get_spawn_stats() -> Dictionary:
	return {
		"spawned": _spawned_count,
		"species": _species.size(),
		"loaded_columns": _loaded_columns.size(),
		"pending_columns": _pending.size(),
		"season": _season,
	}

source_text.scripts/systems/TaskManager.gd:
extends Node

## The colony's task scheduler (doc 16 §2 — the no-hang architecture).
## Autoload, loaded after NavGrid (probes), before nothing in particular.
##
## OWNERSHIP: Tasks are entities owned exclusively by these tables. Dwarves
## hold task IDS only. Work sources (mining zones, step 5) post intent-sized
## tasks — NEVER per-block tasks (doc 16 §2.1: O(intents), not O(blocks)).
##
## SCHEDULING MODEL — event-driven with a heartbeat, never a frame scan:
##   - Wake events set a dirty flag (task added, dwarf idle, release); the
##     flag is flushed AT MOST once per frame in _process.
##   - A slow heartbeat (task_config.json) catches retry_at expiries.
##   - Each wake is TIME-BUDGETED (scheduler_budget_usec) and PROBE-CAPPED
##     (max_probes_per_wake); the matching loop stops mid-scan and resumes
##     from per-type cursors next wake. Overload degrades into assignment
##     LATENCY — never frame time. (doc 16 §2.5, hard rules.)
##   - Unreachable tasks back off exponentially (retry_at); after
##     unreachable_signal_threshold consecutive failures task_unreachable
##     fires for the UI. chunk_dirtied near a blocked target re-arms it early.
##
## RELEASE PROTOCOL (doc 16 §2.8): releasing a task is ALWAYS cheap and legal.
## release_dwarf_task() returns the task to PENDING with its static priority;
## work sources get notified via task_released to free reservations.
##
## JSON = what things are (budgets, priorities — data/tasks/task_config.json);
## GDScript = what things do (this loop).

signal task_added(task: Task)
signal task_assigned(task: Task, dwarf_id: int)
signal task_released(task: Task, dwarf_id: int, reason: int)
signal task_completed(task: Task)
signal task_failed(task: Task, reason: String)
signal task_cancelled(task: Task)
signal task_unreachable(task: Task)

const CONFIG_PATH := "res://data/tasks/task_config.json"

# ── Config (fallbacks mirror task_config.json) ───────────────────────────────
var _config_raw: Dictionary = {}          # full parsed task_config.json (see get_config_section)
var _budget_usec: int = 1000
var _max_probes_per_wake: int = 8
var _probe_node_cap: int = 200
var _heartbeat_s: float = 0.5
var _backoff_base_s: float = 2.0
var _backoff_max_s: float = 30.0
var _unreachable_threshold: int = 3
var _static_priorities: Dictionary = {}   # type name -> int

# ── Tables (doc 16 §2.3) ──────────────────────────────────────────────────────
var _tasks: Dictionary = {}            # id -> Task
var _pending: Dictionary = {}          # Task.Type (int) -> Array[int], static priority desc
var _active: Dictionary = {}           # dwarf_id -> task_id
var _idle_dwarves: Array[int] = []     # event-maintained
var _agents: Dictionary = {}           # dwarf_id -> DwarfAgent (weak by validity checks)
var _completed_log: Array = []         # ring buffer of dicts, last 200
var _scan_cursor: Dictionary = {}      # Task.Type -> int (resumable scan position)

var _next_task_id: int = 1
var _blocked_count: int = 0            # PENDING tasks currently in backoff (fast gate)

# ── Work sources (doc 16 §2.7 — zones now, workshops later) ──────────────────
# A work source posts intent-sized lease tasks (source_id = its id) and hands
# out per-block/per-batch work to the assigned dwarf directly — the scheduler
# never sees the atomic units. Dwarves resolve a lease's source through here,
# so work sources stay scene-decoupled from agents.
var _work_sources: Dictionary = {}     # source_id -> Object (e.g. MiningZoneComponent)

# ── Wake machinery ────────────────────────────────────────────────────────────
var _wake_dirty: bool = false
var _heartbeat_accum: float = 0.0

# ── Instrumentation (doc 16 Phase 0) ─────────────────────────────────────────
var _wake_count: int = 0
var _worst_wake_usec: int = 0
var _probes_total: int = 0
var _probes_at_last_stats: int = 0
var _stats_last_msec: int = 0


func _ready() -> void:
	_load_config()
	WorldData.chunk_dirtied.connect(_on_chunk_dirtied, CONNECT_DEFERRED)
	print("TaskManager: ready (budget %d us, %d probes/wake, heartbeat %.2f s)." % [
		_budget_usec, _max_probes_per_wake, _heartbeat_s])


func _process(delta: float) -> void:
	_heartbeat_accum += delta
	if _heartbeat_accum >= _heartbeat_s:
		_heartbeat_accum = 0.0
		_wake_dirty = true
	if _wake_dirty:
		_wake_dirty = false
		_run_scheduler()


# ── Public API — tasks ────────────────────────────────────────────────────────

## Creates and enqueues a task. Static priority defaults from task_config.json
## by type; pass priority >= 0 to override. Returns the task id.
func add_task(type: int, target_pos: Vector3i, payload: Dictionary = {},
		source_id: int = -1, priority: int = -1) -> int:
	var p := priority
	if p < 0:
		p = int(_static_priorities.get(Task.type_name(type), 1))
	var task := Task.new(type, p, target_pos, payload, source_id)
	task.id = _next_task_id
	_next_task_id += 1
	_tasks[task.id] = task
	_insert_pending(task)
	task_added.emit(task)
	_wake_dirty = true
	return task.id


func get_task(task_id: int) -> Task:
	return _tasks.get(task_id)


## Cancels a task outright (player action / source destroyed). Assigned tasks
## are pulled from their dwarf, who returns to the idle pool.
func cancel_task(task_id: int) -> void:
	var task: Task = _tasks.get(task_id)
	if task == null:
		return
	if task.status == Task.Status.PENDING or task.status == Task.Status.BLOCKED:
		_remove_pending(task)
	elif task.assigned_to >= 0:
		var dwarf_id := task.assigned_to
		_active.erase(dwarf_id)
		var agent: DwarfAgent = _agents.get(dwarf_id)
		if agent != null and is_instance_valid(agent):
			agent.abort_task()
		_mark_idle(dwarf_id)
	task.status = Task.Status.CANCELLED
	_tasks.erase(task_id)
	# Emit while assigned_to is still intact: source-side cancel cleanup
	# (StorageComponent.cancel_haul, FurnitureGhostComponent.cancel_fetch,
	# MiningZoneComponent.release_worker) routes by the cancelled dwarf's id.
	# Clearing it before the emit made every cancel route receive -1 and skip
	# cleanup — leaking reservations whenever the agent-side abort_task above
	# couldn't run (agent freed/invalid). abort_task and the source-side paths
	# are all owner-guarded and idempotent, so both running is safe.
	task_cancelled.emit(task)
	task.assigned_to = -1


## The dwarf finished its task. Logs it, frees the dwarf back into the pool.
func complete_dwarf_task(dwarf_id: int) -> void:
	var task := _take_active(dwarf_id)
	if task == null:
		return
	task.status = Task.Status.COMPLETED
	_log_completed(task)
	_tasks.erase(task.id)
	task_completed.emit(task)
	_mark_idle(dwarf_id)


## The RELEASE protocol (doc 16 §2.8): the task returns to PENDING intact;
## reservations are the source's to free on the task_released signal.
## requeue_dwarf=false when the dwarf is heading into an interrupt behaviour
## (sleep, combat) and will report idle later.
func release_dwarf_task(dwarf_id: int, reason: int, requeue_dwarf: bool = true) -> void:
	var task := _take_active(dwarf_id)
	if task == null:
		if requeue_dwarf:
			_mark_idle(dwarf_id)
		return
	task.status = Task.Status.PENDING
	task.assigned_to = -1
	_insert_pending(task)
	# PATH_INVALID means the dwarf actually failed to path there (stronger
	# evidence than a capped probe) — back the task off so the scheduler does
	# not immediately re-assign the same dead end (doc 16 §2.7 step 2).
	if reason == Task.ReleaseReason.PATH_INVALID:
		_apply_backoff(task, Time.get_ticks_msec())
	task_released.emit(task, dwarf_id, reason)
	if requeue_dwarf:
		_mark_idle(dwarf_id)
	_wake_dirty = true


## Permanent failure (target gone, invalid state). Task is removed, not retried.
func fail_dwarf_task(dwarf_id: int, reason: String) -> void:
	var task := _take_active(dwarf_id)
	if task == null:
		return
	task.status = Task.Status.FAILED
	_tasks.erase(task.id)
	task_failed.emit(task, reason)
	_mark_idle(dwarf_id)


# ── Public API — work sources (doc 16 §2.7) ──────────────────────────────────

## Source-id allocator (doc 19 §3.6 — the doc 18 tech debt, due with the
## third/fourth work-source families). Monotonic, starting above every
## existing keyspace (mining raw ids, stockpile zones at 1M). New families
## allocate here; migrating the old keyspaces is optional cleanup.
var _next_source_id: int = 10_000_000


func allocate_source_id() -> int:
	var id := _next_source_id
	_next_source_id += 1
	return id


func register_work_source(source_id: int, source: Object) -> void:
	_work_sources[source_id] = source


func unregister_work_source(source_id: int) -> void:
	_work_sources.erase(source_id)


## The work source behind a lease's source_id, or null if it is gone.
func get_work_source(source_id: int) -> Object:
	return _work_sources.get(source_id)


## Cancels every task posted by a work source (zone removed / mined out).
## exclude_task_id lets the finishing dwarf's own lease complete normally.
func cancel_source_tasks(source_id: int, exclude_task_id: int = -1) -> void:
	var to_cancel: Array[int] = []
	for id in _tasks:
		var task: Task = _tasks[id]
		if task.source_id == source_id and task.id != exclude_task_id:
			to_cancel.append(task.id)
	for id: int in to_cancel:
		cancel_task(id)


# ── Public API — dwarves ──────────────────────────────────────────────────────

func register_dwarf(agent: DwarfAgent) -> void:
	_agents[agent.dwarf_id] = agent
	_mark_idle(agent.dwarf_id)


func deregister_dwarf(dwarf_id: int) -> void:
	if _active.has(dwarf_id):
		release_dwarf_task(dwarf_id, Task.ReleaseReason.SOURCE_EMPTY, false)
	_agents.erase(dwarf_id)
	_idle_dwarves.erase(dwarf_id)


## A dwarf finished an interrupt behaviour and is available again.
func notify_dwarf_idle(dwarf_id: int) -> void:
	_mark_idle(dwarf_id)


## A dwarf entered an interrupt behaviour (sleep, combat) while holding NO
## task — it must leave the idle pool so the scheduler cannot assign to it
## until notify_dwarf_idle (doc 16 §2.8: a dwarf enters _idle_dwarves only
## after its interrupt behaviour resolves). Dwarves holding a task use
## release_dwarf_task(..., requeue_dwarf = false) instead.
func notify_dwarf_unavailable(dwarf_id: int) -> void:
	_idle_dwarves.erase(dwarf_id)


## Clears transient scheduling state before a scene reload. Configuration and
## signal connections remain intact because this autoload survives the reload.
func reset_runtime_state() -> void:
	_tasks.clear()
	_pending.clear()
	_active.clear()
	_idle_dwarves.clear()
	_agents.clear()
	_completed_log.clear()
	_scan_cursor.clear()
	_work_sources.clear()
	_next_task_id = 1
	_next_source_id = 10_000_000
	_blocked_count = 0
	_wake_dirty = false
	_heartbeat_accum = 0.0


# ── Stats (debug overlay, doc 16 Phase 0) ────────────────────────────────────

func get_scheduler_stats() -> Dictionary:
	var now := Time.get_ticks_msec()
	var pending_total := 0
	var blocked := 0
	var oldest_age_s := 0.0
	var by_type: Dictionary = {}
	for type in _pending:
		var ids: Array = _pending[type]
		by_type[Task.type_name(int(type))] = ids.size()
		pending_total += ids.size()
		for id in ids:
			var task: Task = _tasks.get(id)
			if task == null:
				continue
			if now < task.retry_at:
				blocked += 1
			var age := float(now - task.created_at) / 1000.0
			if age > oldest_age_s:
				oldest_age_s = age
	var dt := float(now - _stats_last_msec) / 1000.0
	var probes_rate := 0.0
	if _stats_last_msec > 0 and dt > 0.0:
		probes_rate = float(_probes_total - _probes_at_last_stats) / dt
	_stats_last_msec = now
	_probes_at_last_stats = _probes_total
	return {
		"pending_total": pending_total,
		"pending_by_type": by_type,
		"active": _active.size(),
		"blocked": blocked,
		"oldest_pending_age_s": oldest_age_s,
		"probes_per_sec": probes_rate,
		"worst_wake_usec": _worst_wake_usec,
		"wake_count": _wake_count,
	}


# ── The scheduler (doc 16 §2.4 / §2.5) ───────────────────────────────────────

func _run_scheduler() -> void:
	if _idle_dwarves.is_empty() or _tasks.is_empty():
		return
	var t_start := Time.get_ticks_usec()
	var probes_left := _max_probes_per_wake
	_wake_count += 1

	# Colony bonuses are computed ONCE per wake, per type (doc 16 §2.2) —
	# stubbed at 0 until stockpiles exist; the structure is the point.
	var bonus: Dictionary = {}
	for type in _pending:
		bonus[type] = _colony_bonus(int(type))

	# Iterate a snapshot of the idle pool; dwarves that get work are removed
	# from the live list inside _try_assign.
	var idle_snapshot := _idle_dwarves.duplicate()
	for dwarf_id in idle_snapshot:
		if Time.get_ticks_usec() - t_start >= _budget_usec or probes_left <= 0:
			_wake_dirty = true   # resume next frame from the cursors
			break
		var agent: DwarfAgent = _agents.get(dwarf_id)
		if agent == null or not is_instance_valid(agent):
			_idle_dwarves.erase(dwarf_id)
			_agents.erase(dwarf_id)
			continue
		probes_left = _try_assign(agent, bonus, probes_left, t_start)

	var wake_usec := int(Time.get_ticks_usec() - t_start)
	if wake_usec > _worst_wake_usec:
		_worst_wake_usec = wake_usec


## Scans this dwarf's compatible type buckets in bonus-adjusted priority order.
## Returns the remaining probe allowance.
func _try_assign(agent: DwarfAgent, bonus: Dictionary, probes_left: int, t_start: int) -> int:
	var types := _types_for(agent)
	types.sort_custom(func(a: int, b: int) -> bool:
		return _bucket_priority(a, bonus) > _bucket_priority(b, bonus))

	var now := Time.get_ticks_msec()
	var dwarf_cell := agent.current_cell()

	for type in types:
		var ids: Array = _pending.get(type, [])
		if ids.is_empty():
			continue
		var cursor := int(_scan_cursor.get(type, 0))
		var scanned := 0
		while scanned < ids.size():
			if Time.get_ticks_usec() - t_start >= _budget_usec or probes_left <= 0:
				_scan_cursor[type] = cursor
				return 0
			var idx := (cursor + scanned) % ids.size()
			scanned += 1
			var task: Task = _tasks.get(ids[idx])
			if task == null or not task.is_available(now):
				continue
			probes_left -= 1
			_probes_total += 1
			# Dwarf-relative probe target for source leases (Alen, 2026-06-26): the
			# lease's static target_pos is one representative cell that can be
			# unreachable even when this dwarf could work elsewhere in the source.
			# Probe the workable stand cell nearest THIS dwarf instead. Generalised
			# from MINE-only to any work source (doc 18 Phase 3 — stockpile HAUL
			# leases use the same hook); has_method guards sources without it.
			var probe_target := task.target_pos
			if task.source_id != -1:
				var src: Object = _work_sources.get(task.source_id)
				if src != null and src.has_method("nearest_stand_target"):
					var t: Vector3i = src.nearest_stand_target(dwarf_cell)
					if t.x >= 0:
						probe_target = t
			if NavGrid.probe_reachable(dwarf_cell, probe_target, _probe_node_cap):
				task.blocked_count = 0
				_assign(task, agent)
				_scan_cursor[type] = (cursor + scanned) % maxi(ids.size(), 1)
				return probes_left
			_apply_backoff(task, now)
		_scan_cursor[type] = 0
	return probes_left


func _assign(task: Task, agent: DwarfAgent) -> void:
	_remove_pending(task)
	task.status = Task.Status.ASSIGNED
	task.assigned_to = agent.dwarf_id
	_active[agent.dwarf_id] = task.id
	_idle_dwarves.erase(agent.dwarf_id)
	agent.receive_task(task.id, task.target_pos)
	task_assigned.emit(task, agent.dwarf_id)


func _apply_backoff(task: Task, now: int) -> void:
	task.blocked_count += 1
	var delay_s: float = minf(pow(_backoff_base_s, float(task.blocked_count)), _backoff_max_s)
	task.retry_at = now + int(delay_s * 1000.0)
	_blocked_count += 1
	if task.blocked_count == _unreachable_threshold:
		task_unreachable.emit(task)


## Compatible task types for a dwarf. v1: every dwarf takes any economic type
## (doc 31: off-profession work runs at x0.7 speed — applied at execution in
## step 6). Profession-gated types (FORGE etc., doc 44) refine this later.
func _types_for(_agent: DwarfAgent) -> Array[int]:
	return [Task.Type.MINE, Task.Type.HAUL, Task.Type.BUILD, Task.Type.FARM,
			Task.Type.BREW, Task.Type.FETCH_BUILD, Task.Type.UNINSTALL]


func _bucket_priority(type: int, bonus: Dictionary) -> int:
	return int(_static_priorities.get(Task.type_name(type), 1)) + int(bonus.get(type, 0))


## Colony-state priority bonuses (doc 31: +20 BREW when ale < 10, ...).
## Stub until stockpiles exist.
func _colony_bonus(_type: int) -> int:
	return 0


# ── Pending bucket maintenance (sorted by static priority desc) ──────────────

func _insert_pending(task: Task) -> void:
	if not _pending.has(task.type):
		_pending[task.type] = []
	var ids: Array = _pending[task.type]
	var lo := 0
	var hi := ids.size()
	while lo < hi:
		@warning_ignore("integer_division")
		var mid := (lo + hi) / 2
		var other: Task = _tasks.get(ids[mid])
		if other != null and other.priority >= task.priority:
			lo = mid + 1
		else:
			hi = mid
	ids.insert(lo, task.id)


func _remove_pending(task: Task) -> void:
	var ids: Array = _pending.get(task.type, [])
	ids.erase(task.id)
	if Time.get_ticks_msec() < task.retry_at:
		_blocked_count = maxi(0, _blocked_count - 1)


func _take_active(dwarf_id: int) -> Task:
	if not _active.has(dwarf_id):
		return null
	var task: Task = _tasks.get(_active[dwarf_id])
	_active.erase(dwarf_id)
	return task


func _mark_idle(dwarf_id: int) -> void:
	if not _agents.has(dwarf_id):
		return
	if not _idle_dwarves.has(dwarf_id):
		_idle_dwarves.append(dwarf_id)
	_wake_dirty = true


func _log_completed(task: Task) -> void:
	_completed_log.append({
		"id": task.id, "type": Task.type_name(task.type),
		"target": task.target_pos, "at_msec": Time.get_ticks_msec(),
	})
	if _completed_log.size() > 200:
		_completed_log.pop_front()


## Registry-pattern accessor: TaskManager is the ONE owner of task_config.json;
## other task-adjacent systems (StockpileManager's hauling block, doc 18) read
## their sections through here rather than opening the file.
func get_config_section(section: String) -> Dictionary:
	return _config_raw.get(section, {})


# ── Early re-arm: terrain changed near a blocked target (doc 16 §2.4) ────────

func _on_chunk_dirtied(cx: int, cy: int, cz: int) -> void:
	if _blocked_count <= 0:
		return   # fast gate — streaming fires this constantly during worldgen
	var now := Time.get_ticks_msec()
	var re_armed := 0
	for type in _pending:
		var ids: Array = _pending[type]
		for id in ids:
			var task: Task = _tasks.get(id)
			if task == null or now >= task.retry_at:
				continue
			if task.target_pos.x >> 4 == cx and task.target_pos.y >> 4 == cy \
					and task.target_pos.z >> 4 == cz:
				task.retry_at = now
				re_armed += 1
	if re_armed > 0:
		_blocked_count = maxi(0, _blocked_count - re_armed)
		_wake_dirty = true


# ── Config loader ─────────────────────────────────────────────────────────────

func _load_config() -> void:
	var file := FileAccess.open(CONFIG_PATH, FileAccess.READ)
	if file == null:
		push_warning("TaskManager: cannot open %s — using built-in defaults." % CONFIG_PATH)
		return
	var json := JSON.new()
	if json.parse(file.get_as_text()) != OK:
		push_error("TaskManager: JSON parse error in %s — %s" % [CONFIG_PATH, json.get_error_message()])
		file.close()
		return
	file.close()
	var d: Dictionary = json.data
	_config_raw = d
	var s: Dictionary = d.get("scheduler", {})
	_budget_usec = int(s.get("scheduler_budget_usec", _budget_usec))
	_max_probes_per_wake = int(s.get("max_probes_per_wake", _max_probes_per_wake))
	_probe_node_cap = int(s.get("probe_node_cap", _probe_node_cap))
	_heartbeat_s = float(s.get("heartbeat_interval_s", _heartbeat_s))
	_backoff_base_s = float(s.get("backoff_base_s", _backoff_base_s))
	_backoff_max_s = float(s.get("backoff_max_s", _backoff_max_s))
	_unreachable_threshold = int(s.get("unreachable_signal_threshold", _unreachable_threshold))
	_static_priorities = d.get("static_priorities", {})

source_text.scripts/systems/WeatherManager.gd:
extends Node

## Per-season weather scheduler. Picks a weather type each in-game day from the weighted table in
## data/calendar/weather_schedule.json, and hands the chosen weather to SkyController, which blends
## its sky overrides (fog density/distance), darkening, and vision multiplier into the day/night look.
##
## Registered as an autoload (project.godot [autoload]), loaded AFTER SkyController so it can call it.
## Mirrors Stonehearth's weather_service: plan-by-season, switch on a daily cadence, support a manual
## override. Draws use a seeded RNG (from the world seed) so a given world replays the same weather.
##
## JSON = what things are (weather defs + the weighted schedule); GDScript = what things do (picking,
## scheduling, applying).

const SCHEDULE_PATH := "res://data/calendar/weather_schedule.json"
const WEATHER_FILES := [
	"res://data/weather/clear.json",
	"res://data/weather/foggy.json",
	"res://data/weather/overcast.json",
	"res://data/weather/snow.json",
]

var _weather_by_id: Dictionary = {}   # id -> weather definition dict
var _ordered_ids: Array[String] = []  # load order, for the manual cycle button
var _schedule: Dictionary = {}        # season -> Array of { weather, weight }
var _rng := RandomNumberGenerator.new()

var _clock: Node = null
var _sky: Node = null
var _current_id: String = ""

@warning_ignore("unused_signal")  # connected by UI / future systems
signal weather_changed(weather_id: String)


func _ready() -> void:
	_load_weather_defs()
	_load_schedule()
	_clock = get_node_or_null("/root/WorldClock")
	_sky = get_node_or_null("/root/SkyController")
	# Wait one frame so SkyController has bound to the scene, then set initial weather.
	await get_tree().process_frame
	# Seed AFTER the await: WorldGenerator.world_seed is 0 during autoload
	# _ready and only gets set when WorldRenderer._ready (scene node, runs
	# after all autoloads but before the first process frame) calls
	# WorldGenerator.generate(). Seeding before the await always found 0 and
	# silently fell back to randomize(), breaking the same-seed-same-weather
	# contract documented in the header.
	_seed_rng()
	if _clock != null:
		if not _clock.is_connected("day_changed", _on_day_changed):
			_clock.connect("day_changed", _on_day_changed)
	_switch_weather_for_current_season()
	print("WeatherManager: ready (%d weather types, current = %s)." % [_ordered_ids.size(), _current_id])


# ── Loaders ───────────────────────────────────────────────────────────────────

func _load_weather_defs() -> void:
	for path in WEATHER_FILES:
		var d := _load_json(path)
		if d.is_empty():
			continue
		var id := String(d.get("id", ""))
		if id == "":
			push_warning("WeatherManager: %s has no 'id' — skipped." % path)
			continue
		_weather_by_id[id] = d
		_ordered_ids.append(id)


func _load_schedule() -> void:
	var d := _load_json(SCHEDULE_PATH)
	for season in d:
		if String(season).begins_with("__"):
			continue
		if d[season] is Array:
			_schedule[season] = d[season]


func _load_json(path: String) -> Dictionary:
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		push_warning("WeatherManager: cannot open %s." % path)
		return {}
	var json := JSON.new()
	var err := json.parse(file.get_as_text())
	file.close()
	if err != OK:
		push_error("WeatherManager: JSON parse error in %s — %s" % [path, json.get_error_message()])
		return {}
	if json.data is Dictionary:
		return json.data
	return {}


func _seed_rng() -> void:
	var seed_val := 0
	var wg := get_node_or_null("/root/WorldGenerator")
	if wg != null:
		seed_val = int(wg.get("world_seed"))
	if seed_val == 0:
		# Should not happen in the normal boot path (see _ready ordering note);
		# warn loudly so a silent determinism break can't sneak back in.
		push_warning("WeatherManager: world_seed unavailable — weather RNG randomized (non-deterministic).")
		_rng.randomize()
	else:
		_rng.seed = seed_val


# ── Scheduling ────────────────────────────────────────────────────────────────

func _on_day_changed(_new_day: int) -> void:
	_switch_weather_for_current_season()


func _switch_weather_for_current_season() -> void:
	var season := "summer"
	if _clock != null:
		season = String(_clock.get("season"))
	var id := _weather_for_season(season)
	if id != "":
		_apply(id)


func _weather_for_season(season: String) -> String:
	var entries = _schedule.get(season, [])
	if not (entries is Array) or (entries as Array).is_empty():
		return _ordered_ids[0] if not _ordered_ids.is_empty() else ""
	var total := 0.0
	for e in entries:
		total += float(e.get("weight", 0.0))
	if total <= 0.0:
		return _ordered_ids[0] if not _ordered_ids.is_empty() else ""
	var r := _rng.randf() * total
	var acc := 0.0
	for e in entries:
		acc += float(e.get("weight", 0.0))
		if r <= acc:
			return String(e.get("weather", ""))
	return String((entries as Array).back().get("weather", ""))


# ── Apply ─────────────────────────────────────────────────────────────────────

func _apply(id: String) -> void:
	if not _weather_by_id.has(id):
		push_warning("WeatherManager: unknown weather id '%s'." % id)
		return
	_current_id = id
	if _sky != null and _sky.has_method("apply_weather"):
		_sky.call("apply_weather", _weather_by_id[id])
	weather_changed.emit(id)


# ── Public API ────────────────────────────────────────────────────────────────

## Force a specific weather id (used for testing / scripted events).
func set_weather(id: String) -> void:
	_apply(id)


## Advance to the next weather type in load order — wired to the Clock window's test button.
func cycle_weather() -> void:
	if _ordered_ids.is_empty():
		return
	var idx := _ordered_ids.find(_current_id)
	idx = (idx + 1) % _ordered_ids.size()
	_apply(_ordered_ids[idx])


func current_weather_id() -> String:
	return _current_id


func serialize_state() -> Dictionary:
	return {
		"current_id": _current_id,
		"rng_state": _rng.state,
	}


func restore_state(state: Dictionary) -> void:
	var id := String(state.get("current_id", ""))
	if _weather_by_id.has(id):
		_apply(id)
	if state.has("rng_state"):
		_rng.state = int(state["rng_state"])


func current_weather_name() -> String:
	if _weather_by_id.has(_current_id):
		return String(_weather_by_id[_current_id].get("display_name", _current_id))
	return "—"

source_text.scripts/tests/SaveManagerRoundTripTest.g:
extends SceneTree

## Headless integration regression for validated save replacement and backup
## recovery. Run from the project root:
##
## godot --headless --path . --script res://scripts/tests/SaveManagerRoundTripTest.gd

const TEST_DIRECTORY := "user://save_manager_round_trip_test"
const TEST_PRIMARY := TEST_DIRECTORY + "/quicksave.json"
const TEST_BACKUP := TEST_DIRECTORY + "/quicksave.backup.json"
const TEST_TEMP := TEST_DIRECTORY + "/quicksave.tmp.json"
const TEST_BACKUP_STAGE := TEST_DIRECTORY + "/quicksave.backup.tmp.json"
const TEST_AUTOSAVE := TEST_DIRECTORY + "/autosave.json"
const TEST_AUTOSAVE_BACKUP := TEST_DIRECTORY + "/autosave.backup.json"
const TEST_AUTOSAVE_TEMP := TEST_DIRECTORY + "/autosave.tmp.json"
const TEST_AUTOSAVE_BACKUP_STAGE := TEST_DIRECTORY + "/autosave.backup.tmp.json"
const WORLD_TIMEOUT_MSEC := 90000
const LOAD_TIMEOUT_MSEC := 90000
const OWNER_GROUP := "save_state_owner"

var _load_completed := false
var _load_succeeded := false
var _load_used_backup := false
var _save_manager: Node = null
var _world_generator: Node = null
var _world_clock: Node = null
## Full scene-owner snapshot captured right after the colony state is built.
## Every load is deep-diffed against it (content equality, not section sizes —
## a chest losing its inventory or a ghost losing its yaw used to pass).
var _content_reference: Dictionary = {}


func _init() -> void:
	call_deferred("_run")


func _run() -> void:
	_save_manager = root.get_node_or_null("SaveManager")
	_world_generator = root.get_node_or_null("WorldGenerator")
	_world_clock = root.get_node_or_null("WorldClock")
	if _save_manager == null or _world_generator == null or _world_clock == null:
		_fail("required autoloads are unavailable")
		return
	_cleanup_test_storage()
	if not bool(_save_manager.call("configure_storage_for_testing", TEST_DIRECTORY)):
		_fail("could not isolate test storage")
		return

	var scene_error := change_scene_to_file("res://scenes/main/debug_world.tscn")
	if scene_error != OK:
		_fail("could not load debug_world.tscn (%s)" % error_string(scene_error))
		return
	await process_frame
	await process_frame
	if not await _wait_for_world_ready(WORLD_TIMEOUT_MSEC):
		_fail("world generation timed out")
		return

	var expected_seed := int(_world_generator.get("world_seed"))
	var setup_error := _build_nonempty_colony_state()
	if not setup_error.is_empty():
		_fail(setup_error)
		return
	_content_reference = _collect_scene_state()

	# Advancing the timer by one interval must write only the independent
	# autosave slot and must not mutate authoritative scene state.
	var scene_before_autosave := JSON.stringify(_collect_scene_state())
	_save_manager.call("_tick_autosave", 300.0)
	if not FileAccess.file_exists(TEST_AUTOSAVE):
		_fail("five-minute timer did not create an autosave")
		return
	if FileAccess.file_exists(TEST_PRIMARY):
		_fail("autosave overwrote or created the manual quick-save slot")
		return
	var autosave_result: Dictionary = _save_manager.call("_read_snapshot", TEST_AUTOSAVE)
	if not bool(autosave_result.get("ok", false)):
		_fail("autosave did not validate")
		return
	_save_manager.call("_tick_autosave", 300.0)
	if not FileAccess.file_exists(TEST_AUTOSAVE_BACKUP):
		_fail("second autosave did not rotate the previous autosave to backup")
		return
	if scene_before_autosave != JSON.stringify(_collect_scene_state()):
		_fail("autosaving mutated authoritative scene state")
		return

	var scene_before := JSON.stringify(_collect_scene_state())
	if not bool(_save_manager.call("request_save")):
		_fail("first validated save failed")
		return
	var scene_after := JSON.stringify(_collect_scene_state())
	if scene_before != scene_after:
		_fail("saving mutated authoritative scene state")
		return

	# The second save must rotate the first valid snapshot to the backup.
	_world_clock.call("restore_state", {
		"day": 9,
		"season": "winter",
		"year": 4,
		"hour": 18.5,
		"speed": 3.0,
		"paused": true,
	})
	if not bool(_save_manager.call("request_save")):
		_fail("second save/backup rotation failed")
		return
	if not FileAccess.file_exists(TEST_BACKUP):
		_fail("validated backup was not created")
		return

	# The autosave must be independently loadable and must not use the manual
	# primary or backup created above.
	_load_completed = false
	_load_succeeded = false
	_load_used_backup = false
	_save_manager.connect("load_finished", _on_load_finished, CONNECT_ONE_SHOT)
	if not bool(_save_manager.call("request_load_autosave")):
		_fail("autosave load did not start")
		return
	if not await _wait_for_load(LOAD_TIMEOUT_MSEC):
		_fail("autosave load timed out")
		return
	if not _load_succeeded or _load_used_backup:
		_fail("autosave did not load from its independent primary slot")
		return
	var autosave_verification_error := _verify_restored_state(expected_seed)
	if not autosave_verification_error.is_empty():
		_fail("autosave: %s" % autosave_verification_error)
		return
	var autosave_content_diff := _deep_diff(_content_reference, _collect_scene_state(), "scene")
	if not autosave_content_diff.is_empty():
		_fail("autosave content did not round-trip — %s" % autosave_content_diff)
		return

	# Fault injection stays inside SaveManager, the sole save-file I/O owner.
	var corrupt_error := String(_save_manager.call("_write_text_file", TEST_PRIMARY, "{invalid json"))
	if not corrupt_error.is_empty():
		_fail("could not inject a corrupt primary: %s" % corrupt_error)
		return

	_load_completed = false
	_load_succeeded = false
	_load_used_backup = false
	_save_manager.connect("load_finished", _on_load_finished, CONNECT_ONE_SHOT)
	if not bool(_save_manager.call("request_load")):
		_fail("backup load did not start")
		return
	if not await _wait_for_load(LOAD_TIMEOUT_MSEC):
		_fail("backup load timed out")
		return
	if not _load_succeeded or not _load_used_backup:
		_fail("load did not complete through the backup path")
		return

	var verification_error := _verify_restored_state(expected_seed)
	if not verification_error.is_empty():
		_fail(verification_error)
		return
	var backup_content_diff := _deep_diff(_content_reference, _collect_scene_state(), "scene")
	if not backup_content_diff.is_empty():
		_fail("backup-load content did not round-trip — %s" % backup_content_diff)
		return

	var repaired_primary: Dictionary = _save_manager.call("_read_snapshot", TEST_PRIMARY)
	if not bool(repaired_primary.get("ok", false)):
		_fail("backup load did not repair the primary slot")
		return

	var inflight_error := _run_inflight_carried_case()
	if not inflight_error.is_empty():
		_fail(inflight_error)
		return

	print("SAVE_MANAGER_ROUND_TRIP_OK")
	_cleanup_and_quit(0)


func _build_nonempty_colony_state() -> String:
	var mining := _owner("mining")
	var flag := _owner("settlement_flag")
	var stockpiles := _owner("stockpiles")
	var furniture := _owner("furniture")
	var items := _owner("items")
	var dwarves := _owner("dwarves")
	var camera := _owner("camera")
	var slice := _owner("slice")
	if [mining, flag, stockpiles, furniture, items, dwarves, camera, slice].has(null):
		return "one or more save-state owners are missing"

	var flag_cell := _surface_cell(0, 0)
	var dwarf_cell := _surface_cell(2, 0)
	var stockpile_cell := _surface_cell(4, 0)
	var furniture_cell := _surface_cell(6, 0)
	var ghost_cell := _surface_cell(8, 0)
	var item_cell := _surface_cell(10, 0)
	var mined_cell := _surface_cell(12, 0)
	var designated_cell := _surface_cell(14, 0)

	mining.call("restore_state", {
		"mined_blocks": [_pack_v3i(mined_cell)],
		"zones": [{ "id": 101, "blocks": [_pack_v3i(designated_cell)] }],
	})
	flag.call("restore_state", {
		"placed": true,
		"cell": _pack_v3i(flag_cell),
	})
	stockpiles.call("restore_state", {
		"zones": [{
			"id": 201,
			"cells": [_pack_v3i(stockpile_cell)],
			"filter_tags": ["stockpile_stone"],
			"stacks": [{
				"cell": _pack_v3i(stockpile_cell),
				"item": "base:resources:stone:rough_stone",
				"count": 2,
			}],
		}],
	})
	furniture.call("restore_state", {
		"ghosts": [{
			"id": 301,
			"key": "base:furniture:storage_shelf",
			"origin": _pack_v3i(ghost_cell),
			"yaw": 1,
		}],
		"installed": [{
			"id": 401,
			"key": "base:furniture:barrel",
			"origin": _pack_v3i(furniture_cell),
			"yaw": 0,
			"flagged_uninstall": false,
			"inventory": { "base:resources:stone:rough_stone": 2 },
		}],
	})
	items.call("restore_state", {
		"loose": [{
			"item_key": "base:resources:stone:rough_stone",
			"position": _pack_v3(Vector3(
				float(item_cell.x) + 0.5, float(item_cell.y) + 1.05, float(item_cell.z) + 0.5)),
			"rotation_y": 0.25,
		}],
	})
	dwarves.call("restore_state", {
		"birth_index": 1,
		"settlement_anchor": _pack_v3i(flag_cell),
		"roster": [{
			"id": 0,
			"name": "Testur",
			"gender": "male",
			"appearance": {
				"gender": "male",
				"age_tier": "adult",
				"skin_tone": "medium",
				"eye_color": "grey",
				"hair_color": "brown",
				"hair_style": "short_back",
				"eyebrow_style": "thick_flat",
				"beard_style": "",
				"scar": "none",
			},
			"traits": [],
			"profession": "base:profession:worker",
			"profession_experience": { "base:profession:worker": 7 },
			"position": _pack_v3(Vector3(
				float(dwarf_cell.x) + 0.5, float(dwarf_cell.y) + 1.0, float(dwarf_cell.z) + 0.5)),
			"rotation_y": 0.5,
			"sleep": 0.4,
			"sleeping": true,
			"sleep_hours_left": 2.5,
			"carried_items": [],
		}],
	})
	camera.call("restore_state", {
		"target_position": _pack_v3(Vector3(520.0, 64.0, 500.0)),
		"zoom": 42.0,
		"pitch": -55.0,
		"orbit_y": 25.0,
	})
	slice.call("restore_state", {
		"active": true,
		"seeded": true,
		"slice_y": 25,
		"last_slice_y": 25,
	})
	_world_clock.call("restore_state", {
		"day": 7,
		"season": "autumn",
		"year": 3,
		"hour": 6.25,
		"speed": 2.0,
		"paused": true,
	})
	return ""


func _verify_restored_state(expected_seed: int) -> String:
	if int(_world_generator.get("world_seed")) != expected_seed:
		return "world seed did not round-trip"
	if int(_world_clock.get("day")) != 7 \
			or String(_world_clock.get("season")) != "autumn" \
			or int(_world_clock.get("year")) != 3:
		return "calendar did not restore from the saved snapshot"
	if not is_equal_approx(float(_world_clock.get("hour")), 6.25) \
			or not is_equal_approx(float(_world_clock.get("speed")), 2.0):
		return "clock hour/speed did not restore from the backup snapshot"
	if not bool(_world_clock.get("paused")):
		return "clock paused state did not round-trip"

	var scene_state := _collect_scene_state()
	var expected_keys := [
		"mining", "settlement_flag", "stockpiles", "furniture",
		"items", "dwarves", "camera", "slice",
	]
	for key in expected_keys:
		if not scene_state.has(key):
			return "restored scene is missing section %s" % key
	if (scene_state["mining"] as Dictionary).get("mined_blocks", []).size() != 1:
		return "mined blocks did not round-trip"
	if (scene_state["mining"] as Dictionary).get("zones", []).size() != 1:
		return "mining zones did not round-trip"
	if not bool((scene_state["settlement_flag"] as Dictionary).get("placed", false)):
		return "settlement flag did not round-trip"
	if (scene_state["stockpiles"] as Dictionary).get("zones", []).size() != 1:
		return "stockpile state did not round-trip"
	var furniture_state := scene_state["furniture"] as Dictionary
	if furniture_state.get("ghosts", []).size() != 1 or furniture_state.get("installed", []).size() != 1:
		return "furniture state did not round-trip"
	if (scene_state["items"] as Dictionary).get("loose", []).size() != 1:
		return "loose items did not round-trip"
	var roster: Array = (scene_state["dwarves"] as Dictionary).get("roster", [])
	if roster.size() != 1 or not bool((roster[0] as Dictionary).get("sleeping", false)):
		return "dwarf roster/runtime state did not round-trip"
	var camera_state := scene_state["camera"] as Dictionary
	if not is_equal_approx(float(camera_state.get("zoom", 0.0)), 42.0):
		return "camera state did not round-trip"
	var slice_state := scene_state["slice"] as Dictionary
	if not bool(slice_state.get("active", false)) or int(slice_state.get("slice_y", -1)) != 25:
		return "slice state did not round-trip"
	return ""


func _collect_scene_state() -> Dictionary:
	var result: Dictionary = {}
	for state_owner in get_nodes_in_group(OWNER_GROUP):
		if state_owner.has_method("save_section_key") and state_owner.has_method("serialize_state"):
			result[String(state_owner.call("save_section_key"))] = state_owner.call("serialize_state")
	return result


## Recursive content-equality diff. Floats compare with a small tolerance —
## JSON round-trips numbers through text and node transforms through 32-bit
## Vector3 components, so exact bit equality is not the contract. Returns ""
## when equal, otherwise a "path: detail" description of the FIRST difference,
## so a regression names the exact field it ate (e.g. a container inventory
## clamped on load, a ghost yaw reset, a stack count collapsing to 1).
func _deep_diff(expected: Variant, actual: Variant, path: String) -> String:
	if expected is Dictionary and actual is Dictionary:
		var exp_dict := expected as Dictionary
		var act_dict := actual as Dictionary
		for key in exp_dict:
			if not act_dict.has(key):
				return "%s: missing key '%s'" % [path, str(key)]
			var child := _deep_diff(exp_dict[key], act_dict[key], "%s.%s" % [path, str(key)])
			if not child.is_empty():
				return child
		for key in act_dict:
			if not exp_dict.has(key):
				return "%s: unexpected key '%s'" % [path, str(key)]
		return ""
	if expected is Array and actual is Array:
		var exp_arr := expected as Array
		var act_arr := actual as Array
		if exp_arr.size() != act_arr.size():
			return "%s: array size %d != %d" % [path, exp_arr.size(), act_arr.size()]
		for i in range(exp_arr.size()):
			var child := _deep_diff(exp_arr[i], act_arr[i], "%s[%d]" % [path, i])
			if not child.is_empty():
				return child
		return ""
	if (expected is float or expected is int) and (actual is float or actual is int):
		if absf(float(expected) - float(actual)) > 0.002:
			return "%s: %s != %s" % [path, str(expected), str(actual)]
		return ""
	if typeof(expected) != typeof(actual) or expected != actual:
		return "%s: %s != %s" % [path, str(expected), str(actual)]
	return ""


## In-flight case: a save written mid-haul stores carried item KEYS on the
## dwarf (DwarfAgent.serialize_state). The load contract is Hard Rule 12
## shaped: carried items are re-dropped as loose at the dwarf's feet — never
## destroyed, never left on the freed agent. restore_state is invoked here
## exactly as SaveManager invokes it for the dwarves section, so this is the
## same code path a real load takes.
func _run_inflight_carried_case() -> String:
	var dwarves := _owner("dwarves")
	var items := _owner("items")
	if dwarves == null or items == null:
		return "in-flight case: save-state owners missing after reload"
	var loose_before := ((items.call("serialize_state") as Dictionary).get("loose", []) as Array).size()
	var carrier_cell := _surface_cell(16, 0)
	dwarves.call("restore_state", {
		"birth_index": 5,
		"settlement_anchor": _pack_v3i(_surface_cell(0, 0)),
		"roster": [{
			"id": 4,
			"name": "Carrier",
			"gender": "male",
			"appearance": {
				"gender": "male",
				"age_tier": "adult",
				"skin_tone": "medium",
				"eye_color": "grey",
				"hair_color": "brown",
				"hair_style": "short_back",
				"eyebrow_style": "thick_flat",
				"beard_style": "",
				"scar": "none",
			},
			"traits": [],
			"profession": "base:profession:worker",
			"profession_experience": {},
			"position": _pack_v3(Vector3(
				float(carrier_cell.x) + 0.5, float(carrier_cell.y) + 1.0, float(carrier_cell.z) + 0.5)),
			"rotation_y": 0.0,
			"sleep": 0.9,
			"sleeping": true,
			"sleep_hours_left": 5.0,
			"carried_items": [
				"base:resources:stone:rough_stone",
				"base:resources:stone:rough_stone",
			],
		}],
	})
	var loose_after := ((items.call("serialize_state") as Dictionary).get("loose", []) as Array).size()
	if loose_after != loose_before + 2:
		return "in-flight case: carried items not conserved as loose drops (loose %d -> %d, expected +2)" \
			% [loose_before, loose_after]
	var roster: Array = (dwarves.call("serialize_state") as Dictionary).get("roster", [])
	for raw in roster:
		if not (raw is Dictionary):
			continue
		var entry := raw as Dictionary
		if int(entry.get("id", -1)) == 4:
			if not ((entry.get("carried_items", []) as Array).is_empty()):
				return "in-flight case: restored dwarf still reports carried items"
			return ""
	return "in-flight case: carrier dwarf missing from the roster after restore"


func _owner(section_key: String) -> Node:
	for state_owner in get_nodes_in_group(OWNER_GROUP):
		if state_owner.has_method("save_section_key") \
				and String(state_owner.call("save_section_key")) == section_key:
			return state_owner
	return null


func _surface_cell(offset_x: int, offset_z: int) -> Vector3i:
	var x := 512 + offset_x
	var z := 491 + offset_z
	return Vector3i(x, int(_world_generator.call("get_surface_y", x, z)), z)


func _wait_for_world_ready(timeout_msec: int) -> bool:
	var deadline := Time.get_ticks_msec() + timeout_msec
	while Time.get_ticks_msec() < deadline:
		var stats: Dictionary = _world_generator.call("get_streaming_stats")
		if bool(stats.get("maps_ready", false)) and not bool(_world_generator.call("is_generating")):
			return true
		await process_frame
	return false


func _wait_for_load(timeout_msec: int) -> bool:
	var deadline := Time.get_ticks_msec() + timeout_msec
	while not _load_completed and Time.get_ticks_msec() < deadline:
		await process_frame
	return _load_completed


func _on_load_finished(success: bool, used_backup: bool) -> void:
	_load_succeeded = success
	_load_used_backup = used_backup
	_load_completed = true


func _fail(message: String) -> void:
	push_error("SAVE_MANAGER_ROUND_TRIP_FAIL: %s" % message)
	_cleanup_and_quit(1)


func _cleanup_and_quit(exit_code: int) -> void:
	if _save_manager != null:
		_save_manager.call("reset_storage_after_testing")
	_cleanup_test_storage()
	quit(exit_code)


func _pack_v3i(value: Vector3i) -> Array:
	return [value.x, value.y, value.z]


func _pack_v3(value: Vector3) -> Array:
	return [value.x, value.y, value.z]


func _cleanup_test_storage() -> void:
	for path in [
		TEST_PRIMARY, TEST_BACKUP, TEST_TEMP, TEST_BACKUP_STAGE,
		TEST_AUTOSAVE, TEST_AUTOSAVE_BACKUP, TEST_AUTOSAVE_TEMP,
		TEST_AUTOSAVE_BACKUP_STAGE,
	]:
		if FileAccess.file_exists(path):
			DirAccess.remove_absolute(ProjectSettings.globalize_path(path))
	var absolute_directory := ProjectSettings.globalize_path(TEST_DIRECTORY)
	if DirAccess.dir_exists_absolute(absolute_directory):
		# The fixed test directory is removed only when the exact files above left it empty.
		DirAccess.remove_absolute(absolute_directory)

source_text.scripts/ui/UIWindowManager.gd:
class_name UIWindowManager
extends CanvasLayer

## One CanvasLayer hosting every UIWindow (doc 24, Phase U1).
##
## Owns everything that is chrome-and-behaviour rather than content: z-order
## (last-clicked wins), placement (remembered position → default → cascade),
## open/close/toggle bookkeeping, and layout persistence. Content stays with
## the registering system (Scene Decoupling Contract) — controllers build a
## plain Control, register it, and keep their reference to update labels.
##
## Layer plan (doc 24 §3): dock 20, ALL windows here at 22, mouse-ignoring
## HUD callouts 24.
##
## Persistence: `user://ui_layout.json`, this class is the SINGLE owner of that
## file (Registry-Pattern discipline applied to user data — no other script may
## read or write it). Window layout is a player preference, so it lives outside
## the save file and survives every save/load/new game (Alen, 2026-08-20).
##
## New `class_name` — after pulling this change, run Project → Reload Current
## Project once.

## Emitted whenever any window opens or closes. DockUI's pressed-state refresh
## hangs off this one signal — the per-window special cases are gone.
signal window_state_changed(id: String, open: bool)

const LAYOUT_PATH := "user://ui_layout.json"
const LAYOUT_SCHEMA_VERSION := 1

## First-open placement when no remembered or default position exists —
## the classic DockUI cascade, kept.
const CASCADE_START := Vector2(32.0, 130.0)
const CASCADE_STEP := Vector2(28.0, 28.0)
const CASCADE_WRAP := 5

var _windows: Dictionary = {}   # id: String -> UIWindow
var _layout: Dictionary = {}    # id: String -> { "x": float, "y": float, "open": bool }
var _cascade_index: int = 0
var _layout_loaded: bool = false


func _enter_tree() -> void:
	layer = 22


func _ready() -> void:
	_load_layout()
	get_viewport().size_changed.connect(_on_viewport_resized)
	print("UIWindowManager: ready (%d remembered window positions)." % _layout.size())


# ── Registration ──────────────────────────────────────────────────────────────

## Registers a window and returns it (owners keep the reference for title and
## content updates). The window starts hidden; a persistent window whose
## remembered state is open reopens on the next idle frame.
##
## opts:
##   "persistent":  bool     — restorable open state at startup (default false)
##   "default_pos": Vector2  — first-ever position (else cascade)
##   "min_size":    Vector2  — content minimum size
func register_window(id: String, title: String, emoji: String,
		content: Control, opts: Dictionary = {}) -> UIWindow:
	if _windows.has(id):
		push_warning("UIWindowManager: '%s' registered twice — keeping the first." % id)
		return _windows[id] as UIWindow

	var window := UIWindow.new()
	window.window_id = id
	window.persistent = bool(opts.get("persistent", false))
	window.set_window_title(title, emoji)
	window.visible = false
	if opts.has("min_size"):
		window.custom_minimum_size = opts.get("min_size", Vector2.ZERO)
	add_child(window)
	window.set_content(content)
	_windows[id] = window

	window.position = _initial_position_for(id, opts)
	window.focus_requested.connect(_on_focus_requested)
	window.close_pressed.connect(_on_close_pressed)
	window.drag_ended.connect(_on_drag_ended)

	if window.persistent and _remembered_open(id):
		# Deferred: let the owner finish its own _ready before content shows.
		call_deferred("open", id)
	return window


func has_window(id: String) -> bool:
	return _windows.has(id)


## NOT get_window(): that name is Node's native get_window() -> Window, and
## overriding a native method is a warning-treated-as-error in this project.
func get_ui_window(id: String) -> UIWindow:
	return _windows.get(id, null) as UIWindow


# ── Open / close / toggle ─────────────────────────────────────────────────────

func is_open(id: String) -> bool:
	var window := get_ui_window(id)
	return window != null and window.visible


func open(id: String) -> void:
	var window := get_ui_window(id)
	if window == null:
		push_warning("UIWindowManager: open('%s') — no such window registered." % id)
		return
	if window.visible:
		_raise(window)
		return
	window.visible = true
	window.clamp_to_viewport()
	_raise(window)
	_record_state(id)
	window_state_changed.emit(id, true)


func close(id: String) -> void:
	var window := get_ui_window(id)
	if window == null or not window.visible:
		return
	window.visible = false
	_record_state(id)
	window_state_changed.emit(id, false)


func toggle(id: String) -> void:
	if is_open(id):
		close(id)
	else:
		open(id)


# ── Window signal handlers ────────────────────────────────────────────────────

func _on_focus_requested(window: UIWindow) -> void:
	_raise(window)


func _on_close_pressed(window: UIWindow) -> void:
	close(window.window_id)


func _on_drag_ended(window: UIWindow) -> void:
	_record_state(window.window_id)


func _raise(window: UIWindow) -> void:
	move_child(window, get_child_count() - 1)


func _on_viewport_resized() -> void:
	for id: String in _windows:
		var window := _windows[id] as UIWindow
		if window.visible:
			window.clamp_to_viewport()


# ── Placement ─────────────────────────────────────────────────────────────────

func _initial_position_for(id: String, opts: Dictionary) -> Vector2:
	var entry: Dictionary = _layout.get(id, {})
	if entry.has("x") and entry.has("y"):
		return Vector2(float(entry["x"]), float(entry["y"]))
	if opts.has("default_pos"):
		return opts.get("default_pos", CASCADE_START)
	var pos := CASCADE_START + CASCADE_STEP * float(_cascade_index)
	_cascade_index = (_cascade_index + 1) % CASCADE_WRAP
	return pos


func _remembered_open(id: String) -> bool:
	var entry: Dictionary = _layout.get(id, {})
	return bool(entry.get("open", false))


# ── Layout persistence (single owner of user://ui_layout.json) ────────────────

func _record_state(id: String) -> void:
	var window := get_ui_window(id)
	if window == null:
		return
	var entry: Dictionary = _layout.get(id, {})
	entry["x"] = window.position.x
	entry["y"] = window.position.y
	# Only persistent windows restore "open"; storing it for all is harmless
	# and keeps the writer branch-free (the reader filters, doc 24 §2).
	entry["open"] = window.visible
	_layout[id] = entry
	_save_layout()


func _load_layout() -> void:
	_layout_loaded = true
	if not FileAccess.file_exists(LAYOUT_PATH):
		return
	var file := FileAccess.open(LAYOUT_PATH, FileAccess.READ)
	if file == null:
		push_warning("UIWindowManager: cannot open %s — using default layout." % LAYOUT_PATH)
		return
	var json := JSON.new()
	var parse_err := json.parse(file.get_as_text())
	file.close()
	if parse_err != OK or not (json.data is Dictionary):
		push_warning("UIWindowManager: %s is corrupt — using default layout." % LAYOUT_PATH)
		return
	var root: Dictionary = json.data
	var windows_variant: Variant = root.get("windows", {})
	if not (windows_variant is Dictionary):
		push_warning("UIWindowManager: %s has no valid windows table — using defaults." % LAYOUT_PATH)
		return
	var windows: Dictionary = windows_variant
	for id_variant: Variant in windows.keys():
		var id := String(id_variant)
		var entry_variant: Variant = windows[id_variant]
		if not (entry_variant is Dictionary):
			continue
		var entry: Dictionary = entry_variant
		var clean: Dictionary = {}
		if entry.has("x") and entry.has("y"):
			clean["x"] = float(entry["x"])
			clean["y"] = float(entry["y"])
		clean["open"] = bool(entry.get("open", false))
		_layout[id] = clean


func _save_layout() -> void:
	if not _layout_loaded:
		return   # never clobber the file before it has been read
	var root: Dictionary = {
		"schema_version": LAYOUT_SCHEMA_VERSION,
		"windows": _layout,
	}
	var file := FileAccess.open(LAYOUT_PATH, FileAccess.WRITE)
	if file == null:
		push_warning("UIWindowManager: cannot write %s (error %d)." % [
			LAYOUT_PATH, FileAccess.get_open_error()])
		return
	file.store_string(JSON.stringify(root, "  "))
	file.close()

